class _MountedFlowEndPatch {
  const _MountedFlowEndPatch({
    required this.flow,
    required this.flowIndex,
    required this.notesByDay,
    required this.hadTotalCount,
    required this.totalCount,
    required this.hadRemainingCount,
    required this.remainingCount,
    required this.unconfirmedNotes,
  });

  final _Flow? flow;
  final int flowIndex;
  final Map<String, List<_Note>> notesByDay;
  final bool hadTotalCount;
  final int? totalCount;
  final bool hadRemainingCount;
  final int? remainingCount;
  final List<_UnconfirmedNote> unconfirmedNotes;
}

void _calendarDebugPrint(String? message, {int? wrapWidth}) {
  if (kDebugMode) {
    debugPrint(message, wrapWidth: wrapWidth);
  }
}

Future<void> _ensureSharedExperienceForFlow({
  required int flowId,
  required String? calendarId,
  required String source,
}) async {
  final trimmedCalendarId = calendarId?.trim();
  if (flowId <= 0 || trimmedCalendarId == null || trimmedCalendarId.isEmpty) {
    return;
  }
  try {
    await SharedPracticeRepo(
      Supabase.instance.client,
    ).ensureSharedExperienceForFlow(
      flowId: flowId,
      calendarId: trimmedCalendarId,
    );
  } catch (e) {
    if (kDebugMode) {
      _calendarDebugPrint(
        '[$source] shared experience ensure failed for flow=$flowId '
        'calendar=$trimmedCalendarId: $e',
      );
    }
  }
}

typedef QuickAddParse = ({
  DateTime date,
  bool allDay,
  TimeOfDay? start,
  TimeOfDay? end,
  String title,
  String? location,
});

@visibleForTesting
Future<T> beginOptimisticNoteEditorSave<T>({
  required Future<T> Function() startSave,
  required VoidCallback closeEditor,
}) {
  final save = startSave();
  closeEditor();
  return save;
}

class _QuickAddSheet extends StatefulWidget {
  const _QuickAddSheet({
    required this.parse,
    required this.onSave,
    required this.onOpenJournal,
    required this.onOpenPlanner,
    required this.onOpenFullEditor,
    required this.scaffoldMessengerContext,
  });

  final QuickAddParse? Function(String raw) parse;
  final Future<void> Function(QuickAddParse parsed, Color color) onSave;
  final VoidCallback onOpenJournal;
  final VoidCallback onOpenPlanner;
  final VoidCallback onOpenFullEditor;
  final BuildContext scaffoldMessengerContext;

  @override
  State<_QuickAddSheet> createState() => _QuickAddSheetState();
}

class _QuickAddSheetState extends State<_QuickAddSheet> {
  final TextEditingController _textCtrl = TextEditingController();
  final FocusNode _focusNode = FocusNode();
  final ScrollController _scrollCtrl = ScrollController();
  String? _error;
  bool _submitting = false;
  Color _selectedColor = daySheetColorPalette.first;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      unawaited(_requestInitialFocus());
    });
  }

  @override
  void dispose() {
    _focusNode.dispose();
    _textCtrl.dispose();
    _scrollCtrl.dispose();
    super.dispose();
  }

  Future<void> _requestInitialFocus() async {
    if (!mounted) return;
    _focusNode.requestFocus();
  }

  Future<void> _handleSubmit() async {
    if (_submitting) return;

    final parsed = widget.parse(_textCtrl.text);
    if (parsed == null) {
      setState(() {
        _error = 'Please enter a description.';
      });
      return;
    }

    setState(() {
      _error = null;
      _submitting = true;
    });

    final messenger = ScaffoldMessenger.maybeOf(
      widget.scaffoldMessengerContext,
    );
    final save = beginOptimisticNoteEditorSave<void>(
      startSave: () => widget.onSave(parsed, _selectedColor),
      closeEditor: () => Navigator.of(context).pop(),
    );
    messenger?.showSnackBar(
      SnackBar(
        content: Text('Added "${parsed.title}"'),
        backgroundColor: const Color(0xFF1E1E1E),
      ),
    );

    try {
      await save;
    } catch (e, st) {
      if (kDebugMode) {
        _calendarDebugPrint('[QuickAdd] Failed to save note: $e');
        _calendarDebugPrint('$st');
      }
      messenger?.showSnackBar(
        SnackBar(
          content: Text('Failed to save note: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  void _handleOpenDestination(VoidCallback onOpen) {
    _focusNode.unfocus();
    Navigator.of(context).pop();
    onOpen();
  }

  Widget _buildDestinationRow({
    required Key key,
    required String glyph,
    required String label,
    required VoidCallback onOpen,
  }) {
    final enabled = !_submitting;
    return Semantics(
      button: true,
      enabled: enabled,
      label: label,
      child: SizedBox(
        key: key,
        width: double.infinity,
        height: 34,
        child: InkWell(
          borderRadius: BorderRadius.circular(8),
          onTap: enabled ? () => _handleOpenDestination(onOpen) : null,
          child: Row(
            children: [
              SizedBox(
                width: 18,
                child: Center(child: KemeticGold.glyph(glyph, size: 16)),
              ),
              const SizedBox(width: 12),
              Text(
                label.toUpperCase(),
                style: TextStyle(
                  inherit: false,
                  color: enabled
                      ? const Color(0xFFD8D1C4)
                      : const Color(0xFF5A5449),
                  fontSize: 14.5,
                  fontWeight: FontWeight.w400,
                  fontFamily: DaySheetTokens.serif,
                  letterSpacing: 2.68,
                  height: 1,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final tone = _FlowStudioTone.resolve(_selectedColor);
    return KemeticKeyboardRevealScope(
      enabled: false,
      child: AnimatedPadding(
        duration: const Duration(milliseconds: 150),
        curve: Curves.easeOut,
        padding: EdgeInsets.only(
          bottom: MediaQuery.viewInsetsOf(context).bottom,
