final Map<String, _InlineNodeContent> _decanInlineNodes =
    _buildDecanInlineNodes();

List<KemeticNodeLink> _buildDecanNameLinks() {
  final links = <KemeticNodeLink>[];
  DecanMetadata.decanNames.forEach((_, names) {
    for (final name in names) {
      links.add(KemeticNodeLink(phrase: name, targetId: 'decan:$name'));
    }
  });
  return links;
}

Map<String, _InlineNodeContent> _buildDecanInlineNodes() {
  final map = <String, _InlineNodeContent>{};
  DecanMetadata.decanNames.forEach((month, names) {
    for (int i = 0; i < names.length; i++) {
      final idx = (month - 1) * 3 + i;
      if (idx < 0 || idx >= _decanInfo.length) continue;
      final short = names[i];
      final title = DecanMetadata.decanTitles[short] ?? short;
      map['decan:$short'] = _InlineNodeContent(
        id: 'decan:$short',
        title: title,
        body: _decanInfo[idx].trim(),
        glyph: '✶',
        linkMap: _decanLinkMap,
      );
    }
  });
  return map;
}

/* ─────────── Gloss helpers ─────────── */

class _Glossy extends StatelessWidget {
  final Widget child;
  final Gradient gradient;
  const _Glossy({required this.child, required this.gradient});
  @override
  Widget build(BuildContext context) {
    return ShaderMask(
      shaderCallback: (Rect bounds) => gradient.createShader(bounds),
      blendMode: BlendMode.srcIn,
      child: child,
    );
  }
}

// GlossyText is now imported from shared/glossy_text.dart as GlossyText

// --- Month header rendering helper (crisp + glossy) ---
class _GlossyMonthNameText extends StatelessWidget {
  final String text;
  final TextStyle? style;
  final Gradient gradient;

  const _GlossyMonthNameText({
    required this.text,
    required this.gradient,
    this.style,
  });

  @override
  Widget build(BuildContext context) {
    final s = style ?? const TextStyle();
    final double fs = (s.fontSize ?? 20.0);
    final bool small = fs < 18.0;

    // White base for mask happens inside MonthNameText via color override here.
    final TextStyle masked = s.copyWith(
      color: const Color(0xFFFFFFFF),
      fontSize: fs.roundToDouble(),
      letterSpacing: 0,
      height: s.height,
      // keep caller's family; MonthNameText merges canonical stack
      fontFamily: s.fontFamily,
      fontFamilyFallback: s.fontFamilyFallback,
      // Gate shadows: small text + mask + shadows = mush
      shadows: small ? null : s.shadows,
    );

    return RepaintBoundary(
      child: ShaderMask(
        shaderCallback: (Rect r) => gradient.createShader(r),
        blendMode: BlendMode.srcIn,
        child: MonthNameText(
          text,
          style: masked,
          softWrap: false,
          maxLines: 1,
          overflow: TextOverflow.fade,
          textAlign: TextAlign.center,
        ),
      ),
    );
  }
}

class _GlossyIcon extends StatelessWidget {
  final IconData icon;
  final Gradient gradient;
  const _GlossyIcon(this.icon, {required this.gradient});
  @override
  Widget build(BuildContext context) {
    return ShaderMask(
      shaderCallback: (bounds) => gradient.createShader(bounds),
      blendMode: BlendMode.srcIn,
      child: Icon(icon, color: Colors.white),
    );
  }
}

class _GlossyDot extends StatelessWidget {
  final Gradient gradient;
  const _GlossyDot({required this.gradient});
  @override
  Widget build(BuildContext context) {
    return _Glossy(
      gradient: gradient,
      child: Container(
        width: 4.5,
        height: 4.5,
        decoration: const BoxDecoration(
          color: Colors.white,
          shape: BoxShape.circle,
        ),
      ),
    );
  }
}

const int _kActionGridColumns = 3;
const double _kActionTileWidth = 96.0;
const double _kActionTileHeight = 96.0;
const double _kActionGridSpacing = 12.0;
const double _kActionGridHPadding = 12.0;
const double _kActionGridVPadding = 12.0;
const Key _kCalendarActionsMenuPanelKey = ValueKey(
  'calendar-actions-menu-panel',
);
const Key _kCalendarActionsGridKey = ValueKey('calendar-actions-grid');

bool _isLandscapeMenu(BuildContext context) =>
    MediaQuery.orientationOf(context) == Orientation.landscape;

double _landscapeMenuPanelWidth(BuildContext context) {
  const double defaultGridWidth =
      _kActionGridHPadding * 2 +
      _kActionGridColumns * _kActionTileWidth +
      (_kActionGridColumns - 1) * _kActionGridSpacing;
  final screenWidth = MediaQuery.sizeOf(context).width;
  return math.min(defaultGridWidth, screenWidth * 0.82);
}

double _landscapeMenuMaxGridHeight(
  BuildContext context, {
  required double bottomInset,
}) {
  final media = MediaQuery.of(context);
  const handleChrome = 10.0 + 3.0 + 8.0;
  final targetPanelHeight = media.size.height * 0.80;
  return math.max(96.0, targetPanelHeight - handleChrome - bottomInset);
}

class _CalendarAction {
