class _NotificationDotOverlay extends StatelessWidget {
  final Widget child;
  final bool show;
  final double top;
  final double right;

  const _NotificationDotOverlay({
    required this.child,
    required this.show,
    this.top = -2,
    this.right = -2,
  });

  @override
  Widget build(BuildContext context) {
    return Stack(
      clipBehavior: Clip.none,
