  // Headless persistence helper: save/delete flows + planned notes without calendar state.
  static Future<int?> _persistFlowStudioResultHeadless(
    _FlowStudioResult r,
  ) async {
    final userEventsRepo = UserEventsRepo(Supabase.instance.client);

    // Deletes
    final deleteId = r.deleteFlowId;
    if (deleteId != null) {
      await userEventsRepo.deleteByFlowId(deleteId);
      await userEventsRepo.deleteFlow(deleteId);
      _publishHeadlessCalendarInvalidation(
        reason: CalendarInvalidationReason.flowDeleted,
        flowId: deleteId,
        clientEventIds: const <String>[],
      );
      return deleteId;
    }

    // Saves
    if (r.savedFlow == null) return null;
    final f = r.savedFlow!;
    final isNewFlowSave = r.completionRequired;
    final opensDayView = _shouldOpenDayViewAfterFlowStudioAdd(r);
    final rulesJson = jsonEncode(
      f.rules.map(CalendarPageState.ruleToJson).toList(),
    );

    final savedId = await userEventsRepo.upsertFlow(
      id: f.id > 0 ? f.id : null,
      name: f.name,
      color: f.color.toARGB32(),
      active: f.active,
      calendarId: f.calendarId,
      startDate: f.start,
      endDate: f.end,
      notes: f.notes,
      rules: rulesJson,
      isHidden: f.isHidden,
      isSaved: f.isSaved,
      originType: r.originType,
      originFlowId: r.originFlowId,
      originShareId: r.originShareId ?? f.shareId,
      originGenerationId: r.originGenerationId,
      rootFlowId: r.rootFlowId,
      aiMetadata: r.aiMetadata,
    );

    final localFlow = _savedFlowForStudioResult(f, savedId);
    bool generationCommitted = false;

    Future<void> commitGenerationIfNeeded() async {
      if (generationCommitted || r.originGenerationId == null) return;
      generationCommitted = true;
      try {
        await userEventsRepo.flowCommit(
          generationId: r.originGenerationId!,
          flowId: savedId,
        );
      } catch (e) {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[persistFlowStudioHeadless] flow_commit failed for generation ${r.originGenerationId}: $e',
          );
        }
      }
    }

    if (r.plannedNotes.isNotEmpty) {
      if (!isNewFlowSave) {
        await userEventsRepo.deleteByFlowId(
          savedId,
          semantic: 'flow_replace',
          suppressesClient: false,
          sourceFeature: 'CalendarPage._persistFlowStudioResultHeadless',
          deleteScope: 'planned_flow_replace',
        );
      }
      final writes = <PlannedNoteWrite>[
        for (final planned in r.plannedNotes)
          CalendarPage._flowStudioPlannedNoteWrite(
            planned: planned,
            localFlow: localFlow,
            calendarName: null,
            persistedDetail: (planned.note.detail ?? '').trim().isEmpty
                ? null
                : planned.note.detail,
            caller: 'flow_studio_headless_deferred',
          ),
      ];
      final firstClientEventId = writes.first.clientEventId;
      final staged = FlowJoinService(userEventsRepo: userEventsRepo)
          .stagePlannedNotesAndDeferPersist(
            flowId: savedId,
            localFlow: localFlow,
            writes: writes,
            invalidationReason: CalendarInvalidationReason.flowStudioPersisted,
            additionalPersistence: () async {
              await commitGenerationIfNeeded();
              await _ensureSharedExperienceForFlow(
                flowId: savedId,
                calendarId: f.calendarId,
                source: 'CalendarPage._persistFlowStudioResultHeadless',
              );
              if (isNewFlowSave) {
                try {
                  await SharedCalendarsRepo(
                    Supabase.instance.client,
                  ).notifySharedCalendarItemAdded(
                    calendarId: f.calendarId,
                    itemType: 'flow',
                    itemId: savedId.toString(),
                    itemTitle: f.name,
                    clientEventId: firstClientEventId,
                    flowId: savedId,
                    startDate: f.start,
                    endDate: f.end,
                  );
                } catch (error, stackTrace) {
                  if (kDebugMode) {
                    _calendarDebugPrint(
                      '[persistFlowStudioHeadless] shared notification failed: '
                      '$error',
                    );
                    _calendarDebugPrint('$stackTrace');
                  }
                }
              }
            },
          );
      final persist = staged.persistInBackground;
      if (persist == null || staged._plannedNotes.isEmpty) {
        throw StateError('Flow $savedId did not produce staged notes.');
      }
      _stageFlowForDeferredPersistence(
        _PendingStagedFlow(
          flowId: savedId,
          localFlow: localFlow,
          plannedNotes: staged._plannedNotes,
          persist: persist,
          completionRequired: opensDayView,
          rollback: (state) async {
            if (!isNewFlowSave) {
              if (state != null) {
                await state._requestHydration(
                  _CalendarHydrationRequest.catalogReconcile(
                    reason: 'flow_studio_edit_persist_failure',
                  ),
                );
              } else {
                _publishHeadlessCalendarInvalidation(
                  reason: CalendarInvalidationReason.flowStudioPersisted,
                  flowId: savedId,
                  clientEventIds: const <String>[],
                );
              }
              return;
            }
            if (state != null) {
              await state._rollbackStagedFlowLocally(
                savedId,
                repo: userEventsRepo,
                failureMessage: 'Could not create ${f.name}.',
              );
              return;
            }
            try {
              await userEventsRepo.deleteByFlowId(
                savedId,
                semantic: 'flow_save_rollback',
                suppressesClient: false,
                sourceFeature: 'CalendarPage._persistFlowStudioResultHeadless',
                deleteScope: 'failed_new_flow_save',
              );
            } catch (_) {}
            try {
              await userEventsRepo.deleteFlow(savedId);
            } catch (_) {}
          },
        ),
      );
      _mountedState?._applyPendingStagedFlow(savedId);

      // Persistence is independent of UI completion. The route owner arms
      // and consumes Day View after this method returns.
      _startStagedFlowPersistence(savedId);
      return savedId;
    }

    await commitGenerationIfNeeded();
    await _ensureSharedExperienceForFlow(
      flowId: savedId,
      calendarId: f.calendarId,
      source: 'CalendarPage._persistFlowStudioResultHeadless',
    );
    if (isNewFlowSave) {
      await SharedCalendarsRepo(
        Supabase.instance.client,
      ).notifySharedCalendarItemAdded(
        calendarId: f.calendarId,
        itemType: 'flow',
        itemId: savedId.toString(),
        itemTitle: f.name,
        flowId: savedId,
        startDate: f.start,
        endDate: f.end,
      );
    }
    _publishHeadlessCalendarInvalidation(
      reason: CalendarInvalidationReason.flowStudioPersisted,
      flowId: savedId,
      clientEventIds: const <String>[],
    );
    return savedId;
  }

  static List<FlowRule> _parseImportedFlowRules(List<dynamic> rawRules) {
    final rules = <FlowRule>[];
    for (final raw in rawRules) {
      if (raw is FlowRule) {
        rules.add(raw);
      } else if (raw is Map) {
        try {
          rules.add(ruleFromJson(Map<String, dynamic>.from(raw)));
        } catch (_) {
          // Keep parsing the remaining valid rules.
        }
      }
    }
    return rules;
  }

  static DateTime _sharedImportEndDate({
    required DateTime startDate,
    required List<dynamic> events,
    required List<FlowRule> rules,
    DateTime? requestedEndDate,
  }) {
    if (requestedEndDate != null) return DateUtils.dateOnly(requestedEndDate);
    var maxOffset = 0;
    for (final raw in events) {
      if (raw is! Map) continue;
      final offset = (raw['offset_days'] as num?)?.toInt() ?? 0;
      if (offset > maxOffset) maxOffset = offset;
    }
    if (events.isNotEmpty) {
      return _addLocalCalendarDays(startDate, maxOffset);
    }
    if (rules.isNotEmpty) {
      return _addLocalCalendarDays(startDate, 90);
    }
    return startDate;
  }

  /// Imports a shared flow directly into the universal staged-write pipeline.
  /// The route owner supplies completion so mounted and detached surfaces close
  /// themselves correctly; persistence begins before that callback runs.
  static Future<({int flowId, bool didStageEvents})?> importFlowFromShare(
    ImportFlowData data, {
    required FlowAddCompletion completeAdd,
  }) async {
    final rawEvents =
        data.share.payloadJson?['events'] as List<dynamic>? ?? const [];
    final rules = _parseImportedFlowRules(data.rules);
    if (rawEvents.isEmpty && rules.isEmpty) {
      throw StateError('Shared flow has no events or materializable rules.');
    }

    final startDate = DateUtils.dateOnly(
      data.suggestedStartDate ?? DateTime.now(),
    );
    final endDate = _sharedImportEndDate(
      startDate: startDate,
      events: rawEvents,
      rules: rules,
      requestedEndDate: data.suggestedEndDate,
    );
    final calendarId =
        data.calendarId ??
        _mountedState?._personalCalendarId ??
        await _loadHeadlessPersonalCalendarId();
    final repo = UserEventsRepo(Supabase.instance.client);
    final savedId = await repo.upsertFlow(
      name: data.name,
      color: data.color,
      active: true,
      calendarId: calendarId,
      startDate: startDate,
      endDate: endDate,
      notes: data.notes,
      rules: jsonEncode(const <dynamic>[]),
      isSaved: false,
      shareId: data.share.shareId,
      originType: data.originType ?? 'share_import',
      originFlowId: data.originFlowId,
      originShareId: data.share.shareId,
      originGenerationId: data.generationId,
      rootFlowId: data.rootFlowId,
      aiMetadata: data.aiMetadata,
    );
    final localFlow = _Flow(
      id: savedId,
      calendarId: calendarId,
      name: data.name,
      color: Color(data.color),
      active: true,
      isSaved: false,
      rules: const <FlowRule>[],
      start: startDate,
      end: endDate,
      notes: data.notes,
      shareId: data.share.shareId,
    );

    final writes = rawEvents.isNotEmpty
        ? materializeFlowSnapshotWrites(
            flowId: savedId,
            events: rawEvents,
            startDate: startDate,
            fallbackTitle: data.name,
            calendarId: calendarId,
            calendarName: data.calendarName,
            manualColor: Color(data.color),
            caller: 'shared_flow_import_snapshot',
            alertDebugLabel: 'sharedFlowImportSnapshot',
          )
        : materializeFlowRuleWrites(
            flowId: savedId,
            rules: rules,
            startDate: startDate,
            endDate: endDate,
            title: data.name,
            notes: data.notes,
            calendarId: calendarId,
            calendarName: data.calendarName,
            manualColor: Color(data.color),
            caller: 'shared_flow_import_rules',
            alertDebugLabel: 'sharedFlowImportRules',
          );
    final dedupedWrites = <String, PlannedNoteWrite>{
      for (final write in writes) write.clientEventId: write,
    }.values.toList(growable: false);
    if (dedupedWrites.isEmpty) {
      try {
        await repo.deleteFlow(savedId);
      } catch (_) {}
      throw StateError('Shared flow did not produce calendar events.');
    }

    final firstClientEventId = dedupedWrites.first.clientEventId;
    final staged = FlowJoinService(userEventsRepo: repo)
        .stagePlannedNotesAndDeferPersist(
          flowId: savedId,
          localFlow: localFlow,
          writes: dedupedWrites,
          invalidationReason: CalendarInvalidationReason.flowStudioPersisted,
          additionalPersistence: () async {
            if (data.generationId != null) {
              try {
                await repo.flowCommit(
                  generationId: data.generationId!,
                  flowId: savedId,
                );
              } catch (_) {}
            }
            await _ensureSharedExperienceForFlow(
              flowId: savedId,
              calendarId: calendarId,
              source: 'CalendarPage.importFlowFromShare',
            );
            try {
              await SharedCalendarsRepo(
                Supabase.instance.client,
              ).notifySharedCalendarItemAdded(
                calendarId: calendarId,
                itemType: 'flow',
                itemId: savedId.toString(),
                itemTitle: data.name,
                clientEventId: firstClientEventId,
                flowId: savedId,
                startDate: startDate,
                endDate: endDate,
              );
            } catch (_) {}
          },
        );
    final persist = staged.persistInBackground;
    if (persist == null || staged._plannedNotes.isEmpty) {
      try {
        await repo.deleteFlow(savedId);
      } catch (_) {}
      throw StateError('Shared flow could not stage calendar events.');
    }
    _stageFlowForDeferredPersistence(
      _PendingStagedFlow(
        flowId: savedId,
        localFlow: localFlow,
        plannedNotes: staged._plannedNotes,
        persist: persist,
        completionRequired: true,
        rollback: (state) async {
          if (state != null) {
            await state._rollbackStagedFlowLocally(
              savedId,
              repo: repo,
              failureMessage: 'Could not import ${data.name}.',
            );
            return;
          }
          try {
            await repo.deleteByFlowId(
              savedId,
              semantic: 'flow_save_rollback',
              suppressesClient: false,
              sourceFeature: 'CalendarPage.importFlowFromShare',
              deleteScope: 'failed_shared_flow_import',
            );
          } catch (_) {}
          try {
            await repo.deleteFlow(savedId);
          } catch (_) {}
        },
      ),
    );
    _mountedState?._applyPendingStagedFlow(savedId);
    _startStagedFlowPersistence(savedId);
    await Future<void>.sync(() => completeAdd(savedId));
    return (flowId: savedId, didStageEvents: true);
  }

  static Future<({int flowId, bool didStageEvents})?>
  importGeneratedFlowFromAnyContext({
    required AIFlowGenerationResponse response,
    required DateTime baseStart,
    required FlowAddCompletion completeAdd,
  }) async {
    final data = _importDataFromAiGenerationResponse(response, baseStart);
    if (data == null) return null;
    return importFlowFromShare(data, completeAdd: completeAdd);
  }

  static void completeRootRouteStagedFlowAdd(BuildContext context, int flowId) {
    _armStagedFlowDayView(flowId);
    if (context.mounted) {
      context.go('/');
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _mountedState?._schedulePendingStagedFlowDayViewIfAny();
    });
  }

  static ImportFlowData? _importDataFromAiGenerationResponse(
    AIFlowGenerationResponse response,
    DateTime baseStart,
  ) {
    try {
      final events = buildAiFlowImportEvents(response);
      if (events.isEmpty) return null;

      final now = DateTime.now();
      final share = InboxShareItem(
        shareId: 'ai-local-${now.millisecondsSinceEpoch}',
        kind: InboxShareKind.flow,
        recipientId: '',
        senderId: '',
        payloadId: 'ai-local',
        title: response.flowName ?? 'AI Flow',
        createdAt: now,
        payloadJson: {'events': events},
      );

      final cleaned = (response.flowColor ?? '#4dd0e1').replaceFirst('#', '');
      final rgb = int.tryParse(cleaned, radix: 16) ?? 0x4dd0e1;

      return ImportFlowData(
        share: share,
        name: response.flowName ?? 'AI Flow',
        color: 0xFF000000 | rgb,
        notes: response.notes,
        rules: const [],
        suggestedStartDate: baseStart,
        suggestedEndDate: response.requestedEndDate,
        overview: response.overviewSummary ?? response.overviewTitle ?? '',
        generationId: response.generationId,
        originType: 'ai',
        originFlowId: response.flowId,
        rootFlowId: response.flowId,
        aiMetadata: response.aiMetadata,
      );
    } catch (_) {
      return null;
    }
  }

  @override
  State<CalendarPage> createState() => CalendarPageState();
}

class _FlowStudioRoutePage extends StatefulWidget {
  const _FlowStudioRoutePage({this.routeUri});

  final Uri? routeUri;

  @override
  State<_FlowStudioRoutePage> createState() => _FlowStudioRoutePageState();
}

class _FlowStudioRoutePageState extends State<_FlowStudioRoutePage> {
  final GlobalKey<NavigatorState> _flowStudioNavigatorKey =
      GlobalKey<NavigatorState>();
  late final FlowsRepo _flowsRepo = FlowsRepo(Supabase.instance.client);
  bool _routeCloseRequested = false;

  void _closeRoute() {
    if (!mounted || _routeCloseRequested) return;
    _routeCloseRequested = true;
    RestorationCoordinator.instance.suppressRestoreForUserNavigation(
      reason: 'flow_studio_route_close',
    );
    unawaited(CalendarPage._clearFlowStudioTransientState());
    closeOrReturn(context, '/');
  }

  void _returnToFlowStudioHubRoute() {
    if (!mounted) return;
    final uri = GoRouter.of(context).routerDelegate.currentConfiguration.uri;
    if (uri.path == '/flows' && uri.queryParameters.isNotEmpty) {
      context.go('/flows');
    }
  }

  bool _handleSystemBack() {
    final nestedNavigator = _flowStudioNavigatorKey.currentState;
    if (nestedNavigator != null && nestedNavigator.canPop()) {
      nestedNavigator.pop();
      return true;
    }
    return false;
  }

  @override
  Widget build(BuildContext context) {
    final restorationState = CalendarPage._flowStudioRouteStateFromUri(
      widget.routeUri,
    );
    return UtilitySheetRouteScaffold(
      semanticLabel: 'Flow Studio',
      onClose: _closeRoute,
      onBackPressed: _handleSystemBack,
      showRouteChrome: false,
      heightFactor: 1,
      topRadius: 0,
      child: Navigator(
        key: _flowStudioNavigatorKey,
        onGenerateInitialRoutes: (navigator, initial) =>
            CalendarPage._detachedFlowStudioInitialRoutes(
              parentRoute: '/flows',
              flowsRepo: _flowsRepo,
              restorationState: restorationState,
              onClose: _closeRoute,
              onReturnToHub: _returnToFlowStudioHubRoute,
            ),
      ),
    );
  }
}

