class _FlowEditorRoutePage extends StatefulWidget {
  const _FlowEditorRoutePage({
    required this.flowId,
    this.calendarId,
    this.fallbackLocation,
  });

  final int flowId;
  final String? calendarId;
  final String? fallbackLocation;

  @override
  State<_FlowEditorRoutePage> createState() => _FlowEditorRoutePageState();
}

class _FlowEditorRoutePageState extends State<_FlowEditorRoutePage> {
  late final Future<_Flow?> _readingHouseRouteFlowFuture;
  bool _persisting = false;

  String get _fallbackLocation =>
      CalendarPage._validFlowEditorFallbackLocation(widget.fallbackLocation) ??
      '/shared-flow/by-flow/${widget.flowId}';

  @override
  void initState() {
    super.initState();
    _readingHouseRouteFlowFuture = _loadReadingHouseRouteFlow();
    if (kDebugMode) {
      debugPrint(
        '[EditFlow] open studio source=route flowId=${widget.flowId} calendarId=${widget.calendarId}',
      );
    }
  }

  Future<_Flow?> _loadReadingHouseRouteFlow() async {
    final mountedHost = CalendarPage._mountedState;
    _Flow? mountedFlow;
    for (final flow in mountedHost?._flows ?? const <_Flow>[]) {
      if (flow.id == widget.flowId) {
        mountedFlow = flow;
        break;
      }
    }
    final flow =
        mountedFlow ??
        CalendarPage._flowFromFiledRowDetached(
          await FlowsRepo(
            Supabase.instance.client,
          ).getFlowById(widget.flowId).then((row) {
            if (row == null) {
              throw StateError('Flow ${widget.flowId} was not found.');
            }
            return row;
          }),
        );
    if (widget.calendarId != null && widget.calendarId!.trim().isNotEmpty) {
      flow.calendarId = widget.calendarId!.trim();
    }
    if (resolveMaatFlowKind(flowNotes: flow.notes) ==
            MaatFlowKind.readingHouse ||
        isReadingHouseFlowReference(
          flowName: flow.name,
          flowNotes: flow.notes,
        )) {
      return flow;
    }
    return null;
  }

  Future<void> _handleResult(_FlowStudioResult result) async {
    if (_persisting) return;
    setState(() => _persisting = true);
    try {
      final mountedHost = CalendarPage._mountedState;
      if (mountedHost != null) {
        await mountedHost._persistFlowStudioResult(result);
        await mountedHost._requestHydration(
          _CalendarHydrationRequest.catalogReconcile(
            reason: 'flow_editor_route',
          ),
        );
      } else {
        await CalendarPage._persistFlowStudioResultHeadless(result);
      }
      if (!mounted) return;
      popOrGo(context, _fallbackLocation, result: true);
    } catch (error, stackTrace) {
      if (kDebugMode) {
        debugPrint('[EditFlow] failed error=$error');
        debugPrint('$stackTrace');
      }
      if (!mounted) return;
      setState(() => _persisting = false);
      Error.throwWithStackTrace(error, stackTrace);
    }
  }

  Future<void> _handleClose() async {
    if (!mounted) return;
    await CalendarPage._clearFlowStudioTransientState();
    if (!mounted) return;
    popOrGo(context, _fallbackLocation);
  }

  Widget _buildGenericFlowEditor() {
    return _FlowStudioPage(
      existingFlows: const <_Flow>[],
      editFlowId: widget.flowId,
      initialCalendarId: widget.calendarId,
      onRouteResult: _handleResult,
      onRouteClose: _handleClose,
    );
  }

  Widget _buildReadingHouseAuthoringPage(_Flow flow) {
    final mountedHost = CalendarPage._mountedState;
    final sharedCalendarsRepo =
        mountedHost?._sharedCalendarsRepo ??
        SharedCalendarsRepo(Supabase.instance.client);
    return _ReadingHouseAuthoringPage(
      flow: flow,
      calendar: mountedHost?._calendarSummary(flow.calendarId),
      personalCalendarId: mountedHost?._personalCalendarId,
      sharedCalendarsRepo: sharedCalendarsRepo,
      onCalendarChanged: mountedHost?._moveReadingHouseFlowToCalendar,
      onSave: _handleResult,
    );
  }

  @override
  Widget build(BuildContext context) {
    return Stack(
      children: [
        FutureBuilder<_Flow?>(
          future: _readingHouseRouteFlowFuture,
          builder: (context, snapshot) {
            if (snapshot.connectionState != ConnectionState.done) {
              return const Scaffold(
                backgroundColor: Color(0xFF161310),
                body: Center(
                  child: CircularProgressIndicator(color: Color(0xFFE0B95A)),
                ),
              );
            }
            if (snapshot.hasError) {
              if (kDebugMode) {
                debugPrint(
                  '[EditFlow] Reading House route detection failed; falling back to generic editor: ${snapshot.error}',
                );
              }
              return _buildGenericFlowEditor();
            }
            final readingHouseFlow = snapshot.data;
            if (readingHouseFlow != null) {
              return _buildReadingHouseAuthoringPage(readingHouseFlow);
            }
            return _buildGenericFlowEditor();
          },
        ),
        if (_persisting)
          const Positioned.fill(
            child: ColoredBox(
              color: Color(0x99000000),
              child: Center(
                child: CircularProgressIndicator(color: Color(0xFFE0B95A)),
              ),
            ),
          ),
      ],
    );
  }
}

class CalendarPageState extends State<CalendarPage>
    with WidgetsBindingObserver, RouteAware {
  static const Duration _foregroundRefreshThreshold = Duration(minutes: 10);
  static const Duration _restorationWriteDebounce = Duration(milliseconds: 150);
  late final CalendarHydrationScheduler _hydrationScheduler =
      CalendarHydrationScheduler(
        isMounted: () => mounted,
        debugLog: _calendarDebugPrint,
      );
  late final CalendarHydrationController _hydrationController =
      CalendarHydrationController(
        scheduler: _hydrationScheduler,
        onStateChanged: _handleHydrationControllerStateChanged,
      );
  late final CalendarHydrationInvalidationBridge _hydrationInvalidationBridge =
      CalendarHydrationInvalidationBridge(
        onInvalidation: _handleTypedCalendarInvalidation,
        isMounted: () => mounted,
        isDeferred: () => _sharedCalendarRealDayViewOpening,
      );
  int _hydrationPassEpoch = 0;
  final _UnconfirmedNoteLedger _unconfirmed = _UnconfirmedNoteLedger();
  final PendingCalendarNoteStore _pendingNoteStore = PendingCalendarNoteStore();
  final Set<String> _pendingCidVerificationInFlight = <String>{};
  String? _pendingNotesRestoredForUserId;
  Future<void>? _pendingNotesRestoreInFlight;
  String? _pendingNotesRestoreInFlightForUserId;
  // Startup coordinator: single-flight gate for auth-triggered startup work.
  Completer<void>? _startupFlight;
  bool _startupRerunRequested = false;
  String? _startupLastReason;
  Timer? _startupRecoveryTimer;
  int _startupRecoveryAttempt = 0;
  bool _pendingInitialHydration = false;
  String? _initialStartupUserId;
  // Narrower initial window for faster startup; flows can still widen it.
  static const int _standaloneHydrationWindowYears = 1;
  static const Duration _standaloneHydrationPadding = Duration(days: 30);
  static const String _kWarmStartCacheKeyPrefix = 'calendar:warm_start:v1';
  static const Duration _warmStartCacheDebounce = Duration(milliseconds: 600);
  static const int _warmStartCacheMaxChars = 850000;
  static const Duration _warmStartWidePast = Duration(days: 120);
  static const Duration _warmStartWideFuture = Duration(days: 365);
  static const Duration _warmStartBoundedPast = Duration(days: 30);
  static const Duration _warmStartBoundedFuture = Duration(days: 60);
  static const Duration _warmStartNearPast = Duration(days: 7);
  static const Duration _warmStartNearFuture = Duration(days: 14);

  int _dataVersion = 0;
  int _calendarProjectionMutationRevision = 0;
  bool _monthHydrationFirstFrameRecorded = false;
  bool _monthHydrationFrameScheduled = false;
  Timer? _viewportHydrationDebounce;
  final ValueNotifier<int> _dayViewDataVersion = ValueNotifier<int>(0);
  final ValueNotifier<int> _dayViewHydrationActivation = ValueNotifier<int>(0);
  CalendarRefreshState _calendarRefreshState = CalendarRefreshState.initial;
  final ValueNotifier<DayViewSheetEventTarget?> _dayViewEventDetailRequest =
      ValueNotifier<DayViewSheetEventTarget?>(null);
  Timer? _warmStartCacheDebounceTimer;
  Future<void> _warmStartCacheWriteTail = Future<void>.value();
  Future<void> _calendarSnapshotWriteTail = Future<void>.value();
  String? _lastCalendarSnapshotShadowOutcome;
  @visibleForTesting
  String? get debugCalendarSnapshotShadowOutcome =>
      _lastCalendarSnapshotShadowOutcome;
  String? _warmStartCacheRestoredForUserId;
  CalendarHydrationAuthorityScope get _hydrationAuthorityScope {
    final authority = _hydrationController.state.authority;
    if (authority == CalendarViewportAuthority.fullHorizon) {
      return CalendarHydrationAuthorityScope.fullHorizon;
    }
    if (authority == CalendarViewportAuthority.viewportRefreshed ||
        authority == CalendarViewportAuthority.serverCurrent) {
      return CalendarHydrationAuthorityScope.visibleWindow;
    }
    return CalendarHydrationAuthorityScope.none;
  }

