  void _bumpDataVersion({bool scheduleCacheSave = true}) {
    // why: force landscape PageView child to reconstruct once when data hydrates
    if (!mounted) return;
    setState(() => _dataVersion++);
    _notifyDayViewDataChanged(scheduleCacheSave: scheduleCacheSave);
  }

  void _notifyDayViewDataChanged({bool scheduleCacheSave = true}) {
    if (!mounted) return;
    _calendarProjectionMutationRevision++;
    _dayViewDataVersion.value++;
    _publishWarmStateSnapshot();
    _scheduleMonthHydrationFrame();
    if (scheduleCacheSave &&
        shouldScheduleCacheSaveOnDataBump(_hydrationAuthorityScope)) {
      _scheduleWarmStartCacheSave();
    }
  }

  void _setHydrationAuthorityScope(
    CalendarHydrationAuthorityScope scope, {
    required String reason,
    HydrationDiagnosticContext? diagnosticContext,
  }) {
    if (scope == CalendarHydrationAuthorityScope.visibleWindow) {
      _warmStartCacheDebounceTimer?.cancel();
      _warmStartCacheDebounceTimer = null;
    }
    CalendarHydrationDiagnostics.instance.recordPostProcessing(
      diagnosticContext,
      'authority_scope_changed',
      fields: <String, Object?>{
        'authority_scope': scope.diagnosticName,
        'reason': reason,
      },
    );
  }

  void _publishCalendarRefreshState() {
    if (!mounted) return;
    final viewport = _hydrationController.state.viewport;
    final activeCoverage = _activeCalendarCoverage;
    final visibleViewportComplete =
        viewport == null ||
        (activeCoverage != null && activeCoverage.covers(viewport));
    final hasUsableSnapshot =
        activeCoverage != null ||
        _warmStartSnapshotVisible ||
        _serverHydrationCommittedForUserId != null ||
        _flows.isNotEmpty ||
        _notes.isNotEmpty;
    final next = CalendarRefreshState(
      visibleViewportComplete: visibleViewportComplete,
      lastSuccessfulRefreshAtUtc: _lastAuthoritativeHydrationAt?.toUtc(),
      latestRefreshStatus: _latestCalendarRefreshStatus,
      hasUsableSnapshot: hasUsableSnapshot,
    );
    _calendarRefreshState = next;
  }

  void _recordCalendarRefreshFailure() {
    if (!mounted) return;
    _latestCalendarRefreshStatus = CalendarRefreshStatus.failed;
    _publishCalendarRefreshState();
  }

  void _handleHydrationControllerStateChanged(
    CalendarHydrationControllerState state,
    String reason,
  ) {
    CalendarHydrationDiagnostics.instance.setCalendarFrameContext(
      <String, Object?>{
        'session_generation': state.sessionGeneration,
        'viewport_revision': state.viewportRevision,
        'viewport_start_utc': state.viewport?.startUtc.toIso8601String(),
        'viewport_end_utc': state.viewport?.endUtc.toIso8601String(),
        'catalog_fingerprint': state.catalogFingerprint,
        'authority_state': state.authority.diagnosticName,
        'confirmed_coverage': <Object?>[
          for (final interval in state.coverage.intervals)
            <String, Object?>{
              'start_utc': interval.startUtc.toIso8601String(),
              'end_utc': interval.endUtc.toIso8601String(),
            },
        ],
        'stale': state.stale,
      },
    );
    final legacyScope = state.authority == CalendarViewportAuthority.fullHorizon
        ? CalendarHydrationAuthorityScope.fullHorizon
        : state.authority == CalendarViewportAuthority.viewportRefreshed ||
              state.authority == CalendarViewportAuthority.serverCurrent
        ? CalendarHydrationAuthorityScope.visibleWindow
        : CalendarHydrationAuthorityScope.none;
    _setHydrationAuthorityScope(legacyScope, reason: reason);
    CalendarHydrationDiagnostics.instance.recordPostProcessing(
      null,
      'hydration_controller_state_changed',
      fields: <String, Object?>{
        'authority_state': state.authority.diagnosticName,
        'catalog_fingerprint': state.catalogFingerprint,
        'fresh_catalog_fingerprint': state.freshCatalogFingerprint,
        'viewport_revision': state.viewportRevision,
        'stale': state.stale,
        'reason': reason,
      },
    );
    _publishCalendarRefreshState();
  }

  Future<bool> _handleTypedCalendarInvalidation(
    CalendarInvalidated invalidation,
  ) async {
    final disposition = await _requestHydration(
      _CalendarHydrationRequest.catalogReconcile(
        reason: 'invalidation_${invalidation.reason.name}',
      ),
    );
    return disposition == CalendarHydrationJobDisposition.completed;
  }

  Future<CalendarHydrationJobDisposition> _refreshVisibleViewport({
    required String reason,
    required CalendarHydrationInterval interval,
  }) async {
    final provisional = await _requestHydration(
      _CalendarHydrationRequest.provisionalViewport(
        reason: reason,
        interval: interval,
      ),
    );
    if (provisional != CalendarHydrationJobDisposition.completed ||
        !mounted ||
        _hydrationController.state.viewport != interval) {
      return provisional;
    }
    final state = _hydrationController.state;
    if (state.authority == CalendarViewportAuthority.serverCurrent ||
        state.authority == CalendarViewportAuthority.fullHorizon) {
      return provisional;
    }
    return _requestHydration(
      _CalendarHydrationRequest.catalogReconcile(
        reason: '${reason}_fresh_catalog',
        interval: interval,
      ),
    );
  }

  HydrationSelectedDaySnapshot _hydrationSelectedDaySnapshot(
    Map<String, List<_Note>> notesByDay,
  ) {
    final fallbackKy = _lastViewKy ?? _today.kYear;
    final fallbackKm = _lastViewKm ?? _today.kMonth;
    final fallbackKd = _lastViewKd ?? _today.kDay;
    final activeDayView = _activeDayViewRestorationState;
    final selectedDay = selectHydrationDiagnosticDay(
      fallbackKYear: fallbackKy,
      fallbackKMonth: fallbackKm,
      fallbackKDay: fallbackKd,
      activeDayViewOpen: activeDayView?.isOpen ?? false,
      activeKYear: activeDayView?.kYear,
      activeKMonth: activeDayView?.kMonth,
      activeKDay: activeDayView?.kDay,
    );
    final ky = selectedDay.kYear;
    final km = selectedDay.kMonth;
    final kd = selectedDay.kDay;
    final notes = notesByDay[_kKey(ky, km, kd)] ?? const <_Note>[];
    var flowBacked = 0;
    var reminders = 0;
    var standalone = 0;
    var startMinuteSum = 0;
    var checksum = 0x811c9dc5;
    for (final note in notes) {
      final startMinute = note.allDay
          ? 0
          : (note.start?.hour ?? 0) * 60 + (note.start?.minute ?? 0);
      startMinuteSum += startMinute;
      if (note.isReminder) {
        reminders++;
      } else if ((note.flowId ?? -1) > 0) {
        flowBacked++;
      } else {
        standalone++;
      }
      for (final value in <int>[
        startMinute,
        note.allDay ? 1 : 0,
        note.isReminder ? 1 : 0,
        (note.flowId ?? -1) > 0 ? 1 : 0,
      ]) {
        checksum = ((checksum ^ value) * 0x01000193) & 0x7fffffff;
      }
    }
    return HydrationSelectedDaySnapshot(
      dayKey: _kKey(ky, km, kd),
      eventCount: notes.length,
      flowBackedCount: flowBacked,
      reminderCount: reminders,
      standaloneCount: standalone,
      startMinuteSum: startMinuteSum,
      multisetChecksum: checksum,
    );
  }

  void _scheduleMonthHydrationFrame() {
    if (_monthHydrationFrameScheduled) return;
    _monthHydrationFrameScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _monthHydrationFrameScheduled = false;
      if (!mounted) return;
      final firstFrame = !_monthHydrationFirstFrameRecorded;
      _monthHydrationFirstFrameRecorded = true;
      CalendarHydrationDiagnostics.instance.recordCalendarFrame(
        surface: 'month',
        selectedDay: _hydrationSelectedDaySnapshot(_notes),
        dataVersion: _dataVersion,
        firstFrame: firstFrame,
        hasLocalSnapshot:
            _warmStartSnapshotVisible || _flows.isNotEmpty || _notes.isNotEmpty,
      );
    });
  }

  Future<bool> _ensureJournalControllerReady() async {
    if (_journalInitialized) return true;
    try {
      await _journalController.init();
      if (mounted) {
        setState(() => _journalInitialized = true);
      }
      return true;
    } catch (error) {
      if (kDebugMode) {
        _calendarDebugPrint(
          '[calendar] journal init for badge sync failed: $error',
        );
      }
      return false;
    }
  }

  Future<void> _appendToJournalAndRefresh(String text) async {
    if (text.trim().isEmpty) return;
    if (!await _ensureJournalControllerReady()) return;
    await _journalController.appendToToday(text);
    _notifyDayViewDataChanged();
  }

  Future<void> _removeCompletionBadgeAndRefresh(String badgeId) async {
    if (badgeId.trim().isEmpty) return;
    if (!await _ensureJournalControllerReady()) return;
    await _journalController.removeBadge(badgeId);
    _notifyDayViewDataChanged();
  }

  Future<void> _writeMaatJournalResponseBlockAndRefresh(
    MaatJournalResponseBlock block,
  ) async {
    if (block.sourceId.trim().isEmpty) return;
    if (!await _ensureJournalControllerReady()) return;
    final localDate = block.localDate;
    if (localDate != null) {
      await _journalController.loadDate(DateUtils.dateOnly(localDate));
    }
    final currentDocument =
        _journalController.currentDocument ??
        JournalDocument.fromPlainText(_journalController.currentDraft);
    final nextDocument = MaatJournalResponseBlockUtils.upsertPlainUserText(
      currentDocument,
      block,
    );
    await _journalController.updateDocument(nextDocument);
    _notifyDayViewDataChanged();
  }

  void _publishWarmStateSnapshot() {
    _CalendarWarmStateStore.save(
      userId: _activeWarmStartUserId(),
      notes: _notes,
      flows: _flows,
      calendarSummariesById: _calendarSummariesById,
      hiddenCalendarIds: _hiddenCalendarIds,
      personalCalendarId: _personalCalendarId,
    );
  }

  NoteData _noteDataFromNote(_Note n) {
    return NoteData(
      id: n.id?.toString(),
      clientEventId: n.clientEventId,
      calendarId: n.calendarId,
      calendarName: n.calendarName,
      title: n.title,
      detail: n.detail,
      location: n.location,
      allDay: n.allDay,
      start: n.start,
      end: n.end,
      flowId: n.flowId,
      manualColor: n.manualColor,
      category: n.category,
      isReminder: n.isReminder,
      reminderId: n.reminderId,
      behaviorPayload: n.behaviorPayload,
    );
  }

  List<NoteData> _noteDataForDay(int y, int m, int d) {
    final notes = _dedupeVisibleDayNotes(_notes['$y-$m-$d'] ?? const <_Note>[]);
    return [for (final note in notes) _noteDataFromNote(note)];
  }

  // Build a reminder id that is unique per event occurrence and alert time.
  String _reminderIdForNote(_Note n, DateTime alertUtc) {
    final base = n.id ?? n.title;
    return '$base-${alertUtc.toIso8601String()}';
  }

  int? _effectiveAlertMinutes(int? raw) {
    if (raw == _alertNoneMinutes) return null; // explicit "None"
    // Legacy/unspecified -> default to at-time
    return raw ?? 0;
  }

  DateTime? _alertDateTimeLocal({
    required _Note note,
    required int kYear,
    required int kMonth,
    required int kDay,
  }) {
    final alertMinutes = _effectiveAlertMinutes(note.alertOffsetMinutes);
    if (alertMinutes == null) return null;

    final gDay = KemeticMath.toGregorian(kYear, kMonth, kDay);
    final startHour = note.start?.hour ?? 9;
    final startMinute = note.start?.minute ?? 0;
    final startLocal = DateTime(
      gDay.year,
      gDay.month,
      gDay.day,
      note.allDay ? 9 : startHour,
      note.allDay ? 0 : startMinute,
    );

    return startLocal.subtract(Duration(minutes: alertMinutes));
  }

  Future<void> _saveFlowById(int flowId) async {
    final idx = _flows.indexWhere((f) => f.id == flowId);
    if (idx < 0) {
      if (kDebugMode) {
        _calendarDebugPrint('[saveFlowById] Flow $flowId not found in cache');
      }
      return;
    }
    final flow = _flows[idx];
    if (flow.isSaved) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Already in Saved Flows'),
          duration: Duration(seconds: 2),
        ),
      );
      return;
    }

    try {
      await UserEventsRepo(
        Supabase.instance.client,
      ).setFlowSaved(flowId: flowId, isSaved: true);
      if (!mounted) return;
      setState(() {
        _flows[idx].isSaved = true;
        _flows[idx].savedAt = DateTime.now().toUtc();
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Saved to Saved Flows'),
          duration: Duration(seconds: 2),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('Unable to save flow: $e')));
    }
  }

