  /* ───── ClientEventId utilities ───── */
  /// Build a canonical clientEventId using the shared EventCidUtil (URL-encoded).
  /// Defaults start time to 9:00 when missing or all-day.
  String _buildCid({
    required int ky,
    required int km,
    required int kd,
    required String title,
    int? startHour,
    int? startMinute,
    bool allDay = false,
    required int flowId,
    String? calendarScopeToken,
  }) {
    final int sHour = (allDay || startHour == null) ? 9 : startHour;
    final int sMinute = (allDay || startMinute == null) ? 0 : startMinute;
    final baseCid = EventCidUtil.buildClientEventId(
      ky: ky,
      km: km,
      kd: kd,
      title: title,
      startHour: sHour,
      startMinute: sMinute,
      allDay: allDay,
      flowId: flowId,
    );
    final scopeToken = calendarScopeToken?.trim();
    if (scopeToken == null || scopeToken.isEmpty) return baseCid;
    return '$baseCid|cal=$scopeToken';
  }

  String? _calendarScopeToken(String? calendarId) {
    final trimmed = calendarId?.trim();
    if (trimmed == null ||
        trimmed.isEmpty ||
        trimmed == _personalCalendarId ||
        trimmed.length < 8) {
      return null;
    }
    return trimmed.substring(0, 8);
  }

  bool _isCalendarVisible(String? calendarId) {
    final trimmed = calendarId?.trim();
    if (!_calendarStateLoaded || trimmed == null || trimmed.isEmpty) {
      return true;
    }
    return !_hiddenCalendarIds.contains(trimmed);
  }

  String? _activeWarmStartUserId() {
    final userId = Supabase.instance.client.auth.currentUser?.id.trim();
    if (userId == null || userId.isEmpty) return null;
    return userId;
  }

  String _warmStartCacheKey(String userId) =>
      '$_kWarmStartCacheKeyPrefix:$userId';

  bool _hasPaintedEventSnapshot(Map<String, List<_Note>> notesByDay) {
    return notesByDay.values.any((notes) => notes.isNotEmpty);
  }

  TimeOfDay? _timeOfDayFromMinutes(dynamic raw) {
    final totalMinutes = (raw as num?)?.toInt();
    if (totalMinutes == null || totalMinutes < 0) return null;
    return TimeOfDay(
      hour: (totalMinutes ~/ 60) % 24,
      minute: totalMinutes % 60,
    );
  }

  int? _timeOfDayToMinutes(TimeOfDay? time) {
    if (time == null) return null;
    return time.hour * 60 + time.minute;
  }

  DateTime? _parseWarmStartDateTime(Object? raw) {
    final value = raw?.toString().trim();
    if (value == null || value.isEmpty) return null;
    return DateTime.tryParse(value);
  }

  DateTime? _warmStartDateFromKey(String key) {
    final parts = key.split('-');
    if (parts.length != 3) return null;
    final ky = int.tryParse(parts[0]);
    final km = int.tryParse(parts[1]);
    final kd = int.tryParse(parts[2]);
    if (ky == null || km == null || kd == null) return null;
    try {
      return DateUtils.dateOnly(KemeticMath.toGregorian(ky, km, kd));
    } catch (_) {
      return null;
    }
  }

  Map<int, int> _decodeWarmStartIntMap(Object? raw) {
    if (raw is! Map) return const <int, int>{};
    final result = <int, int>{};
    raw.forEach((key, value) {
      final id = int.tryParse(key.toString());
      final count = (value as num?)?.toInt();
      if (id == null || count == null) return;
      result[id] = count;
    });
    return result;
  }

  Map<String, dynamic> _encodeWarmStartIntMap(Map<int, int> values) {
    return <String, dynamic>{
      for (final entry in values.entries) entry.key.toString(): entry.value,
    };
  }

  Map<String, dynamic> _serializeWarmStartFlow(_Flow flow) {
    return <String, dynamic>{
      'id': flow.id,
      'calendarId': flow.calendarId,
      'name': flow.name,
      'color': flow.color.toARGB32(),
      'active': flow.active,
      'isSaved': flow.isSaved,
      'savedAt': flow.savedAt?.toIso8601String(),
      'start': flow.start?.toIso8601String(),
      'end': flow.end?.toIso8601String(),
      'rules': flow.rules.map(ruleToJson).toList(growable: false),
      'notes': flow.notes,
      'shareId': flow.shareId,
      'isHidden': flow.isHidden,
      'isReminder': flow.isReminder,
      'reminderUuid': flow.reminderUuid,
    };
  }

  _Flow? _deserializeWarmStartFlow(Object? raw) {
    if (raw is! Map) return null;
    try {
      final json = Map<String, dynamic>.from(raw);
      final id = (json['id'] as num?)?.toInt();
      final name = json['name'] as String?;
      final colorValue = (json['color'] as num?)?.toInt();
      if (id == null || name == null || colorValue == null) return null;
      final rulesRaw = (json['rules'] as List?) ?? const [];
      final rules = <FlowRule>[];
      for (final item in rulesRaw.whereType<Map>()) {
        try {
          rules.add(CalendarPage.ruleFromJson(Map<String, dynamic>.from(item)));
        } catch (_) {
          // Skip malformed cached rules instead of dropping the entire flow.
        }
      }
      return _Flow(
        id: id,
        calendarId: json['calendarId'] as String?,
        name: name,
        color: Color(colorValue),
        active: (json['active'] as bool?) ?? true,
        isSaved: (json['isSaved'] as bool?) ?? false,
        savedAt: _parseWarmStartDateTime(json['savedAt'])?.toUtc(),
        rules: rules,
        start: _parseWarmStartDateTime(json['start'])?.toLocal(),
        end: _parseWarmStartDateTime(json['end'])?.toLocal(),
        notes: json['notes'] as String?,
        shareId: json['shareId'] as String?,
        isHidden: (json['isHidden'] as bool?) ?? false,
        isReminder: (json['isReminder'] as bool?) ?? false,
        reminderUuid: json['reminderUuid'] as String?,
      );
    } catch (_) {
      return null;
    }
  }

  Map<String, dynamic> _serializeWarmStartNote(_Note note) {
    return <String, dynamic>{
      'id': note.id,
      'clientEventId': note.clientEventId,
      'calendarId': note.calendarId,
      'calendarName': note.calendarName,
      'title': note.title,
      'detail': note.detail,
      'location': note.location,
      'allDay': note.allDay,
      'startMinutes': _timeOfDayToMinutes(note.start),
      'endMinutes': _timeOfDayToMinutes(note.end),
      'flowId': note.flowId,
      'manualColor': note.manualColor?.toARGB32(),
      'resolvedColor': _noteColor(note).toARGB32(),
      'category': note.category,
      'isReminder': note.isReminder,
      'reminderId': note.reminderId,
      'alertOffsetMinutes': note.alertOffsetMinutes,
      'actionId': note.actionId,
      'behaviorPayload': note.behaviorPayload,
    };
  }

  _Note? _deserializeWarmStartNote(Object? raw) {
    if (raw is! Map) return null;
    try {
      final json = Map<String, dynamic>.from(raw);
      final title = json['title'] as String?;
      final allDay = json['allDay'] as bool?;
      if (title == null || allDay == null) return null;
      final flowId = (json['flowId'] as num?)?.toInt();
      final explicitColorValue = (json['manualColor'] as num?)?.toInt();
      final resolvedColorValue = (json['resolvedColor'] as num?)?.toInt();
      final warmStartColorValue =
          explicitColorValue ??
          ((flowId != null && flowId != -1) ? resolvedColorValue : null);
      return _Note(
        id: json['id'] as String?,
        clientEventId: json['clientEventId'] as String?,
        calendarId: json['calendarId'] as String?,
        calendarName: json['calendarName'] as String?,
        title: title,
        detail: json['detail'] as String?,
        location: json['location'] as String?,
        allDay: allDay,
        start: _timeOfDayFromMinutes(json['startMinutes']),
        end: _timeOfDayFromMinutes(json['endMinutes']),
        flowId: flowId,
        manualColor: warmStartColorValue == null
            ? null
            : Color(warmStartColorValue),
        category: json['category'] as String?,
        isReminder: (json['isReminder'] as bool?) ?? false,
        reminderId: json['reminderId'] as String?,
        alertOffsetMinutes: (json['alertOffsetMinutes'] as num?)?.toInt(),
        actionId: json['actionId'] as String?,
        behaviorPayload: json['behaviorPayload'] is Map
            ? Map<String, dynamic>.from(json['behaviorPayload'] as Map)
            : null,
      );
    } catch (_) {
      return null;
    }
  }

  PendingCalendarNoteRecord _pendingRecordForNote({
    required String dayKey,
    required _Note note,
    required DateTime createdAt,
  }) {
    final cid = note.clientEventId?.trim();
    if (cid == null || cid.isEmpty) {
      throw ArgumentError('Pending note persistence requires an exact CID');
    }
    return PendingCalendarNoteRecord(
      clientEventId: cid,
      dayKey: dayKey,
      createdAt: createdAt.toUtc(),
      notePayload: _serializeWarmStartNote(note),
    );
  }

  Future<void> _persistPendingNote({
    required String userId,
    required String dayKey,
    required _Note note,
    required DateTime createdAt,
  }) async {
    final record = _pendingRecordForNote(
      dayKey: dayKey,
      note: note,
      createdAt: createdAt,
    );
    await _pendingNoteStore.write(userId: userId, record: record);
    await _commitCalendarOverlayState(
      userId: userId,
      reason: 'pending_create_or_edit',
      additionalRecords: <Map<String, Object?>>[
        <String, Object?>{
          'kind': 'create_or_edit',
          'dayKey': record.dayKey,
          'clientEventId': record.clientEventId,
          'createdAtUtc': record.createdAt.toUtc().toIso8601String(),
          'note': record.notePayload,
        },
      ],
    );
  }

  Future<void> _removePersistedPendingCids(
    Iterable<String> clientEventIds, {
    String? userId,
  }) async {
    final normalizedCids = clientEventIds
        .map((value) => value.trim())
        .where((value) => value.isNotEmpty)
        .toSet();
    final debugBarrier =
        CalendarPage.debugBeforePersistedPendingCidRemovalForTesting;
    if (debugBarrier != null) {
      await debugBarrier(Set<String>.unmodifiable(normalizedCids));
    }
    final resolvedUserId = userId ?? _activeWarmStartUserId();
    if (resolvedUserId == null || resolvedUserId.trim().isEmpty) return;
    await _pendingNoteStore.removeMany(
      userId: resolvedUserId,
      clientEventIds: normalizedCids,
    );
    await _commitCalendarOverlayState(
      userId: resolvedUserId,
      reason: 'pending_cid_reconciled',
      removeCreateCids: normalizedCids,
    );
  }

  Future<void> _restoreDurablePendingNotesForUser(
    String userId, {
    bool requireActiveUser = true,
  }) async {
    final normalizedUserId = userId.trim();
    if (normalizedUserId.isEmpty || !mounted) return;
    if (_pendingNotesRestoredForUserId == normalizedUserId) return;
    if (_pendingNotesRestoreInFlightForUserId == normalizedUserId) {
      await _pendingNotesRestoreInFlight;
      return;
    }

    final previousUserId = _pendingNotesRestoredForUserId;
    if (previousUserId != null && previousUserId != normalizedUserId) {
      _unconfirmed.clear();
      unawaited(_pendingNoteStore.clearForUser(previousUserId));
    }

    final restore = () async {
      final records = await _pendingNoteStore.readForUser(normalizedUserId);
      if (!mounted ||
          (requireActiveUser && _activeWarmStartUserId() != normalizedUserId)) {
        return;
      }
      var paintedFallback = false;
      var restoredRecordCount = 0;
      for (final record in records) {
        final note = _deserializeWarmStartNote(record.notePayload);
        if (note == null ||
            note.clientEventId?.trim() != record.clientEventId) {
          continue;
        }
        final registered = _unconfirmed.register(
          dayKey: record.dayKey,
          note: note,
          createdAt: record.createdAt,
        );
        if (!registered) continue;
        final alreadyPainted = _notes.values.any(
          (bucket) => bucket.any(
            (candidate) =>
                candidate.clientEventId?.trim() == record.clientEventId,
          ),
        );
        paintedFallback = !alreadyPainted || paintedFallback;
        restoredRecordCount++;
      }
      if (restoredRecordCount > 0) {
        final trackSkyFlowIds = _flows
            .where((flow) => _isTrackSkyFlowName(flow.name))
            .map((flow) => flow.id)
            .where((flowId) => flowId > 0)
            .toSet();
        final projection = deriveVisibleCalendarProjection<_Note>(
          source: _notes,
          pendingItems: _unconfirmed.visibleProjectionItems,
          stableIdentityOf: _calendarNoteStableIdentity,
          suppressionRules: const <CalendarItemSuppressionRule<_Note>>[],
          pendingIdentityConflictResolution:
              CalendarPendingIdentityConflictResolution.pendingReplacesSource,
          reduceBucket: (_, notes) =>
              _dedupeVisibleDayNotes(notes, trackSkyFlowIds: trackSkyFlowIds),
        );
        _replaceLiveNoteBuckets(projection.buckets);
      }
      _pendingNotesRestoredForUserId = normalizedUserId;
      if (restoredRecordCount > 0 && mounted) {
        if (paintedFallback) {
          _warmStartCacheRestoredForUserId = normalizedUserId;
          _warmStartSnapshotVisible = true;
        }
        _bumpDataVersion();
      }
    }();
    _pendingNotesRestoreInFlight = restore;
    _pendingNotesRestoreInFlightForUserId = normalizedUserId;
    try {
      await restore;
    } finally {
      if (_pendingNotesRestoreInFlightForUserId == normalizedUserId) {
        _pendingNotesRestoreInFlightForUserId = null;
        _pendingNotesRestoreInFlight = null;
      }
    }
  }

  void _scheduleExpiredPendingCidVerification() {
    final userId = _activeWarmStartUserId();
    if (userId == null) return;
    for (final entry in _unconfirmed.dueForVerification()) {
      final cid = entry.note.clientEventId?.trim();
      if (cid == null ||
          cid.isEmpty ||
          _pendingCidVerificationInFlight.contains(cid)) {
        continue;
      }
      unawaited(
        _hydrationScheduler.schedule(
          CalendarHydrationJob(
            key: CalendarHydrationJobKey(
              kind: CalendarHydrationIntentKind.reminderMaintenance,
              reason: 'verify_pending_cid:$cid',
            ),
            priority: 10,
            run: (context) async {
              context.throwIfCancelled('before_pending_cid_verification');
              if (!_pendingCidVerificationInFlight.add(cid)) return;
              await _verifyPendingCid(userId: userId, clientEventId: cid);
              context.throwIfCancelled('after_pending_cid_verification');
            },
          ),
        ),
      );
    }
  }

  Future<void> _verifyPendingCid({
    required String userId,
    required String clientEventId,
  }) async {
    try {
      final result = await UserEventsRepo(
        Supabase.instance.client,
      ).lookupEventByClientEventId(clientEventId);
      if (!mounted || _activeWarmStartUserId() != userId) return;
      switch (result.disposition) {
        case UserEventLookupDisposition.found:
          // The lookup proves persistence, but only an accepted calendar
          // commit may retire the optimistic projection.
          final entry = _unconfirmed.entryForCid(clientEventId);
          final localDate = entry == null
              ? null
              : _warmStartDateFromKey(entry.dayKey);
          unawaited(
            _requestHydration(
              _CalendarHydrationRequest.targeted(
                reason: 'verify_pending_cid_found',
                intentKind: CalendarHydrationIntentKind.affectedDate,
                interval: localDate == null
                    ? null
                    : CalendarHydrationInterval.fromInclusiveLocalDays(
                        firstLocalDay: localDate,
                        lastLocalDay: localDate,
                      ),
              ),
            ),
          );
          return;
        case UserEventLookupDisposition.notFound:
          if (!_unconfirmed.containsCid(clientEventId)) return;
          _unconfirmed.forgetCid(clientEventId);
          _removeCalendarNotesWhere(
            (_, note) => note.clientEventId?.trim() == clientEventId,
          );
          await _removePersistedPendingCids(<String>[
            clientEventId,
          ], userId: userId);
          if (!mounted) return;
          _bumpDataVersion();
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text(
                'An event could not be confirmed as saved and was restored to server state.',
              ),
            ),
          );
          return;
        case UserEventLookupDisposition.unavailable:
          // Keep both the painted event and its durable record. A later
          // hydration or verification attempt will resolve it.
          return;
      }
    } finally {
      _pendingCidVerificationInFlight.remove(clientEventId);
    }
  }

  Map<String, dynamic> _buildWarmStartSnapshot({
    required String userId,
    required String compactionLevel,
    Duration? pastWindow,
    Duration? futureWindow,
    bool relevantFlowsOnly = false,
  }) {
    assert(
      (pastWindow == null) == (futureWindow == null),
      'Warm-start cache windows must be both bounded or both unbounded.',
    );
    final cacheSavedAt = DateTime.now().toUtc().toIso8601String();
    final centerDay =
        (_lastViewKy != null && _lastViewKm != null && _lastViewKd != null)
        ? DateUtils.dateOnly(
            KemeticMath.toGregorian(_lastViewKy!, _lastViewKm!, _lastViewKd!),
          )
        : DateUtils.dateOnly(DateTime.now());
    final trimmedStart = pastWindow == null
        ? null
        : centerDay.subtract(pastWindow);
    final trimmedEnd = futureWindow == null
        ? null
        : centerDay.add(futureWindow);

    final notesJson = <String, dynamic>{};
    final referencedFlowIds = <int>{};
    _notes.forEach((key, notes) {
      final day = _warmStartDateFromKey(key);
      if (trimmedStart != null &&
          trimmedEnd != null &&
          (day == null ||
              day.isBefore(trimmedStart) ||
              day.isAfter(trimmedEnd))) {
        return;
      }
      for (final note in notes) {
        final flowId = note.flowId;
        if (flowId != null && flowId > 0) referencedFlowIds.add(flowId);
      }
      notesJson[key] = notes
          .map(_serializeWarmStartNote)
          .toList(growable: false);
    });
    final snapshotFlows = relevantFlowsOnly
        ? _flows
              .where(
                (flow) =>
                    flow.isReminder || referencedFlowIds.contains(flow.id),
              )
              .toList(growable: false)
        : _flows;
    final snapshotFlowIds = snapshotFlows.map((flow) => flow.id).toSet();
    Map<int, int> snapshotCounts(Map<int, int> counts) {
      if (!relevantFlowsOnly) return counts;
      return <int, int>{
        for (final entry in counts.entries)
          if (snapshotFlowIds.contains(entry.key)) entry.key: entry.value,
      };
    }

    return <String, dynamic>{
      'snapshotSchemaVersion': 2,
      'userId': userId,
      // Keep savedAt for older builds while making cache-write time distinct
      // from the last server-authoritative calendar/accounting results.
      'savedAt': cacheSavedAt,
      'cacheSavedAt': cacheSavedAt,
      'lastAuthoritativeHydrationAt': _lastAuthoritativeHydrationAt
          ?.toUtc()
          .toIso8601String(),
      'lastAccountingAuthorityAt': _lastAccountingAuthorityAt
          ?.toUtc()
          .toIso8601String(),
      'accountingStale': _accountingStale,
      'compactionLevel': compactionLevel,
      'cacheCenterDay': centerDay.toIso8601String(),
      'cachePastDays': pastWindow?.inDays,
      'cacheFutureDays': futureWindow?.inDays,
      'catalogFingerprint':
          _hydrationController.state.catalogFingerprint ??
          _catalogFingerprintForCurrentFlows(),
      'cacheAuthority': _hydrationController.state.authority.name,
      'authoritativeViewportStartUtc': _hydrationController
          .state
          .viewport
          ?.startUtc
          .toIso8601String(),
      'authoritativeViewportEndUtc': _hydrationController.state.viewport?.endUtc
          .toIso8601String(),
      'nextFlowId': _nextFlowId,
      'flows': snapshotFlows
          .map(_serializeWarmStartFlow)
          .toList(growable: false),
      'notes': notesJson,
      'flowTotalEventCounts': _encodeWarmStartIntMap(
        snapshotCounts(_flowTotalEventCounts),
      ),
      'flowRemainingEventCounts': _encodeWarmStartIntMap(
        snapshotCounts(_flowRemainingEventCounts),
      ),
    };
  }

  void _scheduleWarmStartCacheSave() {
    final userId = _activeWarmStartUserId();
    if (userId == null) return;
    if (!shouldPersistWarmStartCache(_hydrationAuthorityScope)) {
      CalendarHydrationDiagnostics.instance
          .recordCacheEvent('cache_save_skipped', <String, Object?>{
            'reason': 'partial_authority',
            'authority_scope': _hydrationAuthorityScope.diagnosticName,
            'stage': 'schedule',
          });
      return;
    }
    _warmStartCacheDebounceTimer?.cancel();
    _warmStartCacheDebounceTimer = Timer(_warmStartCacheDebounce, () {
      _warmStartCacheDebounceTimer = null;
      unawaited(_persistWarmStartCacheNow(userId: userId));
    });
  }

  Future<void> _flushPendingWarmStartCacheSave({
    String reason = 'manual',
  }) async {
    final timer = _warmStartCacheDebounceTimer;
    if (timer == null) return;
    _warmStartCacheDebounceTimer = null;
    if (timer.isActive) {
      timer.cancel();
    }
    if (!shouldPersistWarmStartCache(_hydrationAuthorityScope)) {
      CalendarHydrationDiagnostics.instance
          .recordCacheEvent('cache_save_skipped', <String, Object?>{
            'reason': 'partial_authority',
            'authority_scope': _hydrationAuthorityScope.diagnosticName,
            'stage': 'flush',
            'request_reason': reason,
          });
      return;
    }
    await _persistWarmStartCacheNow(debugReason: reason);
  }

  String? _encodeServerCurrentViewportCheckpoint({
    required String userId,
    required String? previousEncoded,
  }) {
    final viewport = _hydrationController.state.viewport;
    if (viewport == null) return null;
    final fresh = _buildWarmStartSnapshot(
      userId: userId,
      compactionLevel: 'viewport_checkpoint',
      pastWindow: null,
      futureWindow: null,
      relevantFlowsOnly: false,
    );
    if (previousEncoded == null || previousEncoded.trim().isEmpty) {
      return jsonEncode(fresh);
    }
    try {
      final decoded = jsonDecode(previousEncoded);
      if (decoded is! Map) return jsonEncode(fresh);
      final previous = Map<String, dynamic>.from(decoded);
      final merged = mergeSerializedWarmCacheViewport(
        previous: previous,
        fresh: fresh,
        userId: userId,
        viewportStartInclusive: viewport.startUtc,
        viewportEndExclusive: viewport.endUtc,
        parseKeyToDay: _warmStartDateFromKey,
      );
      return merged == null ? null : jsonEncode(merged);
    } catch (_) {
      return jsonEncode(fresh);
    }
  }

  Future<void> _persistWarmStartCacheNow({
    String? userId,
    String debugReason = 'debounced',
    bool allowServerCurrentViewport = false,
  }) {
    final operation = _warmStartCacheWriteTail.then(
      (_) => _persistWarmStartCacheNowSerialized(
        userId: userId,
        debugReason: debugReason,
        allowServerCurrentViewport: allowServerCurrentViewport,
      ),
    );
    _warmStartCacheWriteTail = operation.then<void>(
      (_) {},
      onError: (Object _, StackTrace _) {},
    );
    return operation;
  }

  /// Cache durability is best-effort after live authority has committed.
  /// Callers may await completion for diagnostics, but this future never
  /// converts a successful hydration into a failed hydration.
  Future<void> _persistWarmStartCacheBestEffort({
    String? userId,
    String debugReason = 'debounced',
    bool allowServerCurrentViewport = false,
  }) async {
    try {
      await _persistWarmStartCacheNow(
        userId: userId,
        debugReason: debugReason,
        allowServerCurrentViewport: allowServerCurrentViewport,
      );
    } catch (_) {
      // `_persistWarmStartCacheNowSerialized` already records the safe failure
      // class. Persistence is deliberately outside presentation authority.
    }
  }

  Future<void> _persistWarmStartCacheNowSerialized({
    String? userId,
    required String debugReason,
    required bool allowServerCurrentViewport,
  }) async {
    final resolvedUserId = userId ?? _activeWarmStartUserId();
    if (resolvedUserId == null) return;
    final diagnostics = CalendarHydrationDiagnostics.instance;
    _lastWarmStartCacheSaveOutcome = null;
    final controllerStateAtStart = _hydrationController.state;
    final requiredViewportRevision = allowServerCurrentViewport
        ? controllerStateAtStart.viewportRevision
        : null;
    bool writeIsAuthorized() =>
        shouldPersistWarmStartCache(_hydrationAuthorityScope) ||
        (allowServerCurrentViewport &&
            _hydrationController.state.mayPersistServerCurrentViewport &&
            _hydrationController.state.viewportRevision ==
                requiredViewportRevision);

    if (!writeIsAuthorized()) {
      diagnostics.recordCacheEvent('cache_save_skipped', <String, Object?>{
        'reason': 'partial_authority',
        'authority_scope': _hydrationAuthorityScope.diagnosticName,
        'request_reason': debugReason,
      });
      _lastWarmStartCacheSaveOutcome = 'partial_authority';
      return;
    }
    final cacheCatalogFingerprint = controllerStateAtStart.catalogFingerprint;
    if (cacheCatalogFingerprint == null ||
        !_hydrationController.validateCacheWrite(
          sessionGeneration: controllerStateAtStart.sessionGeneration,
          catalogFingerprint: cacheCatalogFingerprint,
          allowServerCurrentViewport: allowServerCurrentViewport,
          requiredViewportRevision: requiredViewportRevision,
        )) {
      diagnostics.recordCacheEvent('cache_save_skipped', <String, Object?>{
        'reason': 'controller_authority_mismatch',
        'request_reason': debugReason,
      });
      _lastWarmStartCacheSaveOutcome = 'partial_authority';
      return;
    }
    final totalStopwatch = Stopwatch()..start();
    final diagnosticWork = diagnostics.markAsyncWorkStarted(
      null,
      'warm_cache_save',
    );
    void recordCache(String marker, Map<String, Object?> fields) {
      diagnostics.recordCacheEvent(marker, fields, token: diagnosticWork);
    }

    recordCache('cache_save_attempted', <String, Object?>{
      'reason': debugReason,
      'authority_scope': _hydrationAuthorityScope.diagnosticName,
    });
    try {
      final prefsStopwatch = Stopwatch()..start();
      final prefs = await SharedPreferences.getInstance();
      recordCache('cache_save_prefs_ready', <String, Object?>{
        'duration_ms': prefsStopwatch.elapsedMilliseconds,
      });
      // Re-validate after the prefs await — account may have switched.
      final currentUserId = _activeWarmStartUserId();
      if (currentUserId == null || currentUserId != resolvedUserId) {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[warmStart] skip cache save reason=$debugReason '
            'userMismatch scheduled=$resolvedUserId current=$currentUserId',
          );
        }
        recordCache('cache_save_skipped', <String, Object?>{
          'reason': 'user_mismatch',
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        _lastWarmStartCacheSaveOutcome = 'user_mismatch';
        return;
      }
      if (!writeIsAuthorized()) {
        recordCache('cache_save_skipped', <String, Object?>{
          'reason': 'partial_authority',
          'authority_scope': _hydrationAuthorityScope.diagnosticName,
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        _lastWarmStartCacheSaveOutcome = 'partial_authority';
        return;
      }
      if (!_hydrationController.validateCacheWrite(
        sessionGeneration: controllerStateAtStart.sessionGeneration,
        catalogFingerprint: cacheCatalogFingerprint,
        allowServerCurrentViewport: allowServerCurrentViewport,
        requiredViewportRevision: requiredViewportRevision,
      )) {
        recordCache('cache_save_skipped', <String, Object?>{
          'reason': 'controller_changed_after_prefs',
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        _lastWarmStartCacheSaveOutcome = 'partial_authority';
        return;
      }
      final key = _warmStartCacheKey(resolvedUserId);
      final previousEncoded = prefs.getString(key);

      if (_flows.isEmpty && _notes.isEmpty) {
        await prefs.remove(key);
        recordCache('cache_save_ended', <String, Object?>{
          'outcome': 'empty_removed',
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        _lastWarmStartCacheSaveOutcome = 'empty_removed';
        return;
      }

      String? encoded;
      int? untrimmedSize;
      int smallestCandidateSize = 0;
      var selectedLevel = 'none';
      int? selectedPastDays;
      int? selectedFutureDays;
      if (allowServerCurrentViewport) {
        encoded = _encodeServerCurrentViewportCheckpoint(
          userId: resolvedUserId,
          previousEncoded: previousEncoded,
        );
        untrimmedSize = encoded?.length;
        smallestCandidateSize = encoded?.length ?? 0;
        if (encoded != null && encoded.length <= _warmStartCacheMaxChars) {
          selectedLevel = 'viewport_checkpoint';
        } else {
          encoded = null;
        }
      } else {
        final candidates = [
          (
            level: 'full',
            past: null as Duration?,
            future: null as Duration?,
            relevantFlowsOnly: false,
          ),
          (
            level: 'wide',
            past: _warmStartWidePast,
            future: _warmStartWideFuture,
            relevantFlowsOnly: false,
          ),
          (
            level: 'bounded',
            past: _warmStartBoundedPast,
            future: _warmStartBoundedFuture,
            relevantFlowsOnly: false,
          ),
          (
            level: 'near',
            past: _warmStartNearPast,
            future: _warmStartNearFuture,
            relevantFlowsOnly: false,
          ),
          (
            level: 'selected_day',
            past: Duration.zero,
            future: Duration.zero,
            relevantFlowsOnly: true,
          ),
        ];
        for (final candidate in candidates) {
          final candidateEncoded = jsonEncode(
            _buildWarmStartSnapshot(
              userId: resolvedUserId,
              compactionLevel: candidate.level,
              pastWindow: candidate.past,
              futureWindow: candidate.future,
              relevantFlowsOnly: candidate.relevantFlowsOnly,
            ),
          );
          untrimmedSize ??= candidateEncoded.length;
          smallestCandidateSize = candidateEncoded.length;
          if (candidateEncoded.length > _warmStartCacheMaxChars) continue;
          encoded = candidateEncoded;
          selectedLevel = candidate.level;
          selectedPastDays = candidate.past?.inDays;
          selectedFutureDays = candidate.future?.inDays;
          break;
        }
      }
      if (encoded == null) {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[warmStart] skip cache save reason=$debugReason '
            'smallestSize=$smallestCandidateSize',
          );
        }
        recordCache('cache_save_ended', <String, Object?>{
          'outcome': 'oversize_skipped',
          'untrimmed_chars': untrimmedSize,
          'smallest_candidate_chars': smallestCandidateSize,
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        _lastWarmStartCacheSaveOutcome = 'oversize_skipped';
        return;
      }

      if (!writeIsAuthorized() ||
          !_hydrationController.validateCacheWrite(
            sessionGeneration: controllerStateAtStart.sessionGeneration,
            catalogFingerprint: cacheCatalogFingerprint,
            allowServerCurrentViewport: allowServerCurrentViewport,
            requiredViewportRevision: requiredViewportRevision,
          )) {
        recordCache('cache_save_skipped', <String, Object?>{
          'reason': 'controller_changed_before_write',
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        _lastWarmStartCacheSaveOutcome = 'partial_authority';
        return;
      }
      final writeSucceeded = await prefs.setString(key, encoded);
      if (!writeSucceeded) {
        recordCache('cache_save_ended', <String, Object?>{
          'outcome': 'storage_rejected',
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        _lastWarmStartCacheSaveOutcome = 'failed';
        return;
      }
      if (!_hydrationController.validateCacheWrite(
        sessionGeneration: controllerStateAtStart.sessionGeneration,
        catalogFingerprint: cacheCatalogFingerprint,
        allowServerCurrentViewport: allowServerCurrentViewport,
        requiredViewportRevision: requiredViewportRevision,
      )) {
        final rollbackSucceeded = previousEncoded == null
            ? await prefs.remove(key)
            : await prefs.setString(key, previousEncoded);
        recordCache('cache_save_ended', <String, Object?>{
          'outcome': rollbackSucceeded
              ? 'controller_changed_write_rolled_back'
              : 'controller_changed_rollback_failed',
          'saved_chars': encoded.length,
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        _lastWarmStartCacheSaveOutcome = rollbackSucceeded
            ? 'controller_changed_write_rolled_back'
            : 'failed';
        return;
      }
      _lastWarmStartCacheSaveOutcome = selectedLevel == 'full'
          ? 'saved'
          : 'compacted_and_saved';
      recordCache('cache_save_ended', <String, Object?>{
        'outcome': _lastWarmStartCacheSaveOutcome,
        'compaction_level': selectedLevel,
        'past_days': selectedPastDays,
        'future_days': selectedFutureDays,
        'untrimmed_chars': untrimmedSize,
        'saved_chars': encoded.length,
        'duration_ms': totalStopwatch.elapsedMilliseconds,
      });
      if (kDebugMode) {
        _calendarDebugPrint(
          '[warmStart] saved cache reason=$debugReason '
          'level=$selectedLevel size=${encoded.length}',
        );
      }
    } catch (error) {
      _lastWarmStartCacheSaveOutcome = 'failed';
      recordCache('cache_save_ended', <String, Object?>{
        'outcome': 'failed',
        'duration_ms': totalStopwatch.elapsedMilliseconds,
        'safe_error_class': error.runtimeType.toString(),
      });
      rethrow;
    } finally {
      diagnostics.markAsyncWorkEnded(
        null,
        'warm_cache_save',
        token: diagnosticWork,
      );
    }
  }

  Future<void> _restoreWarmStartCacheIfAvailable({
    String reason = 'startup',
  }) async {
    final userId = _activeWarmStartUserId();
    if (userId == null) return;
    final projectionRevisionAtStart = _calendarProjectionMutationRevision;
    final diagnostics = CalendarHydrationDiagnostics.instance;
    final totalStopwatch = Stopwatch()..start();
    HydrationAsyncWorkToken? diagnosticWork;
    void recordCache(String marker, Map<String, Object?> fields) {
      diagnostics.recordCacheEvent(marker, fields, token: diagnosticWork);
    }

    void recordSkip(String skipReason) {
      recordCache('cache_restore_skipped', <String, Object?>{
        'reason': skipReason,
        'request_reason': reason,
        'duration_ms': totalStopwatch.elapsedMilliseconds,
      });
    }

    recordCache('cache_restore_requested', <String, Object?>{'reason': reason});
    if (_warmStartCacheRestoredForUserId == userId) {
      recordSkip('already_restored');
      return;
    }
    if (_warmStartRestoreInFlightForUserId == userId) {
      recordSkip('restore_in_flight');
      await _warmStartRestoreInFlightCompleter?.future;
      return;
    }
    if (_serverHydrationCommittedForUserId == userId) {
      recordSkip('server_already_committed');
      return;
    }

    diagnosticWork = diagnostics.markAsyncWorkStarted(
      null,
      'warm_cache_restore',
    );
    final restoreCompleter = Completer<void>();
    _warmStartRestoreInFlightCompleter = restoreCompleter;
    _warmStartRestoreInFlightForUserId = userId;
    try {
      final reminderExclusionStopwatch = Stopwatch()..start();
      await _loadOccurrenceExclusions();
      recordCache('cache_restore_reminder_exclusions_ready', <String, Object?>{
        'duration_ms': reminderExclusionStopwatch.elapsedMilliseconds,
      });

      // The generational snapshot is the lossless warm-start source. It owns
      // only cached presentation: live hydration remains free to publish
      // without waiting for, or depending on, durable persistence. Keep this
      // inside the existing single-flight restore so the snapshot and the
      // compacted legacy mirror can never race to paint different projections.
      final restoredSnapshot = await _restoreCalendarSnapshotStoreIfAvailable(
        userId: userId,
        reason: reason,
      );
      if (restoredSnapshot) {
        recordCache('cache_restore_snapshot_selected', <String, Object?>{
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        return;
      }

      // Snapshot absence/corruption is recoverable. The older compacted mirror
      // remains a migration fallback, but it is never allowed to overwrite a
      // complete snapshot or a newer server/local projection.
      final prefsStopwatch = Stopwatch()..start();
      final prefs = await SharedPreferences.getInstance();
      recordCache('cache_restore_prefs_ready', <String, Object?>{
        'duration_ms': prefsStopwatch.elapsedMilliseconds,
      });

      // Re-check after awaits — another restore, load, or auth may have won.
      if (!mounted) {
        recordSkip('unmounted_after_prefs');
        return;
      }
      if (_activeWarmStartUserId() != userId) {
        recordSkip('user_changed_after_prefs');
        return;
      }
      if (_warmStartCacheRestoredForUserId == userId) {
        recordSkip('restore_won_after_prefs');
        return;
      }
      if (_serverHydrationCommittedForUserId == userId) {
        recordSkip('server_won_after_prefs');
        return;
      }

      final raw = prefs.getString(_warmStartCacheKey(userId));
      if (raw == null || raw.trim().isEmpty) {
        _warmStartCacheRestoredForUserId = userId;
        recordCache('cache_miss', <String, Object?>{
          'duration_ms': totalStopwatch.elapsedMilliseconds,
        });
        return;
      }

      final decodeStopwatch = Stopwatch()..start();
      final decoded = jsonDecode(raw);
      if (decoded is! Map) {
        _warmStartCacheRestoredForUserId = userId;
        recordCache('cache_restore_skipped', <String, Object?>{
          'reason': 'invalid_root',
          'raw_chars': raw.length,
          'decode_ms': decodeStopwatch.elapsedMilliseconds,
        });
        return;
      }
      final json = Map<String, dynamic>.from(decoded);
      final savedAt = DateTime.tryParse(
        (json['cacheSavedAt'] as String?) ?? (json['savedAt'] as String?) ?? '',
      );
      final savedAgeMs = savedAt == null
          ? null
          : DateTime.now().toUtc().difference(savedAt.toUtc()).inMilliseconds;
      final snapshotUserId = (json['userId'] as String?)?.trim();
      if (snapshotUserId != null &&
          snapshotUserId.isNotEmpty &&
          snapshotUserId != userId) {
        _warmStartCacheRestoredForUserId = userId;
        recordSkip('snapshot_user_mismatch');
        return;
      }

      final flows = ((json['flows'] as List?) ?? const [])
          .map(_deserializeWarmStartFlow)
          .whereType<_Flow>()
          .toList(growable: false);
      final restoredTrackSkyFlowIds = flows
          .where((flow) => _isTrackSkyFlowName(flow.name))
          .map((flow) => flow.id)
          .where((flowId) => flowId > 0)
          .toSet();
      final legacySourceNotesByDay = <String, List<_Note>>{};
      final notesRaw = json['notes'];
      if (notesRaw is Map) {
        notesRaw.forEach((key, value) {
          if (value is! List) return;
          final notes = value
              .map(_deserializeWarmStartNote)
              .whereType<_Note>()
              .toList(growable: true);
          if (notes.isNotEmpty) {
            legacySourceNotesByDay[key.toString()] = notes;
          }
        });
      }
      final authoritativeProjection = deriveVisibleCalendarProjection<_Note>(
        source: legacySourceNotesByDay,
        pendingItems: const <CalendarPendingVisibleItem<_Note>>[],
        stableIdentityOf: _calendarNoteStableIdentity,
        suppressionRules: const <CalendarItemSuppressionRule<_Note>>[],
        reduceBucket: (_, notes) => _dedupeVisibleDayNotes(
          notes,
          trackSkyFlowIds: restoredTrackSkyFlowIds,
        ),
      );
      final authoritativeNotesByDay =
          Map<String, List<_Note>>.unmodifiable(<String, List<_Note>>{
            for (final entry in authoritativeProjection.buckets.entries)
              entry.key: List<_Note>.unmodifiable(entry.value),
          });
      final notesByDay = <String, List<_Note>>{
        for (final entry in authoritativeProjection.buckets.entries)
          entry.key: List<_Note>.of(entry.value),
      };

      final nextFlowId =
          (json['nextFlowId'] as num?)?.toInt() ??
          ((flows.isEmpty
                  ? 0
                  : flows
                        .map((flow) => flow.id)
                        .reduce((a, b) => a > b ? a : b)) +
              1);
      final totalCounts = _decodeWarmStartIntMap(json['flowTotalEventCounts']);
      final remainingCounts = _decodeWarmStartIntMap(
        json['flowRemainingEventCounts'],
      );

      if (!mounted) {
        recordSkip('unmounted_before_commit');
        return;
      }
      if (_activeWarmStartUserId() != userId) {
        recordSkip('user_changed_before_commit');
        return;
      }
      if (_warmStartCacheRestoredForUserId == userId) {
        recordSkip('restore_won_before_commit');
        return;
      }
      if (_serverHydrationCommittedForUserId == userId) {
        recordSkip('server_won_before_commit');
        return;
      }
      if (_calendarProjectionMutationRevision != projectionRevisionAtStart) {
        recordSkip('projection_changed_before_commit');
        return;
      }

      final reminderProjectionStopwatch = Stopwatch()..start();
      final projectedReminderCount = _projectReminderMembershipForHydration(
        flows: flows,
        notesByDay: notesByDay,
      );
      recordCache('cache_restore_reminder_projection', <String, Object?>{
        'added_count': projectedReminderCount,
        'duration_ms': reminderProjectionStopwatch.elapsedMilliseconds,
      });

      final commitStopwatch = Stopwatch()..start();
      _hydrationController.beginSession(userId);
      final restoredCatalogFingerprint = (json['catalogFingerprint'] as String?)
          ?.trim();
      final restoredViewportStart = DateTime.tryParse(
        json['authoritativeViewportStartUtc']?.toString() ?? '',
      )?.toUtc();
      final restoredViewportEnd = DateTime.tryParse(
        json['authoritativeViewportEndUtc']?.toString() ?? '',
      )?.toUtc();
      final restoredCoverage =
          restoredViewportStart != null &&
              restoredViewportEnd != null &&
              restoredViewportEnd.isAfter(restoredViewportStart)
          ? <CalendarHydrationInterval>[
              CalendarHydrationInterval(
                startUtc: restoredViewportStart,
                endUtc: restoredViewportEnd,
              ),
            ]
          : const <CalendarHydrationInterval>[];
      final affectedMonths = _calendarAffectedMonths(notesByDay, flows);
      _hydrationController.restoreCache(
        catalogFingerprint:
            restoredCatalogFingerprint != null &&
                restoredCatalogFingerprint.isNotEmpty
            ? restoredCatalogFingerprint
            : _catalogFingerprintForFlows(flows),
        coverageIntervals: restoredCoverage,
        applyPreparedState: () {
          _flows
            ..clear()
            ..addAll(flows);
          _replaceLiveNoteBuckets(notesByDay);
          _calendarAuthoritativeFlows = List<_Flow>.unmodifiable(flows);
          _calendarAuthoritativeNotesByDay = authoritativeNotesByDay;
          _flowTotalEventCounts
            ..clear()
            ..addAll(totalCounts);
          _flowRemainingEventCounts
            ..clear()
            ..addAll(remainingCounts);
          if (nextFlowId > 0) {
            _nextFlowId = math.max(_nextFlowId, nextFlowId);
          }
          _rebuildReminderRulesFromFlowsIfMissing();
          _publishCalendarMonthProjections(affectedMonths);
        },
      );
      _activeCalendarCoverage = _hydrationController.state.coverage;
      _latestCalendarRefreshStatus = CalendarRefreshStatus.idle;
      _warmStartCacheRestoredForUserId = userId;
      _warmStartSnapshotVisible = true;
      _lastAuthoritativeHydrationAt = DateTime.tryParse(
        (json['lastAuthoritativeHydrationAt'] as String?) ?? '',
      )?.toLocal();
      _lastAccountingAuthorityAt = DateTime.tryParse(
        (json['lastAccountingAuthorityAt'] as String?) ?? '',
      )?.toLocal();
      _accountingStale = (json['accountingStale'] as bool?) ?? false;
      _publishCalendarRefreshState();
      _notifyDayViewDataChanged(scheduleCacheSave: false);
      final restoredEventCount = notesByDay.values.fold<int>(
        0,
        (sum, notes) => sum + notes.length,
      );
      recordCache('cache_hit', <String, Object?>{
        'snapshot_schema_version':
            (json['snapshotSchemaVersion'] as num?)?.toInt() ?? 1,
        'compaction_level': (json['compactionLevel'] as String?) ?? 'legacy',
        'cache_center_day': json['cacheCenterDay'] as String?,
        'cache_past_days': (json['cachePastDays'] as num?)?.toInt(),
        'cache_future_days': (json['cacheFutureDays'] as num?)?.toInt(),
        'raw_chars': raw.length,
        'saved_age_ms': savedAgeMs,
        'cached_flow_count': flows.length,
        'cached_event_count': restoredEventCount,
        'cached_day_bucket_count': notesByDay.length,
        'decode_ms': decodeStopwatch.elapsedMilliseconds,
        'commit_ms': commitStopwatch.elapsedMilliseconds,
        'duration_ms': totalStopwatch.elapsedMilliseconds,
      });
      diagnostics.recordWarmCacheCommit(
        totalFlows: flows.length,
        totalEvents: restoredEventCount,
        totalDayBuckets: notesByDay.length,
        selectedDay: _hydrationSelectedDaySnapshot(notesByDay),
        token: diagnosticWork,
      );
      if (kDebugMode) {
        final totalNotes = notesByDay.values.fold<int>(
          0,
          (sum, list) => sum + list.length,
        );
        _calendarDebugPrint(
          '[warmStart] restored cache reason=$reason flows=${flows.length} notes=$totalNotes',
        );
      }
      _notifyDayViewDataChanged(scheduleCacheSave: false);
    } catch (e) {
      recordCache('cache_restore_failed', <String, Object?>{
        'duration_ms': totalStopwatch.elapsedMilliseconds,
        'safe_error_class': e.runtimeType.toString(),
      });
      if (kDebugMode) {
        _calendarDebugPrint(
          '[warmStart] restore failed reason=$reason error=$e',
        );
      }
    } finally {
      if (!restoreCompleter.isCompleted) {
        restoreCompleter.complete();
      }
      if (_warmStartRestoreInFlightForUserId == userId) {
        _warmStartRestoreInFlightForUserId = null;
        _warmStartRestoreInFlightCompleter = null;
      }
      diagnostics.markAsyncWorkEnded(
        null,
        'warm_cache_restore',
        token: diagnosticWork,
      );
    }
  }

  Future<void> _refreshCalendarStateFromServer() async {
    final snapshot = await _sharedCalendarsRepo.loadSnapshot();
    if (!mounted) return;
    setState(() {
      _calendarSummariesById = <String, SharedCalendarSummary>{
        for (final calendar in snapshot.calendars) calendar.id: calendar,
      };
      _hiddenCalendarIds = Set<String>.from(snapshot.hiddenCalendarIds);
      _personalCalendarId = snapshot.personalCalendarId;
      _calendarStateLoaded = true;
    });
    _publishWarmStateSnapshot();
  }

  Future<CalendarHydrationJobDisposition> _scheduleCalendarStateRefresh({
    required String reason,
  }) {
    return _scheduleMaintenanceJob(
      kind: CalendarHydrationIntentKind.calendarState,
      reason: reason,
      dedupeKey: 'calendar_state',
      run: _refreshCalendarStateFromServer,
      priority: 30,
    );
  }

  void _rememberSharedCalendarSnapshot(
    SharedCalendarSummary calendar, {
    bool publishWarmState = true,
  }) {
    final calendarId = _normalizeCalendarId(calendar.id);
    if (calendarId == null) return;
    _calendarSummariesById[calendarId] = calendar;
    if (publishWarmState) {
      _publishWarmStateSnapshot();
    }
  }

  void _seedSharedCalendarFlows(
    Iterable<_Flow> flows, {
    bool publishWarmState = false,
  }) {
    final incoming = flows
        .where((flow) => flow.id > 0)
        .map(_CalendarWarmStateStore._copyFlow)
        .toList(growable: false);
    if (incoming.isEmpty) return;
    final nextCatalog = mergeCalendarCatalogByIdentity<_Flow, int>(
      source: _flows,
      incoming: incoming,
      identityOf: (flow) => flow.id > 0 ? flow.id : null,
    );
    _flows
      ..clear()
      ..addAll(nextCatalog);
    for (final flow in incoming) {
      if (flow.id >= _nextFlowId) {
        _nextFlowId = flow.id + 1;
      }
    }
    _rebuildReminderRulesFromFlowsIfMissing();
    _bumpDataVersion();
    if (publishWarmState) {
      _publishWarmStateSnapshot();
    }
  }

  _Note _noteFromSharedCalendarEventSnapshot(
    _SharedCalendarEventDetailSnapshot snapshot,
  ) {
    return _Note(
      id: snapshot.eventId,
      clientEventId: snapshot.clientEventId,
      calendarId: snapshot.calendarId,
      calendarName: snapshot.calendarName,
      title: snapshot.title,
      detail: snapshot.detail,
      location: snapshot.location,
      allDay: snapshot.allDay,
      start: snapshot.allDay
          ? null
          : TimeOfDay.fromDateTime(snapshot.startsAtLocal),
      end: snapshot.allDay || snapshot.endsAtLocal == null
          ? null
          : TimeOfDay.fromDateTime(snapshot.endsAtLocal!),
      flowId: snapshot.flowId ?? -1,
      manualColor: snapshot.calendarColor,
      category: snapshot.category,
      isReminder: snapshot.isReminder,
      reminderId: snapshot.reminderId,
      alertOffsetMinutes: snapshot.alertOffsetMinutes,
      actionId: snapshot.actionId,
      behaviorPayload: snapshot.behaviorPayload,
    );
  }

  _Note _noteFromSharedCalendarFiledEvent({
    required SharedCalendarSummary calendar,
    required FiledEvent filedEvent,
  }) {
    return _noteFromSharedCalendarEventSnapshot(
      CalendarPage._sharedCalendarEventDetailSnapshotForFiledEvent(
        calendar: calendar,
        filedEvent: filedEvent,
      ),
    );
  }

  bool _sharedCalendarSeedConflict(
    String sourceDayKey,
    _Note source,
    String pendingDayKey,
    _Note pending,
  ) {
    if (sourceDayKey != pendingDayKey) return false;
    if (_visibleDayNoteBaseKey(source) == _visibleDayNoteBaseKey(pending)) {
      return true;
    }
    return (source.flowId ?? -1) <= 0 &&
        (pending.flowId ?? -1) <= 0 &&
        _standaloneDedupeKey(source) == _standaloneDedupeKey(pending);
  }

  void _publishSharedCalendarSeedNotes({
    required String dayKey,
    required Iterable<_Note> notes,
  }) {
    final incoming = notes.toList(growable: false);
    if (incoming.isEmpty) return;
    _publishCalendarNoteMutation(
      upserts: <CalendarPendingVisibleItem<_Note>>[
        for (final note in incoming)
          CalendarPendingVisibleItem<_Note>(dayKey: dayKey, item: note),
      ],
      sourceConflictRule: _sharedCalendarSeedConflict,
    );
  }

  void _seedSameDaySharedCalendarFiledEvents({
    required SharedCalendarSummary calendar,
    required List<FiledEvent> filedEvents,
    required int kYear,
    required int kMonth,
    required int kDay,
  }) {
    if (filedEvents.isEmpty) return;
    final key = _kKey(kYear, kMonth, kDay);
    final incoming = <_Note>[
      for (final filedEvent in filedEvents)
        _noteFromSharedCalendarFiledEvent(
          calendar: calendar,
          filedEvent: filedEvent,
        ),
    ];
    _publishSharedCalendarSeedNotes(dayKey: key, notes: incoming);

    if (kDebugMode) {
      _calendarDebugPrint(
        '[SharedCalendarEventTap] seeded same-day filed events '
        'calendarId=${calendar.id} day=$key filed=${filedEvents.length} '
        'notes=${_notes[key]?.length ?? 0}',
      );
    }
  }

  bool _noteMatchesEventDetailRestorationState(
    _Note note,
    EventDetailRestorationState state,
  ) {
    switch (state.identityType) {
      case eventDetailIdentityClientEventId:
        return note.clientEventId?.trim() == state.identityValue;
      case eventDetailIdentityEventId:
        return note.id?.trim() == state.identityValue;
      case eventDetailIdentityReminderId:
        return note.reminderId?.trim() == state.identityValue;
    }
    return false;
  }

  void _seedOneShotSharedCalendarEventSnapshot({
    required int kYear,
    required int kMonth,
    required int kDay,
    required _SharedCalendarEventDetailSnapshot snapshot,
    required EventDetailRestorationState detail,
  }) {
    final note = _noteFromSharedCalendarEventSnapshot(snapshot);
    final key = _kKey(kYear, kMonth, kDay);
    final bucket = _notes[key] ?? const <_Note>[];
    if (bucket.any(
      (existing) => _noteMatchesEventDetailRestorationState(existing, detail),
    )) {
      if (kDebugMode) {
        _calendarDebugPrint(
          '[SharedCalendarEventTap] using cached real detail note '
          '${snapshot.debugIdentity} day=$key notes=${bucket.length}',
        );
      }
      return;
    }
    _publishSharedCalendarSeedNotes(dayKey: key, notes: <_Note>[note]);

    if (kDebugMode) {
      _calendarDebugPrint(
        '[SharedCalendarEventTap] seeded one-shot detail snapshot '
        '${snapshot.debugIdentity} day=$key notes=${bucket.length}',
      );
    }
  }

  bool _consumePendingSharedCalendarRealDayViewIntentIfAny() {
    final intent = CalendarPage._pendingSharedCalendarRealDayViewIntent;
    if (intent == null) return false;
    CalendarPage._pendingSharedCalendarRealDayViewIntent = null;
    _sharedCalendarRealDayViewOpening = true;
    _pendingPersistentDayViewState = null;
    _persistentDayViewRestoreAttempted = true;
    _calendarOverlayRestoreAttempted = true;
    _calendarOverlayRestoreInFlight = false;
    _calendarOverlayRestorePresentationStarted = false;

    _rememberSharedCalendarSnapshot(intent.calendar, publishWarmState: false);
    _flows
      ..clear()
      ..addAll(intent.warmStartFlows);
    _seedSharedCalendarFlows(intent.sharedCalendarFlows);
    _notes
      ..clear()
      ..addEntries(
        intent.warmStartNotes.entries.map(
          (entry) => MapEntry(entry.key, List<_Note>.from(entry.value)),
        ),
      );
    _calendarSummariesById
      ..clear()
      ..addAll(intent.warmCalendarSummariesById);
    _hiddenCalendarIds = Set<String>.from(intent.warmHiddenCalendarIds);
    _personalCalendarId = intent.warmPersonalCalendarId;
    _calendarStateLoaded = intent.warmCalendarSummariesById.isNotEmpty;
    if (_flows.isNotEmpty) {
      final maxFlowId = _flows
          .map((flow) => flow.id)
          .reduce((a, b) => a > b ? a : b);
      _nextFlowId = math.max(_nextFlowId, maxFlowId + 1);
    }
    _seedSameDaySharedCalendarFiledEvents(
      calendar: intent.calendar,
      filedEvents: intent.sameCalendarEvents,
      kYear: intent.kYear,
      kMonth: intent.kMonth,
      kDay: intent.kDay,
    );
    _seedOneShotSharedCalendarEventSnapshot(
      kYear: intent.kYear,
      kMonth: intent.kMonth,
      kDay: intent.kDay,
      snapshot: intent.snapshot,
      detail: intent.detail,
    );
    _rebuildReminderRulesFromFlowsIfMissing();
    _warmStartCacheRestoredForUserId = _activeWarmStartUserId();
    _warmStartSnapshotVisible =
        intent.warmStartFlows.isNotEmpty || intent.warmStartNotes.isNotEmpty;
    _lastAuthoritativeHydrationAt = null;
    _lastAccountingAuthorityAt = null;
    _accountingStale = false;
    _activeCalendarCoverage = null;
    _latestCalendarRefreshStatus = CalendarRefreshStatus.idle;
    _publishCalendarRefreshState();
    _dataVersion++;
    _notifyDayViewDataChanged(scheduleCacheSave: false);

    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _openDayView(
        context,
        intent.kYear,
        intent.kMonth,
        intent.kDay,
        initialFirstVisibleMinute:
            CalendarPage._firstVisibleMinuteFromSharedCalendarSnapshot(
              intent.snapshot,
            ),
        initialEventDetailRestorationState: intent.detail,
        debugOpenSource: 'shared_calendar_event_tap',
      );
      _sharedCalendarRealDayViewOpening = false;
      unawaited(
        _scheduleCalendarStateRefresh(
          reason: 'shared_calendar_event_tap_background',
        ),
      );
      unawaited(
        _requestInitialStartupRun(
          reason: 'shared_calendar_event_tap_background',
        ),
      );
    });

    if (kDebugMode) {
      final key = _kKey(intent.kYear, intent.kMonth, intent.kDay);
      _calendarDebugPrint(
        '[SharedCalendarEventTap] CalendarPage init consumed real day '
        'intent ${intent.snapshot.debugIdentity} '
        'warmFlows=${intent.warmStartFlows.length} '
        'warmDayNotes=${intent.warmStartNotes[key]?.length ?? 0}',
      );
    }
    return true;
  }

  Future<void> _requestInitialStartupRun({required String reason}) async {
    final user = Supabase.instance.client.auth.currentUser;
    if (user == null) {
      _pendingInitialHydration = true;
      return;
    }
    final userId = user.id;
    if (_initialStartupUserId == userId) {
      if (_startupFlight != null && !(_startupFlight!.isCompleted)) {
        await _startupFlight!.future;
      }
      return;
    }
    _initialStartupUserId = userId;
    await _requestStartupRun(reason: reason);
  }

  List<String> _stringListFromRestoration(Object? raw) {
    if (raw is! Iterable) return const <String>[];
    return raw
        .map((value) => value.toString().trim())
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
  }

  Map<String, dynamic> _calendarOverlayParentMetadata() {
    final dayViewState = _activeDayViewRestorationState;
    if (dayViewState != null && dayViewState.isOpen) {
      return <String, dynamic>{
        'parentSurface': _kCalendarParentSurfaceDayView,
        'dayView': dayViewState.toJson(),
      };
    }
    return const <String, dynamic>{
      'parentSurface': _kCalendarParentSurfaceRoot,
    };
  }

  Future<void> _saveCalendarOverlayState(
    String kind,
    Map<String, dynamic> state,
  ) async {
    final normalizedKind = kind.trim();
    if (normalizedKind.isEmpty) return;
    if (normalizedKind == _kCalendarOverlayKindFlowStudio &&
        CalendarPage._isTransientFlowStudioEditorState(state)) {
      return;
    }
    try {
      await AppRestorationService.instance.saveOverlayStack(
        <Map<String, dynamic>>[
          <String, dynamic>{
            'kind': normalizedKind,
            'parentRoute': '/',
            ..._calendarOverlayParentMetadata(),
            'updatedAtMs': DateTime.now().millisecondsSinceEpoch,
            ...state,
          },
        ],
      );
      unawaited(RestorationCoordinator.instance.flush());
    } catch (error) {
      NavigationTrace.instance.record(
        'calendar overlay state save skipped',
        state: <String, Object?>{
          'kind': normalizedKind,
          'error': error.runtimeType,
        },
      );
    }
  }

  Future<void> _clearCalendarOverlayState(String kind) async {
    if (!mounted) {
      return;
    }
    final stack = await AppRestorationService.instance.readOverlayStack();
    final next = stack
        .where((entry) => entry['kind'] != kind)
        .toList(growable: false);
    await AppRestorationService.instance.saveOverlayStack(
      next,
      reason: OverlayStackMutationReason.userDismissed,
    );
  }

  bool _sameEventDetailRestorationState(
    EventDetailRestorationState? a,
    EventDetailRestorationState b,
  ) {
    return a != null &&
        a.kYear == b.kYear &&
        a.kMonth == b.kMonth &&
        a.kDay == b.kDay &&
        a.identityType == b.identityType &&
        a.identityValue == b.identityValue;
  }

  Future<void> _enqueueCalendarEventDetailOverlayWrite(
    Future<void> Function() write,
  ) {
    final next = _calendarEventDetailOverlayWriteQueue
        .catchError((Object error, StackTrace stackTrace) {
          if (kDebugMode) {
            _calendarDebugPrint(
              '[eventDetailOverlay] prior write failed: $error',
            );
            _calendarDebugPrint('$stackTrace');
          }
        })
        .then((_) => write());
    _calendarEventDetailOverlayWriteQueue = next.catchError((
      Object error,
      StackTrace stackTrace,
    ) {
      if (kDebugMode) {
        _calendarDebugPrint('[eventDetailOverlay] write failed: $error');
        _calendarDebugPrint('$stackTrace');
      }
    });
    return next;
  }

  Future<void> _saveCalendarEventDetailOverlayState(
    EventDetailRestorationState state,
  ) {
    final revision = ++_calendarEventDetailOverlayRevision;
    _activeCalendarEventDetailRestoration = state;
    final payload = state
        .copyWith(
          parentSurface: _kCalendarParentSurfaceRoot,
          clearUpdatedAtMs: true,
        )
        .toJson();
    return _enqueueCalendarEventDetailOverlayWrite(() async {
      if (revision != _calendarEventDetailOverlayRevision ||
          !_sameEventDetailRestorationState(
            _activeCalendarEventDetailRestoration,
            state,
          )) {
        return;
      }
      await _saveCalendarOverlayState(
        _kCalendarOverlayKindEventDetail,
        payload,
      );
    });
  }

  Future<void> _saveCalendarEventDetailOverlayForTarget(
    DayViewSheetEventTarget target,
  ) async {
    final state = eventDetailRestorationStateForTarget(
      target,
      parentSurface: _kCalendarParentSurfaceRoot,
    );
    if (state == null) {
      await _clearCalendarEventDetailOverlayState();
      return;
    }
    await _saveCalendarEventDetailOverlayState(state);
  }

  void _handleCalendarEventDetailRestorationChanged(
    EventDetailRestorationState? state,
  ) {
    if (state == null) {
      if (!_preserveEventDetailOverlayForOrientationHandoff) {
        _activeCalendarEventDetailRestoration = null;
      }
      unawaited(_clearCalendarEventDetailOverlayState());
      return;
    }
    _activeCalendarEventDetailRestoration = state;
    unawaited(_saveCalendarEventDetailOverlayState(state));
  }

  Future<void> _clearCalendarEventDetailOverlayState() {
    if (_preserveEventDetailOverlayForOrientationHandoff) {
      return Future<void>.value();
    }
    final revision = ++_calendarEventDetailOverlayRevision;
    _activeCalendarEventDetailRestoration = null;
    return _enqueueCalendarEventDetailOverlayWrite(() async {
      if (revision != _calendarEventDetailOverlayRevision ||
          _activeCalendarEventDetailRestoration != null) {
        return;
      }
      await _clearCalendarOverlayState(_kCalendarOverlayKindEventDetail);
    });
  }

  DayViewSheetEventTarget? _calendarEventDetailTargetFromState(
    EventDetailRestorationState state,
  ) {
    return eventDetailTargetFromRestorationState(
      state: state,
      events: _calendarSheetEventsForDay(state.kYear, state.kMonth, state.kDay),
    );
  }

  Future<void> _openCalendarEventDetailSheet(
    DayViewSheetEventTarget initialTarget,
  ) async {
    if (!mounted) return;
    if (!CalendarEventDetailSheetCoordinator.tryMarkOpenOrOpening()) {
      return;
    }

    try {
      await _saveCalendarEventDetailOverlayForTarget(initialTarget);
      if (!mounted) return;

      await showModalBottomSheet(
        context: context,
        backgroundColor: Colors.transparent,
        isScrollControlled: true,
        builder: (_) => CalendarEventDetailSheet(
          hostContext: context,
          initialTarget: initialTarget,
          flowResolver: _calendarChromeFlowDataForId,
          activeLedgerFlowIds: _buildActiveLedgerFlowIds(),
          resolveCurrentEventTarget: _resolveCalendarCurrentEventTarget,
          resolveAdjacentEventTarget: _resolveCalendarAdjacentEventTarget,
          onTargetChanged: (target) {
            unawaited(_saveCalendarEventDetailOverlayForTarget(target));
          },
          onManageFlows: _getMyFlowsCallback(),
          onEditNote: _editNoteByEvent,
          onDeleteNote: _deleteNoteByEvent,
          onShareNote: (event) async => _shareNoteSimple(event),
          onEditReminder: _editReminderById,
          onEndReminder: _endReminderRule,
          onShareReminder: (event) async => _shareNoteSimple(event),
          onEndFlow: _endFlow,
          onAppendToJournal: _appendToJournalAndRefresh,
          onWriteJournalResponse: _writeMaatJournalResponseBlockAndRefresh,
          onSaveFlow: _saveFlowById,
          dataVersion: _dayViewDataVersion,
          onRecordCompletion:
              ({
                required String clientEventId,
                required int flowId,
                required DateTime completedOnDate,
                Map<String, dynamic>? metadata,
              }) => _recordEventCompletion(
                clientEventId: clientEventId,
                flowId: flowId,
                completedOnDate: completedOnDate,
                metadata: metadata,
              ),
          onUnrecordCompletion: _unrecordEventCompletion,
          onRemoveCompletionBadge: _removeCompletionBadgeAndRefresh,
        ),
      );
    } finally {
      CalendarEventDetailSheetCoordinator.markClosed();
      await _clearCalendarEventDetailOverlayState();
    }
  }

  Future<bool> _restoreCalendarEventDetailOverlay(
    Map<String, dynamic> overlay,
  ) async {
    if (!_restored || !_initialViewportSettled) return false;
    final startupFlight = _startupFlight;
    if (startupFlight != null && !startupFlight.isCompleted) {
      return false;
    }

    final state = EventDetailRestorationState.fromJson(overlay);
    if (state == null) {
      await _clearCalendarEventDetailOverlayState();
      return true;
    }

    final target = _calendarEventDetailTargetFromState(state);
    if (target == null) {
      await _clearCalendarEventDetailOverlayState();
      return true;
    }

    await _openCalendarEventDetailSheet(target);
    return true;
  }

  void _schedulePersistentOverlayRestore({required String reason}) {
    if (_sharedCalendarRealDayViewOpening) {
      return;
    }
    if (_calendarOverlayRestoreAttempted || _calendarOverlayRestoreInFlight) {
      return;
    }
    if (RestorationCoordinator.instance.isRestoreSurfaceSuppressed(
      RestorationCoordinator.calendarOverlayStackSurface,
    )) {
      return;
    }
    _calendarOverlayRestoreAttempted = true;
    _calendarOverlayRestorePresentationStarted = false;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      unawaited(_restorePersistentCalendarOverlayWithRetries(reason: reason));
    });
  }

  String _currentRouteTraceLabel() {
    final location = CalendarPage._currentRouteLocationForContext(context);
    final uri = Uri.tryParse(location);
    if (uri == null) return location.trim().isEmpty ? '/' : location.trim();
    final path = uri.path.isEmpty ? '/' : uri.path;
    final queryKeys =
        uri.queryParameters.keys
            .where((key) => key.trim().isNotEmpty)
            .toList(growable: false)
          ..sort();
    if (queryKeys.isEmpty) return path;
    return '$path?${queryKeys.map((key) => '$key=<redacted>').join('&')}';
  }

  bool _schedulePendingDetachedLaunchActionIfAny() {
    final pendingSearchResult = CalendarPage._pendingDetachedSearchResult;
    if (pendingSearchResult != null) {
      CalendarPage._pendingDetachedSearchResult = null;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _openDayView(
          context,
          pendingSearchResult.ky,
          pendingSearchResult.km,
          pendingSearchResult.kd,
          initialEventDetailRestorationState: pendingSearchResult.eventDetail,
        );
      });
      return true;
    }

    final pendingSearchDay = CalendarPage._pendingDetachedSearchDay;
    if (pendingSearchDay != null) {
      CalendarPage._pendingDetachedSearchDay = null;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _openDaySheet(
          pendingSearchDay.ky,
          pendingSearchDay.km,
          pendingSearchDay.kd,
        );
      });
      return true;
    }

    final action = CalendarPage._pendingDetachedLaunchAction;
    if (action == null) return false;
    CalendarPage._pendingDetachedLaunchAction = null;

    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      switch (action) {
        case _CalendarDetachedLaunchAction.quickAdd:
          unawaited(_openQuickAddSheet());
          break;
        case _CalendarDetachedLaunchAction.sharedCalendars:
          unawaited(_openSharedCalendarsSheet());
          break;
        case _CalendarDetachedLaunchAction.flowStudio:
          _getFlowStudioCallback()(null);
          break;
        case _CalendarDetachedLaunchAction.myFlows:
          _openMyFlowsList();
          break;
        case _CalendarDetachedLaunchAction.search:
          _openSearch();
          break;
      }
    });
    return true;
  }

  Future<void> _restorePersistentCalendarOverlayWithRetries({
    required String reason,
  }) async {
    var restored = false;
    try {
      for (var attempt = 0; attempt < 30; attempt++) {
        if (!mounted) return;
        restored = await _restorePersistentCalendarOverlay(
          reason: '$reason:$attempt',
        );
        if (restored) return;
        await Future<void>.delayed(const Duration(milliseconds: 150));
      }
    } finally {
      if (!restored) {
        _calendarOverlayRestoreAttempted = false;
      }
    }
  }

  Future<bool> _restorePersistentCalendarOverlay({
    required String reason,
  }) async {
    if (_calendarOverlayRestoreInFlight) return false;
    _calendarOverlayRestoreInFlight = true;
    try {
      final snapshot = await RestorationCoordinator.instance.readBestSnapshot(
        includeRemote: Supabase.instance.client.auth.currentSession != null,
      );
      final stack =
          snapshot.snapshot?.overlayStack ?? const <Map<String, dynamic>>[];
      if (!mounted || stack.isEmpty) return false;
      final overlay = stack.lastWhere(
        (entry) =>
            entry['kind'] == _kCalendarOverlayKindSharedCalendars ||
            entry['kind'] == _kCalendarOverlayKindFlowStudio ||
            entry['kind'] == _kCalendarOverlayKindEventDetail,
        orElse: () => const <String, dynamic>{},
      );
      if (overlay.isEmpty) return false;

      final parentRoute = (overlay['parentRoute'] as String?)?.trim();
      if (parentRoute != null &&
          parentRoute.isNotEmpty &&
          !CalendarPage._isRootRouteLocation(parentRoute)) {
        return false;
      }

      final savedDayView = snapshot.snapshot?.dayView;
      if (_restoreDayViewRouteOnStartup &&
          savedDayView != null &&
          savedDayView.isOpen &&
          !_persistentDayViewRestoreAttempted) {
        return false;
      }

      if (overlay['kind'] == _kCalendarOverlayKindEventDetail) {
        if (savedDayView != null && savedDayView.isOpen) {
          await _clearCalendarEventDetailOverlayState();
          return true;
        }
        final parentSurface = (overlay['parentSurface'] as String?)?.trim();
        if (parentSurface != null &&
            parentSurface.isNotEmpty &&
            parentSurface != _kCalendarParentSurfaceRoot) {
          await _clearCalendarEventDetailOverlayState();
          return true;
        }
        final startupFlight = _startupFlight;
        if (!_restored ||
            !_initialViewportSettled ||
            (startupFlight != null && !startupFlight.isCompleted)) {
          return false;
        }
      }

      final restoreKey = CalendarPage._calendarOverlayRestoreSurfaceKey(
        overlay,
      );
      if (!RestorationCoordinator.instance.claimRestoreSurface(
        restoreKey,
        requireRootTarget: true,
      )) {
        return true;
      }

      _calendarOverlayRestorePresentationStarted = true;
      if (overlay['kind'] == _kCalendarOverlayKindSharedCalendars) {
        await _openSharedCalendarsSheet(restorationState: overlay);
        return true;
      }

      if (overlay['kind'] == _kCalendarOverlayKindFlowStudio) {
        await _restoreFlowStudioOverlay(overlay);
        return true;
      }

      if (overlay['kind'] == _kCalendarOverlayKindEventDetail) {
        return _restoreCalendarEventDetailOverlay(overlay);
      }
      return false;
    } finally {
      _calendarOverlayRestoreInFlight = false;
    }
  }

  Future<void> _restoreFlowStudioOverlay(Map<String, dynamic> overlay) async {
    final mode = (overlay['mode'] as String?)?.trim();
    if (mode == _kFlowStudioModeMyFlows) {
      _openMyFlowsList(
        initialFlowId: (overlay['initialFlowId'] as num?)?.toInt(),
      );
      return;
    }

    if (mode == _kFlowStudioModeEditor) {
      final draft = _FlowStudioDraft.fromJson(
        await AppRestorationService.instance.readEditorState(
          _kFlowStudioDraftEditorKey,
        ),
      );
      final editFlowId =
          draft?.editingFlowId ?? (overlay['editFlowId'] as num?)?.toInt();
      await _openFlowStudioSheet(
        continuityState: <String, dynamic>{
          'mode': _kFlowStudioModeEditor,
          if (editFlowId != null) 'editFlowId': editFlowId,
        },
        rootBuilder: (_) =>
            _FlowStudioPage(existingFlows: _flows, editFlowId: editFlowId),
      );
      return;
    }

    if (mode == _kFlowStudioModeMaatFlows ||
        mode == _kFlowStudioModeMaatTemplate) {
      final templateKey = (overlay['templateKey'] as String?)?.trim();
      await _openFlowStudioSheet(
        continuityState: <String, dynamic>{
          'mode': mode,
          if (templateKey != null && templateKey.isNotEmpty)
            'templateKey': templateKey,
        },
        rootBuilder: _buildFlowStudioHubPage,
        initialRoutesBuilder: (navigator) {
          final hubRoute = MaterialPageRoute<dynamic>(
            builder: (ctx) => _buildFlowStudioHubPage(ctx),
          );
          final listRoute = MaterialPageRoute<dynamic>(
            builder: (ctx) => _buildMaatFlowsListPage(ctx),
          );
          unawaited(
            listRoute.popped.then((_) async {
              if (!mounted ||
                  RestorationCoordinator
                      .instance
                      .shouldPreserveOverlayForLifecycleClose) {
                return;
              }
              await _saveCalendarOverlayState(
                _kCalendarOverlayKindFlowStudio,
                const <String, dynamic>{'mode': _kFlowStudioModeHub},
              );
            }),
          );
          if (mode != _kFlowStudioModeMaatTemplate ||
              templateKey == null ||
              templateKey.isEmpty) {
            return <Route<dynamic>>[hubRoute, listRoute];
          }

          final template = _maatTemplateForKey(templateKey);
          if (template == null) return <Route<dynamic>>[hubRoute, listRoute];

          final detailRoute = MaterialPageRoute<int?>(
            builder: (_) => _MaatFlowTemplateDetailPage(
              template: template,
              alreadyJoined: _hasActiveMaatInstanceFor(template.key),
              addInstance:
                  ({
                    required _MaatFlowTemplate template,
                    DateTime? startDate,
                    bool? useKemetic,
                    TrackSkyTimeZone? trackSkyTimeZone,
                    int? alertMinutesBefore,
                    bool? dawnDiscreetMode,
                    DawnHouseRiteLens? dawnLens,
                    bool? eveningDiscreetMode,
                    EveningThresholdRiteLens? eveningLens,
                    int? eveningFallbackMinutesAfterMidnight,
                    TheWeighingLens? theWeighingLens,
                    OfferingTableLens? offeringTableLens,
                    bool? offeringNoCupMode,
                    TheTendingLens? theTendingLens,
                    KeptWordLens? keptWordLens,
                    CourseLens? courseLens,
                    MoonReturnLens? moonReturnLens,
                    WagLens? wagLens,
                    DecanWatchLens? decanWatchLens,
                    OpenHandLens? openHandLens,
                    DjedLens? djedLens,
                    List<ReadingHouseSitting>? readingHouseSittings,
                    String? eveningThresholdInitialCarry,
                  }) async {
                    final id = await _addMaatFlowInstance(
                      template: template,
                      startDate: startDate,
                      useKemetic: useKemetic ?? false,
                      trackSkyTimeZone: trackSkyTimeZone,
                      alertMinutesBefore:
                          alertMinutesBefore ?? _alertNoneMinutes,
                      dawnDiscreetMode: dawnDiscreetMode ?? false,
                      dawnLens: dawnLens ?? DawnHouseRiteLens.neutral,
                      eveningDiscreetMode: eveningDiscreetMode ?? false,
                      eveningLens:
                          eveningLens ?? EveningThresholdRiteLens.neutral,
                      eveningFallbackMinutesAfterMidnight:
                          eveningFallbackMinutesAfterMidnight ??
                          kEveningThresholdDefaultFallbackMinutes,
                      theWeighingLens:
                          theWeighingLens ?? TheWeighingLens.neutral,
                      offeringTableLens:
                          offeringTableLens ?? OfferingTableLens.neutral,
                      offeringNoCupMode: offeringNoCupMode ?? false,
                      theTendingLens: theTendingLens ?? TheTendingLens.neutral,
                      keptWordLens: keptWordLens ?? KeptWordLens.neutral,
                      courseLens: courseLens ?? CourseLens.neutral,
                      moonReturnLens: moonReturnLens ?? MoonReturnLens.neutral,
                      wagLens: wagLens ?? WagLens.neutral,
                      decanWatchLens: decanWatchLens ?? DecanWatchLens.neutral,
                      openHandLens: openHandLens ?? OpenHandLens.neutral,
                      djedLens: djedLens ?? DjedLens.neutral,
                      readingHouseSittings: readingHouseSittings,
                      eveningThresholdInitialCarry:
                          eveningThresholdInitialCarry,
                    );
                    return id;
                  },
              onJoined: (flowId) => _completeMountedMaatJoinWithDayView(
                flowId: flowId,
                templateKey: template.key,
              ),
            ),
          );
          unawaited(
            detailRoute.popped.then((importedFlowId) async {
              if (!mounted ||
                  RestorationCoordinator
                      .instance
                      .shouldPreserveOverlayForLifecycleClose) {
                return;
              }
              if (importedFlowId != null && importedFlowId > 0) {
                CalendarPage._rememberJoinedMaatFlowTemplate(
                  templateKey: template.key,
                  flowId: importedFlowId,
                );
                _myFlowsFilingSnapshotCache = null;
                await _flowsRepo.clearMyFiledFlowsCache();
                // Mounted restore join: notes already in _notes; open Day View.
                if (_firstChronologicalNoteForFlow(importedFlowId) == null) {
                  if (mounted) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(
                        content: Text(
                          'Could not open the first day of this flow.',
                        ),
                      ),
                    );
                  }
                  await _saveCalendarOverlayState(
                    _kCalendarOverlayKindFlowStudio,
                    const <String, dynamic>{'mode': _kFlowStudioModeMaatFlows},
                  );
                  return;
                }
                if (mounted) {
                  final rootNavigator = Navigator.of(
                    context,
                    rootNavigator: true,
                  );
                  if (rootNavigator.canPop()) {
                    rootNavigator.pop();
                  }
                }
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (!mounted) return;
                  _openDayViewForStagedFlow(importedFlowId);
                });
                return;
              }
              await _saveCalendarOverlayState(
                _kCalendarOverlayKindFlowStudio,
                const <String, dynamic>{'mode': _kFlowStudioModeMaatFlows},
              );
            }),
          );
          return <Route<dynamic>>[hubRoute, listRoute, detailRoute];
        },
      );
      return;
    }

    _getFlowStudioCallback()(null);
  }

  _MaatFlowTemplate? _maatTemplateForKey(String key) {
    final trimmed = key.trim();
    if (trimmed.isEmpty) return null;
    for (final template in _kMaatFlowTemplates) {
      if (template.key == trimmed) return template;
    }
    return null;
  }

  Future<T?> _pushFlowStudioRoute<T>(
    NavigatorState navigator,
    Route<T> route, {
    required Map<String, dynamic> visibleState,
    required Map<String, dynamic> returnState,
    bool persistOverlay = true,
  }) async {
    if (persistOverlay) {
      await _saveCalendarOverlayState(
        _kCalendarOverlayKindFlowStudio,
        visibleState,
      );
    }
    try {
      return await navigator.push<T>(route);
    } finally {
      if (persistOverlay &&
          mounted &&
          navigator.mounted &&
          !RestorationCoordinator
              .instance
              .shouldPreserveOverlayForLifecycleClose) {
        await _saveCalendarOverlayState(
          _kCalendarOverlayKindFlowStudio,
          returnState,
        );
      }
    }
  }

  Future<_FlowStudioResult?> _pushFlowStudioEditor(
    NavigatorState navigator, {
    int? editFlowId,
    ImportFlowData? importData,
    required Map<String, dynamic> returnState,
    bool persistOverlay = true,
  }) {
    final readingHouseFlow = importData == null
        ? _readingHouseFlowForEditor(editFlowId)
        : null;
    if (readingHouseFlow != null) {
      return _pushFlowStudioRoute<_FlowStudioResult>(
        navigator,
        MaterialPageRoute<_FlowStudioResult>(
          builder: (_) => _ReadingHouseAuthoringPage(
            flow: readingHouseFlow,
            calendar: _calendarSummary(readingHouseFlow.calendarId),
            personalCalendarId: _personalCalendarId,
            sharedCalendarsRepo: _sharedCalendarsRepo,
            onCalendarChanged: _moveReadingHouseFlowToCalendar,
          ),
        ),
        visibleState: <String, dynamic>{
          'mode': _kFlowStudioModeEditor,
          'editFlowId': editFlowId,
          'templateKey': kReadingHouseFlowKey,
        },
        returnState: returnState,
        persistOverlay: persistOverlay,
      );
    }

    Future<void> handleResult(_FlowStudioResult result) async {
      final opensDayView = CalendarPage._shouldOpenDayViewAfterFlowStudioAdd(
        result,
      );
      final skipExplicitHydrate = CalendarPage._shouldSkipExplicitHydrate(
        result,
      );
      final savedId = await _persistFlowStudioResult(result);
      if (mounted && !skipExplicitHydrate) {
        await _requestHydration(
          _CalendarHydrationRequest.catalogReconcile(
            reason: 'flow_studio_editor_save',
          ),
        );
      }
      if (opensDayView && savedId != null) {
        _completeMountedStagedFlowAddWithDayView(savedId);
      } else if (navigator.mounted) {
        navigator.pop();
      }
    }

    return _pushFlowStudioRoute<_FlowStudioResult>(
      navigator,
      MaterialPageRoute<_FlowStudioResult>(
        builder: (_) => _FlowStudioPage(
          existingFlows: _flows,
          editFlowId: editFlowId,
          importData: importData,
          onRouteResult: handleResult,
        ),
      ),
      visibleState: <String, dynamic>{
        'mode': _kFlowStudioModeEditor,
        if (editFlowId != null) 'editFlowId': editFlowId,
      },
      returnState: returnState,
      persistOverlay: persistOverlay,
    );
  }

  Future<void> _persistReturnedFlowStudioResult(
    _FlowStudioResult? result,
  ) async {
    if (result == null) return;
    await _persistFlowStudioResult(result);
    if (!CalendarPage._shouldSkipExplicitHydrate(result)) {
      await _requestHydration(
        _CalendarHydrationRequest.catalogReconcile(
          reason: 'flow_studio_returned_result',
        ),
      );
    }
  }

  _Flow? _readingHouseFlowForEditor(int? flowId) {
    if (flowId == null) return null;
    final index = _flows.indexWhere((flow) => flow.id == flowId);
    if (index < 0) return null;
    final flow = _flows[index];
    if (resolveMaatFlowKind(flowNotes: flow.notes) ==
            MaatFlowKind.readingHouse ||
        isReadingHouseFlowReference(
          flowName: flow.name,
          flowNotes: flow.notes,
        )) {
      return flow;
    }
    return null;
  }

  Future<int?> _pushMaatFlowTemplateDetail(
