  // Scroll input has one frame owner. The coordinator coalesces notifications,
  // reads one immutable geometry snapshot, and publishes scoped semantic state.
  void _onVerticalScroll() {
    if (!_initialViewportSettled) return;
    if (_scrollCtrl.hasClients) {
      _lastKnownCalendarScrollOffset = _scrollCtrl.position.pixels;
    }
    _restorationInteractedSinceBoot = true;
    _scheduleCurrentDecanViewportRefresh();
    _calendarScrollCoordinator.noteScroll();
  }

  void _handleCoordinatorCenteredMonth() {
    if (!_restored || !_initialViewportSettled) return;
    final centered = _calendarScrollCoordinator.activeCenteredMonth.value;
    if (_lastViewKy == centered.year && _lastViewKm == centered.month) return;
    final maxDay = _maxDayForMonth(centered.year, centered.month);
    final clampedDay = (_lastViewKd ?? 1).clamp(1, maxDay);
    // A live scroll sample owns semantic position only. Durability and
    // hydration are settle consumers; scheduling them at every boundary was
    // timer churn in the frame path and created a second owner for scrolling.
    _lastViewKy = centered.year;
    _lastViewKm = centered.month;
    _lastViewKd = clampedDay;
  }

  MonthRef? _shadowAuthoritativeMonth() {
    final year = _lastViewKy;
    final month = _lastViewKm;
    if (year == null || month == null || month < 1 || month > 13) return null;
    return MonthRef(year: year, month: month);
  }

  MonthRef? _shadowLegacyCandidate(CalendarShadowSampleReason reason) {
    return switch (reason) {
      CalendarShadowSampleReason.scroll => _lastLegacyLiveShadowCandidate,
      CalendarShadowSampleReason.scrollEnd =>
        _lastLegacyScrollEndShadowCandidate,
      CalendarShadowSampleReason.geometryPublication => null,
    };
  }

  void _handleCalendarGeometryPublicationForShadow() {
    _calendarScrollCoordinator.noteGeometryPublication();
  }

  CalendarHydrationInterval? _measureRenderedMonthViewport() {
    if (!_scrollCtrl.hasClients) return null;
    final notificationContext =
        _scrollCtrl.position.context.notificationContext;
    final viewportObject = notificationContext?.findRenderObject();
    if (viewportObject is! RenderBox || !viewportObject.attached) return null;
    final viewportOrigin = viewportObject.localToGlobal(Offset.zero);
    final viewportTop = viewportOrigin.dy;
    final viewportBottom = viewportTop + viewportObject.size.height;
    final mountedMonths = <CalendarMonthViewportBounds>[];
    final idPattern = RegExp(r'^y(-?\d+)m(\d+)$');

    for (final entry in _calendarMonthKeys.entries) {
      final monthContext = entry.value.currentContext;
      if (monthContext == null) continue;
      final monthObject = monthContext.findRenderObject();
      if (monthObject is! RenderBox || !monthObject.attached) continue;
      final top = monthObject.localToGlobal(Offset.zero).dy;
      final bottom = top + monthObject.size.height;
      if (bottom <= viewportTop || top >= viewportBottom) continue;
      final match = idPattern.firstMatch(entry.key);
      if (match == null) continue;
      final ky = int.tryParse(match.group(1)!);
      final km = int.tryParse(match.group(2)!);
      if (ky == null || km == null || km < 1 || km > 13) continue;
      mountedMonths.add(
        CalendarMonthViewportBounds(
          kYear: ky,
          kMonth: km,
          top: top,
          bottom: bottom,
        ),
      );
    }
    final visibleMonths = visibleKemeticMonthRange(
      viewportTop: viewportTop,
      viewportBottom: viewportBottom,
      mountedMonths: mountedMonths,
    );
    if (visibleMonths == null) return null;
    return CalendarHydrationInterval.fromInclusiveLocalDays(
      firstLocalDay: KemeticMath.toGregorian(
        visibleMonths.firstKYear,
        visibleMonths.firstKMonth,
        1,
      ),
      lastLocalDay: KemeticMath.toGregorian(
        visibleMonths.lastKYear,
        visibleMonths.lastKMonth,
        _maxDayForMonth(visibleMonths.lastKYear, visibleMonths.lastKMonth),
      ),
    );
  }

  void _scheduleRenderedViewportHydration({required String reason}) {
    if (_calendarBoundaryBenchmarkEnabled) {
      widget.calendarBoundaryHarnessController?._noteHydrationSchedule();
    }
    _viewportHydrationDebounce?.cancel();
    _viewportHydrationDebounce = Timer(const Duration(milliseconds: 120), () {
      _viewportHydrationDebounce = null;
      if (!mounted || !_initialViewportSettled) return;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        final measured = _measureRenderedMonthViewport();
        if (measured == null ||
            measured == _hydrationController.state.viewport) {
          _scheduleMonthHydrationFrame();
          return;
        }
        unawaited(
          sharedCalendarSyncService(
            Supabase.instance.client,
          ).syncWindowIfActive(
            windowStart: measured.startUtc,
            windowEnd: measured.endUtc,
          ),
        );
        _hydrationController.reportViewport(measured);
        unawaited(
          _refreshVisibleViewport(
            reason: 'viewport_$reason',
            interval: measured,
          ),
        );
      });
    });
  }

  /// ✅ FIX 4: Handle month change from portrait scroll (with feedback loop guard)
  void _handlePortraitMonthChanged(int ky, int km) {
    if (_isUpdatingFromLandscape || _isUpdatingFromPortrait) return;

    _isUpdatingFromPortrait = true;
    try {
      _restorationInteractedSinceBoot = true;
      final maxDay = _maxDayForMonth(ky, km);
      final clampedKd = (_lastViewKd ?? 1).clamp(1, maxDay);

      _setView(ky, km, kd: clampedKd);
    } catch (e) {
      if (kDebugMode) {
        _calendarDebugPrint('⚠️ [CALENDAR] Error in portrait month change: $e');
      }
    } finally {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _isUpdatingFromPortrait = false;
      });
    }
  }

