  Future<void> _handleFirstMaatFlowAdded(
    _MaatFlowTemplate template,
    int flowId,
  ) async {
    CalendarPage._rememberJoinedMaatFlowTemplate(
      templateKey: template.key,
      flowId: flowId,
    );
    _myFlowsFilingSnapshotCache = null;
    await _flowsRepo.clearMyFiledFlowsCache();
    await _requestHydration(
      _CalendarHydrationRequest.catalogReconcile(
        reason: 'onboarding_first_maat_flow_added',
      ),
    );
    final firstEvent = _firstUpcomingNoteForFlow(flowId);
    final eventDate = firstEvent == null
        ? DateUtils.dateOnly(DateTime.now())
        : DateUtils.dateOnly(
            KemeticMath.toGregorian(
              firstEvent.ky,
              firstEvent.km,
              firstEvent.kd,
            ),
          );
    final kDate = firstEvent == null
        ? KemeticMath.fromGregorian(eventDate)
        : (kYear: firstEvent.ky, kMonth: firstEvent.km, kDay: firstEvent.kd);

    _firstMaatFlowId = flowId;
    _firstMaatFlowEventClientEventId = firstEvent?.note.clientEventId;
    _firstMaatFlowEventKDate = (
      ky: kDate.kYear,
      km: kDate.kMonth,
      kd: kDate.kDay,
    );

    await _updateOnboardingProgress(
      (progress) => progress.copyWith(
        hasChosenFirstMaatFlow: true,
        firstMaatFlowId: flowId.toString(),
        firstMaatFlowTemplateId: template.key,
        firstMaatFlowEventDate: eventDate,
        firstMaatFlowEventClientEventId: firstEvent?.note.clientEventId,
        currentStep: TrueOnboardingStep.firstFlowCalendarDay,
      ),
    );
    unawaited(
      Events.trackIfAuthed(
        'onboarding_first_maat_flow_added',
        <String, dynamic>{'flow_id': flowId, 'template_key': template.key},
      ),
    );
    if (!mounted) return;
    context.go('/');
    _alignCalendarToFirstFlowEvent();
    _showFirstFlowCalendarDayCoachmark();
  }

  ({int ky, int km, int kd, _Note note})? _firstUpcomingNoteForFlow(
    int flowId,
  ) {
    final today = DateUtils.dateOnly(DateTime.now());
    final candidates =
        <({int ky, int km, int kd, DateTime date, _Note note})>[];
    for (final entry in _notes.entries) {
      final parts = entry.key.split('-');
      if (parts.length != 3) continue;
      final ky = int.tryParse(parts[0]);
      final km = int.tryParse(parts[1]);
      final kd = int.tryParse(parts[2]);
      if (ky == null || km == null || kd == null) continue;
      final date = DateUtils.dateOnly(KemeticMath.toGregorian(ky, km, kd));
      for (final note in entry.value) {
        if (note.flowId == flowId) {
          candidates.add((ky: ky, km: km, kd: kd, date: date, note: note));
        }
      }
    }
    if (candidates.isEmpty) return null;
    candidates.sort((a, b) {
      final aFuture = !a.date.isBefore(today);
      final bFuture = !b.date.isBefore(today);
      if (aFuture != bFuture) return aFuture ? -1 : 1;
      final byDate = a.date.compareTo(b.date);
      if (byDate != 0) return byDate;
      final aStart = a.note.allDay
          ? 0
          : (a.note.start?.hour ?? 9) * 60 + (a.note.start?.minute ?? 0);
      final bStart = b.note.allDay
          ? 0
          : (b.note.start?.hour ?? 9) * 60 + (b.note.start?.minute ?? 0);
      return aStart.compareTo(bStart);
    });
    final first = candidates.first;
    return (ky: first.ky, km: first.km, kd: first.kd, note: first.note);
  }

  /// Chronological first note for a flow: earliest date, then earliest start.
  /// Same-day tiebreak is start time only (Course dawn wins via date then start).
  /// Null only when the flow has no notes. Do not use upcoming-biased helpers.
  ({int ky, int km, int kd, _Note note})? _firstChronologicalNoteForFlow(
    int flowId,
  ) {
    final candidates =
        <({int ky, int km, int kd, DateTime date, _Note note})>[];
    for (final entry in _notes.entries) {
      final parts = entry.key.split('-');
      if (parts.length != 3) continue;
      final ky = int.tryParse(parts[0]);
      final km = int.tryParse(parts[1]);
      final kd = int.tryParse(parts[2]);
      if (ky == null || km == null || kd == null) continue;
      final date = DateUtils.dateOnly(KemeticMath.toGregorian(ky, km, kd));
      for (final note in entry.value) {
        if (note.flowId == flowId) {
          candidates.add((ky: ky, km: km, kd: kd, date: date, note: note));
        }
      }
    }
    if (candidates.isEmpty) return null;
    candidates.sort((a, b) {
      final byDate = a.date.compareTo(b.date);
      if (byDate != 0) return byDate;
      final aStart = a.note.allDay
          ? 0
          : (a.note.start?.hour ?? 9) * 60 + (a.note.start?.minute ?? 0);
      final bStart = b.note.allDay
          ? 0
          : (b.note.start?.hour ?? 9) * 60 + (b.note.start?.minute ?? 0);
      return aStart.compareTo(bStart);
    });
    final first = candidates.first;
    return (ky: first.ky, km: first.km, kd: first.kd, note: first.note);
  }

  void _openDayViewForStagedFlow(int flowId) {
    final first = _firstChronologicalNoteForFlow(flowId);
    if (first == null) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not open the first day of this flow.'),
          ),
        );
      }
      return;
    }
    if (!mounted) return;
    _openDayView(
      context,
      first.ky,
      first.km,
      first.kd,
      focusEvent: _noteToEventItem(first.note),
      debugOpenSource: 'staged_flow_completion',
    );
  }

  void _applyPendingStagedFlow(int flowId) {
    final pending = CalendarPage._pendingStagedFlows[flowId];
    if (pending == null) return;
    if (!_flows.any((flow) => flow.id == flowId)) {
      _flows.add(pending.localFlow);
    }

    final upserts = <CalendarPendingVisibleItem<_Note>>[];
    for (final planned in pending.plannedNotes) {
      final note = planned.note;
      final clientEventId = note.clientEventId?.trim();
      final key = _kKey(planned.ky, planned.km, planned.kd);
      final bucket = _notes[key];
      if (clientEventId != null &&
          clientEventId.isNotEmpty &&
          bucket?.any(
                (candidate) => candidate.clientEventId?.trim() == clientEventId,
              ) ==
              true) {
        continue;
      }
      final shouldSkip =
          _isPendingDelete(
            kYear: planned.ky,
            kMonth: planned.km,
            kDay: planned.kd,
            title: note.title,
            allDay: note.allDay,
            start: note.start,
            end: note.end,
            clientEventId: note.clientEventId,
            flowId: note.flowId,
          ) ||
          _isTombstoned(note.clientEventId);
      if (shouldSkip) {
        continue;
      }
      _unconfirmed.register(dayKey: key, note: note);
      upserts.add(CalendarPendingVisibleItem<_Note>(dayKey: key, item: note));
    }
    if (upserts.isNotEmpty) {
      _publishCalendarNoteMutation(upserts: upserts);
    }
    if (upserts.isNotEmpty && mounted) {
      setState(() {});
      _notifyDayViewDataChanged();
    }
  }

  bool _schedulePendingStagedFlowDayViewIfAny() {
    if (CalendarPage._pendingStagedFlowDayViewFlowId == null) return false;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      unawaited(_consumePendingStagedFlowDayViewIfAny());
    });
    return true;
  }

  Future<void> _consumePendingStagedFlowDayViewIfAny() async {
    final flowId = CalendarPage._pendingStagedFlowDayViewFlowId;
    if (flowId == null || !mounted) return;
    _applyPendingStagedFlow(flowId);
    if (_firstChronologicalNoteForFlow(flowId) == null) {
      CalendarPage._clearStagedFlowDayViewIntent(flowId);
      CalendarPage._consumeStagedFlowCompletion(flowId);
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Could not stage the first day of this flow.'),
        ),
      );
      return;
    }
    CalendarPage._clearStagedFlowDayViewIntent(flowId);
    _openDayViewForStagedFlow(flowId);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) {
        CalendarPage._consumeStagedFlowCompletion(flowId);
        return;
      }
      // A detached cold start can restore the warm snapshot between the first
      // local apply and Day View's first frame. Re-apply the same cid-keyed
      // notes after that frame so the local block stays visible while the
      // background batch confirms it.
      try {
        _applyPendingStagedFlow(flowId);
      } finally {
        CalendarPage._consumeStagedFlowCompletion(flowId);
      }
    });
  }

