  ReminderRule? _findReminder(String id) {
    for (final r in _reminderRules) {
      if (r.id == id) return r;
    }
    return null;
  }

  Future<void> _editReminderById(String id) async {
    await _loadReminderRules();
    final rule = _findReminder(id);
    if (rule == null) return;
    await _openReminderEditor(existing: rule);
  }

  Future<void> _endReminderRule(String id) {
    final normalizedId = id.trim();
    if (normalizedId.isEmpty || _endedReminderIds.contains(normalizedId)) {
      return Future<void>.value();
    }
    final inFlight = _endingReminderOperations[normalizedId];
    if (inFlight != null) return inFlight;

    final operation = _endReminderRuleOnce(normalizedId);
    late final Future<void> tracked;
    tracked = operation.whenComplete(() {
      if (identical(_endingReminderOperations[normalizedId], tracked)) {
        _endingReminderOperations.remove(normalizedId);
      }
    });
    _endingReminderOperations[normalizedId] = tracked;
    return tracked;
  }

  Future<void> _endReminderRuleOnce(String id) async {
    // End = remove the reminder entirely (rule + scheduled instances + cached notes).
    await _loadReminderRules();
    if (_endedReminderIds.contains(id)) return;
    try {
      await _deleteReminderRule(id);
    } catch (error, stack) {
      if (kDebugMode) {
        _calendarDebugPrint(
          '[reminders] account-backed end failed: $error\n$stack',
        );
      }
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Could not end this reminder in your account. Nothing was deleted.',
            ),
          ),
        );
      }
    }
  }

  void _beginOrientationCriticalReminderSyncDeferral(String reason) {
    if (!mounted) return;
    _orientationCriticalReminderGeneration += 1;
    final generation = _orientationCriticalReminderGeneration;
    _reminderSyncGate.beginOrientationCriticalSection();

    WidgetsBinding.instance.addPostFrameCallback((_) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || generation != _orientationCriticalReminderGeneration) {
          return;
        }
        _endOrientationCriticalReminderSyncDeferral(generation, reason: reason);
      });
    });
  }

  void _endOrientationCriticalReminderSyncDeferral(
    int generation, {
    required String reason,
  }) {
    if (generation != _orientationCriticalReminderGeneration) return;
    _reminderSyncGate.endOrientationCriticalSection();
    if (kDebugMode) {
      _calendarDebugPrint(
        '[reminder_sync] orientation-critical section ended reason=$reason',
      );
    }
  }

  // ✅ Rotation reconcile: re-center on last view after rotation settles
  @override
  void didChangeMetrics() {
    _beginOrientationCriticalReminderSyncDeferral('metrics');
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;

      final orientation = MediaQuery.orientationOf(context);
      final ky = _lastViewKy ?? _today.kYear;
      final km = _lastViewKm ?? _today.kMonth;

      if (orientation == Orientation.portrait) {
        _centerMonth(ky, km); // your existing helper
      }
      _scheduleRenderedViewportHydration(reason: 'metrics');
      // Landscape rebuild pulls initialKy/Km from _lastView* in build()
    });
  }

  /* ───── helpers ───── */

  String _kKey(int ky, int km, int kd) => '$ky-$km-$kd';

  /// Get event marker colors for a given day (for month grid dots).
  /// Derives colors from filed notes in _notes, not from recomputed flow rules.
  List<Color> getFlowColorsForDay(int kYear, int kMonth, int kDay) {
    final notes = _getNotes(kYear, kMonth, kDay);
    return calendarEventMarkerColors<_Note>(
      notes,
      colorOf: _noteColor,
      groupBy: _calendarMarkerGroupKey,
    );
  }

  Object? _calendarMarkerGroupKey(_Note note) {
    final flowId = note.flowId;
    if (flowId == null || flowId <= 0) return null;
    return 'flow:$flowId';
  }

  List<_Note> _getNotes(int kYear, int kMonth, int kDay) {
    final key = _kKey(kYear, kMonth, kDay);
    final result = _notes[key] ?? const [];
    final visible = !_calendarStateLoaded
        ? result
        : result
              .where((note) => _isCalendarVisible(note.calendarId))
              .toList(growable: false);
    return _dedupeVisibleDayNotes(visible);
  }

  DaySheetDayWindow _calendarSheetDayWindow(int kYear, int kMonth, int kDay) {
    return daySheetWindowFor(KemeticMath.toGregorian(kYear, kMonth, kDay));
  }

  DateTime _calendarSheetLocalTimeOnDay(DateTime day, TimeOfDay time) {
    return DateTime(day.year, day.month, day.day, time.hour, time.minute);
  }

  ({DateTime start, DateTime end}) _calendarSheetLocalRangeForTimes({
    required DateTime dayStart,
    required bool allDay,
    required TimeOfDay? start,
    required TimeOfDay? end,
  }) {
    if (allDay) {
      return (start: dayStart, end: dayStart.add(const Duration(days: 1)));
    }

    final startTime = start ?? const TimeOfDay(hour: 9, minute: 0);
    final startsAt = _calendarSheetLocalTimeOnDay(dayStart, startTime);
    final endsAt = end == null
        ? startsAt.add(const Duration(minutes: 30))
        : daySheetEndAfterStart(
            startsAt,
            _calendarSheetLocalTimeOnDay(dayStart, end),
          );

    return (start: startsAt, end: endsAt);
  }

  ({DateTime start, DateTime end}) _calendarSheetLocalRangeForNote(
    _Note note,
    DateTime bucketStart,
  ) {
    return _calendarSheetLocalRangeForTimes(
      dayStart: bucketStart,
      allDay: note.allDay,
      start: note.start,
      end: note.end,
    );
  }

  DaySheetListCandidate _calendarSheetNoteCandidate(
    _Note note,
    DateTime bucketStart, {
    required String sourceType,
  }) {
    final range = _calendarSheetLocalRangeForNote(note, bucketStart);
    return DaySheetListCandidate(
      title: note.title,
      sourceType: sourceType,
      allDay: note.allDay,
      startsAtLocal: range.start,
      endsAtLocal: range.end,
      eventId: note.id,
      clientEventId: note.clientEventId,
      flowId: note.flowId,
      reminderId: note.reminderId,
    );
  }

  List<_DaySheetNoteOccurrence> _calendarSheetNoteCandidatesForDay(
    int kYear,
    int kMonth,
    int kDay,
  ) {
    final window = _calendarSheetDayWindow(kYear, kMonth, kDay);
    final previousDay = window.start.subtract(const Duration(days: 1));
    final previousK = KemeticMath.fromGregorian(previousDay);

    return <_DaySheetNoteOccurrence>[
      for (final note in _getNotes(kYear, kMonth, kDay))
        (note: note, bucketStart: window.start),
      for (final note in _getNotes(
        previousK.kYear,
        previousK.kMonth,
        previousK.kDay,
      ))
        (note: note, bucketStart: previousDay),
    ];
  }

  ReminderRule? _reminderRuleFromFlow(_Flow f) {
    if (f.notes == null || f.notes!.trim().isEmpty) return null;
    try {
      final decoded = jsonDecode(f.notes!.trim());
      final map = Map<String, dynamic>.from(decoded as Map);
      return reminderRuleFromFlowPayload(
        payload: map,
        fallbackCalendarId: f.calendarId,
        legacyFlowEnd: f.end,
      );
    } catch (_) {
      return null;
    }
  }

  TimeOfDay _calendarSheetTimeFromMinute(int minute) {
    final normalized = minute.remainder(24 * 60);
    final safeMinute = normalized < 0 ? normalized + 24 * 60 : normalized;
    return TimeOfDay(hour: safeMinute ~/ 60, minute: safeMinute % 60);
  }

  ({DateTime start, DateTime end}) _calendarSheetLocalRangeForEvent(
    int kYear,
    int kMonth,
    int kDay,
    EventItem event,
  ) {
    final dayStart = _calendarSheetDayWindow(kYear, kMonth, kDay).start;
    if (event.allDay) {
      return (start: dayStart, end: dayStart.add(const Duration(days: 1)));
    }

    final startsAt = dayStart.add(Duration(minutes: event.startMin));
    final rawEndsAt = dayStart.add(Duration(minutes: event.endMin));
    return (start: startsAt, end: daySheetEndAfterStart(startsAt, rawEndsAt));
  }

  bool _calendarSheetEventRepresentsScheduledFlow(
    EventItem event,
    Map<int, _Flow> flowsById,
  ) {
    if (event.isReminder) return false;
    final flowId = event.flowId;
    if (flowId == null || flowId <= 0) return false;
    final flow = flowsById[flowId];
    if (flow == null || flow.isReminder) return false;
    return !flow.isHidden && !hasRepeatingNoteFlowMetadata(flow.notes);
  }

  String _calendarSheetScheduledFlowKeyForEvent(EventItem event) {
    final flowId = event.flowId;
    if (flowId != null && flowId > 0) return 'flow:$flowId';

    final title = event.title.trim().toLowerCase();
    final sourceType = event.behaviorPayload?['source_type']?.toString() ?? '';
    return 'fallback:$sourceType:$title';
  }

  List<_DaySheetScheduledFlowRow> _calendarSheetScheduledFlowsForDay(
    int kYear,
    int kMonth,
    int kDay,
    List<EventItem> dayEvents,
  ) {
    final flowsById = _allFlowsById();
    final rows = <_DaySheetScheduledFlowRow>[];
    final rowIndexByParentKey = <String, int>{};

    for (final event in dayEvents) {
      if (!_calendarSheetEventRepresentsScheduledFlow(event, flowsById)) {
        continue;
      }
      final parentKey = _calendarSheetScheduledFlowKeyForEvent(event);
      final existingIndex = rowIndexByParentKey[parentKey];
      if (existingIndex != null) {
        final existing = rows[existingIndex];
        rows[existingIndex] = existing.copyWith(
          occurrenceCount: existing.occurrenceCount + 1,
        );
        continue;
      }

      final flowId = event.flowId!;
      final flow = flowsById[flowId]!;
      final range = _calendarSheetLocalRangeForEvent(
        kYear,
        kMonth,
        kDay,
        event,
      );
      final safeName = flow.name.trim().isEmpty
          ? event.title.trim()
          : flow.name.trim();
      rowIndexByParentKey[parentKey] = rows.length;
      rows.add(
        _DaySheetScheduledFlowRow(
          flowId: flowId,
          name: safeName.isEmpty ? 'Flow' : safeName,
          color: _displayFlowColor(flow.name, flow.color),
          allDay: event.allDay,
          start: event.allDay
              ? null
              : _calendarSheetTimeFromMinute(event.startMin),
          end: event.allDay ? null : _calendarSheetTimeFromMinute(event.endMin),
          startsAtLocal: range.start,
          endsAtLocal: range.end,
          sourceType: 'day_view_flow',
          eventId: event.id,
          clientEventId: event.clientEventId,
          reminderId: event.reminderId,
        ),
      );
    }

    rows.sort((a, b) {
      final startCompare = _daySheetTimeSortMinutes(
        allDay: a.allDay,
        time: a.start,
      ).compareTo(_daySheetTimeSortMinutes(allDay: b.allDay, time: b.start));
      if (startCompare != 0) return startCompare;
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });
    return rows;
  }

  String _calendarSheetScheduledFlowRowMeta(_DaySheetScheduledFlowRow row) {
    if (row.occurrenceCount > 1) return '${row.occurrenceCount} times today';
    return _timeRangeLabel(allDay: row.allDay, start: row.start, end: row.end);
  }

  int _daySheetTimeSortMinutes({
    required bool allDay,
    required TimeOfDay? time,
  }) {
    if (allDay || time == null) return -1;
    return time.hour * 60 + time.minute;
  }

  FlowRecordSnapshot _flowRecordSnapshotFromFlow(_Flow flow) {
    return FlowRecordSnapshot(
      id: flow.id,
      active: flow.active,
      isHidden: flow.isHidden,
      isReminder: flow.isReminder,
      isSaved: flow.isSaved,
      notes: flow.notes,
    );
  }

  FlowData _flowDataFromFlow(_Flow flow) {
    return FlowData(
      id: flow.id,
      name: flow.name,
      color: _displayFlowColor(flow.name, flow.color),
      active: flow.active,
      notes: flow.notes,
      isHidden: flow.isHidden,
      isReminder: flow.isReminder,
    );
  }

  Map<int, _Flow> _allFlowsById() {
    return {for (final flow in _flows) flow.id: flow};
  }

  Set<int> _calendarReferencedFlowIds() {
    final ids = <int>{};
    for (final bucket in _notes.values) {
      for (final note in bucket) {
        final flowId = note.flowId;
        if (flowId != null && flowId > 0) {
          ids.add(flowId);
        }
      }
    }
    return ids;
  }

  Map<int, FlowData> _buildActiveLedgerFlowIndex() {
    final flowIndex = <int, FlowData>{};
    final ledger = _buildFlowLedger(_flows);
    for (final f in ledger.activeItems) {
      flowIndex[f.id] = _flowDataFromFlow(f);
    }
    return flowIndex;
  }

  Set<int> _buildActiveLedgerFlowIds() {
    return _buildActiveLedgerFlowIndex().keys.toSet();
  }

  void _refreshNoteCacheUi() {
    if (!mounted) return;
    setState(() {});
    _notifyDayViewDataChanged();
  }

  void _replaceLiveNoteBuckets(Map<String, List<_Note>> source) {
    final visible = deriveVisibleCalendarBuckets<_Note>(
      source: source,
      suppressionRules: <CalendarItemSuppressionRule<_Note>>[
        _isExcludedReminderOccurrenceInBucket,
        _isPendingDeletedNoteInBucket,
        (_, note) => _isEndedReminderNote(note),
      ],
    );
    _notes.clear();
    for (final entry in visible.entries) {
      _notes[entry.key] = entry.value;
    }
  }

  String? _calendarNoteMutationStableIdentity(_Note note) {
    final clientEventId = note.clientEventId?.trim();
    if (clientEventId != null && clientEventId.isNotEmpty) {
      return 'cid:$clientEventId';
    }
    final eventId = note.id?.trim();
    if (eventId != null && eventId.isNotEmpty) return 'id:$eventId';
    return null;
  }

  bool _calendarNoteMatchesIdentityAliases(
    _Note note, {
    Iterable<String?> eventIds = const <String?>[],
    Iterable<String?> clientEventIds = const <String?>[],
  }) {
    bool matches(String? value, Iterable<String?> aliases) {
      final candidate = value?.trim();
      if (candidate == null || candidate.isEmpty) return false;
      return aliases.any((alias) => alias?.trim() == candidate);
    }

    return matches(note.id, eventIds) ||
        matches(note.clientEventId, clientEventIds);
  }

  /// The single publication path for local calendar-note mutations.
  ///
  /// Flow staging, replacement, optimistic removal, rollback, and shared
  /// calendar seeding all compose against the current projection here. This
  /// keeps identity replacement, day dedupe, and final visibility rules from
  /// drifting between otherwise equivalent behaviors.
  void _publishCalendarNoteMutation({
    Iterable<CalendarPendingVisibleItem<_Note>> upserts =
        const <CalendarPendingVisibleItem<_Note>>[],
    Iterable<CalendarItemSuppressionRule<_Note>> removals =
        const <CalendarItemSuppressionRule<_Note>>[],
    CalendarPendingSourceConflictRule<_Note>? sourceConflictRule,
  }) {
    final pendingItems = upserts.toList(growable: false);
    final removalRules = removals.toList(growable: false);
    if (pendingItems.isEmpty && removalRules.isEmpty) return;
    final trackSkyFlowIds = _flows
        .where((flow) => _isTrackSkyFlowName(flow.name))
        .map((flow) => flow.id)
        .where((flowId) => flowId > 0)
        .toSet();
    final projection = deriveVisibleCalendarProjection<_Note>(
      source: _notes,
      pendingItems: pendingItems,
      stableIdentityOf: _calendarNoteMutationStableIdentity,
      suppressionRules: removalRules,
      pendingIdentityConflictResolution:
          CalendarPendingIdentityConflictResolution.pendingReplacesSource,
      pendingSourceConflictRule: sourceConflictRule,
      reduceBucket: (_, notes) =>
          _dedupeVisibleDayNotes(notes, trackSkyFlowIds: trackSkyFlowIds),
    );
    _replaceLiveNoteBuckets(projection.buckets);
  }

  ({Map<String, List<_Note>> notesByDay, Set<String> clientEventIds})
  _removeCalendarNotesWhere(CalendarItemSuppressionRule<_Note> matches) {
    final removedByDay = <String, List<_Note>>{};
    final removedClientEventIds = <String>{};
    for (final entry in _notes.entries) {
      final removed = entry.value
          .where((note) => matches(entry.key, note))
          .toList(growable: false);
      if (removed.isEmpty) continue;
      removedByDay[entry.key] = removed;
      removedClientEventIds.addAll(
        removed
            .map((note) => note.clientEventId?.trim())
            .whereType<String>()
            .where((cid) => cid.isNotEmpty),
      );
    }
    if (removedByDay.isNotEmpty) {
      _publishCalendarNoteMutation(
        removals: <CalendarItemSuppressionRule<_Note>>[matches],
      );
    }
    return (notesByDay: removedByDay, clientEventIds: removedClientEventIds);
  }

  String? _calendarNoteStableIdentity(_Note note) {
    final clientEventId = note.clientEventId?.trim();
    return clientEventId == null || clientEventId.isEmpty
        ? null
        : clientEventId;
  }

  bool _isExcludedReminderOccurrenceInBucket(String dayKey, _Note note) {
    if (_occurrenceExclusions.isEmpty) return false;
    final identity = _reminderOccurrenceIdentityForLocalDate(
      note,
      _warmStartDateFromKey(dayKey),
    );
    return identity != null && _isOccurrenceExcluded(identity);
  }

  bool _isPendingDeletedNoteInBucket(String dayKey, _Note note) {
    if (_pendingDeletes.isEmpty) return false;
    final parts = dayKey.split('-');
    final kYear = parts.length == 3 ? int.tryParse(parts[0]) : null;
    final kMonth = parts.length == 3 ? int.tryParse(parts[1]) : null;
    final kDay = parts.length == 3 ? int.tryParse(parts[2]) : null;
    return _isPendingDelete(
      id: note.id,
      clientEventId: note.clientEventId,
      kYear: kYear,
      kMonth: kMonth,
      kDay: kDay,
      title: note.title,
      allDay: note.allDay,
      start: note.start,
      end: note.end,
      flowId: note.flowId,
    );
  }

  bool _isEndedReminderNote(_Note note) {
    if (_endedReminderIds.isEmpty) return false;
    if (note.detail?.contains(_kReminderManualOverrideMarker) == true) {
      return false;
    }
    final reminderId = note.reminderId?.trim();
    if (reminderId != null &&
        reminderId.isNotEmpty &&
        _endedReminderIds.contains(reminderId)) {
      return true;
    }
    final clientEventId = note.clientEventId?.trim();
    if (clientEventId == null || clientEventId.isEmpty) return false;
    final cidReminderId = _reminderRuleIdFromCid(clientEventId);
    return cidReminderId != null && _endedReminderIds.contains(cidReminderId);
  }

  bool _addNote(
    int kYear,
    int kMonth,
    int kDay,
    String title,
    String? detail, {
    String? id,
    String? clientEventId,
    String? calendarId,
    String? calendarName,
    String? location,
    bool allDay = false,
    TimeOfDay? start,
    TimeOfDay? end,
    int? flowId,
    Color? manualColor,
    String? category,
    bool isReminder = false,
    String? reminderId,
    int? alertOffsetMinutes,
    String? actionId,
    Map<String, dynamic>? behaviorPayload,
    bool notify = true,
    NoteConfirmation confirmation = NoteConfirmation.confirmed,
    DateTime? unconfirmedCreatedAt,
  }) {
    final shouldSkip =
        _isPendingDelete(
          kYear: kYear,
          kMonth: kMonth,
          kDay: kDay,
          title: title,
          allDay: allDay,
          start: start,
          end: end,
          clientEventId: clientEventId,
          flowId: flowId,
        ) ||
        _isTombstoned(clientEventId);
    if (shouldSkip) {
      if (kDebugMode) {
        _calendarDebugPrint(
          '[_addNote] skip add for title=<redacted chars=${title.length}> '
          'cid=${safeLogIdentifier(clientEventId)} pending/tombstoned',
        );
      }
      return false;
    }

    final k = _kKey(kYear, kMonth, kDay);
    final note = _Note(
      id: id,
      clientEventId: clientEventId,
      calendarId: calendarId,
      calendarName: calendarName,
      title: title.trim(),
      detail: detail?.trim(),
      location: (location == null || location.trim().isEmpty)
          ? null
          : location.trim(),
      allDay: allDay,
      start: allDay ? null : start,
      end: allDay ? null : end,
      flowId: flowId,
      manualColor: manualColor,
      category: category,
      isReminder: isReminder,
      reminderId: reminderId,
      alertOffsetMinutes: alertOffsetMinutes,
      actionId: actionId,
      behaviorPayload: behaviorPayload == null
          ? null
          : Map<String, dynamic>.from(behaviorPayload),
    );
    _publishCalendarNoteMutation(
      upserts: <CalendarPendingVisibleItem<_Note>>[
        CalendarPendingVisibleItem<_Note>(dayKey: k, item: note),
      ],
    );
    if (confirmation == NoteConfirmation.unconfirmed) {
      _unconfirmed.register(
        dayKey: k,
        note: note,
        createdAt: unconfirmedCreatedAt,
      );
    }
    // Do not schedule notifications here; scheduling is handled by the caller.
    if (notify) {
      _refreshNoteCacheUi();
    }
    return true;
  }

  Future<void> _rollbackStagedFlowLocally(
    int serverFlowId, {
    required UserEventsRepo repo,
    required String failureMessage,
  }) async {
    _flows.removeWhere((flow) => flow.id == serverFlowId);

    final removed = _removeCalendarNotesWhere(
      (_, note) => note.flowId == serverFlowId,
    );
    _unconfirmed.forgetCids(removed.clientEventIds);

    if (mounted) {
      setState(() {});
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(failureMessage)));
    }

    try {
      await repo.deleteByFlowId(
        serverFlowId,
        semantic: 'flow_save_rollback',
        suppressesClient: false,
        sourceFeature: 'CalendarPage._rollbackStagedFlowLocally',
        deleteScope: 'failed_staged_flow_save',
      );
    } catch (_) {}
    try {
      await repo.deleteFlow(serverFlowId);
    } catch (_) {}
  }

  int _removeLocalNotesForFlowReplacement(int flowId) {
    if (flowId <= 0) return 0;
    final removed = _removeCalendarNotesWhere(
      (_, note) => note.flowId == flowId,
    );
    _unconfirmed.forgetCids(removed.clientEventIds);
    return removed.notesByDay.values.fold<int>(
      0,
      (count, notes) => count + notes.length,
    );
  }

  _Note? _removeLocalNoteOnly(int kYear, int kMonth, int kDay, int index) {
    final k = _kKey(kYear, kMonth, kDay);
    final existing = _notes[k];
    if (existing == null || index < 0 || index >= existing.length) return null;

    final removed = existing[index];
    _removeCalendarNotesWhere(
      (dayKey, note) => dayKey == k && identical(note, removed),
    );
    final removedCid = removed.clientEventId?.trim();
    _unconfirmed.forgetCid(removedCid);
    if (removedCid != null && removedCid.isNotEmpty) {
      unawaited(_removePersistedPendingCids(<String>[removedCid]));
    }
    setState(() {});
    _notifyDayViewDataChanged();
    return removed;
  }

  String _standaloneDedupeKey(_Note note) {
    final normalizedTitle = note.title.trim().toLowerCase();
    final startMin = note.start == null
        ? -1
        : (note.start!.hour * 60 + note.start!.minute);
    final endMin = note.end == null
        ? -1
        : (note.end!.hour * 60 + note.end!.minute);
    return '${note.calendarId ?? ''}|$normalizedTitle|${note.allDay}|$startMin|$endMin';
  }

  int _standalonePriority(String? cid) {
    if (cid == null || cid.isEmpty) return 2;
    if (cid.contains('|f=-1') || cid.startsWith('ky=')) return 4; // manual
    if (cid.startsWith('native:')) return 3;
    if (cid.startsWith('holiday:')) return 1;
    return 2;
  }

  String? _editableStandaloneCategory({
    required bool detachImportedDeviceEvent,
    String? category,
  }) {
    final trimmed = category?.trim();
    if (trimmed == null || trimmed.isEmpty) return null;
    if (detachImportedDeviceEvent && trimmed.toLowerCase() == 'native_sync') {
      return null;
    }
    return trimmed;
  }

  bool _isManualCid(String? cid, {int? flowId}) {
    final trimmed = cid?.trim() ?? '';
    if (trimmed.startsWith('reminder:') ||
        trimmed.startsWith('nutrition:') ||
        trimmed.startsWith('native:') ||
        trimmed.startsWith('holiday:')) {
      return false;
    }
    if (trimmed.isEmpty) {
      return flowId == null || flowId == -1;
    }
    if (trimmed.startsWith('ky=')) return true;
    if (trimmed.contains('|f=-1')) return true;
    return flowId == null || flowId == -1;
  }

  String? _manualCidForNote(_Note note, int kYear, int kMonth, int kDay) {
    final cid = note.clientEventId?.trim();
    if (_isManualCid(cid, flowId: note.flowId)) {
      return cid;
    }
    final fid = note.flowId ?? -1;
    if (fid == -1) {
      return _buildCid(
        ky: kYear,
        km: kMonth,
        kd: kDay,
        title: note.title,
        startHour: note.start?.hour,
        startMinute: note.start?.minute,
        allDay: note.allDay,
        flowId: -1,
        calendarScopeToken: _calendarScopeToken(note.calendarId),
      );
    }
    return null;
  }

  String? _inviteImportTombstoneCid(String? cid) {
    final trimmed = cid?.trim();
    if (trimmed == null || trimmed.isEmpty) return null;
    if (trimmed.startsWith('event_share:')) {
      return trimmed;
    }
    return null;
  }

  Future<void> _ensureManualDeleteTombstonesLoaded() async {
    if (_manualTombstonesLoaded) return;
    _manualTombstonesLoad ??= () async {
      try {
        final prefs = await SharedPreferences.getInstance();
        final stored = await CalendarUserScopedPrefs.readStringList(
          prefs: prefs,
          userId: _activeWarmStartUserId(),
          userKey: CalendarUserScopedPrefs.manualDeleteTombstonesKey,
          legacyKey: CalendarUserScopedPrefs.legacyManualDeleteTombstonesKey,
        );
        _manualDeleteTombstones
          ..clear()
          ..addAll(stored);
      } catch (_) {
        // ignore load errors; tombstones are a best-effort safeguard
      } finally {
        _manualTombstonesLoaded = true;
      }
    }();
    await _manualTombstonesLoad;
  }

  Future<void> _persistManualDeleteTombstones() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await CalendarUserScopedPrefs.writeStringList(
        prefs: prefs,
        userId: _activeWarmStartUserId(),
        userKey: CalendarUserScopedPrefs.manualDeleteTombstonesKey,
        legacyKey: CalendarUserScopedPrefs.legacyManualDeleteTombstonesKey,
        values: _manualDeleteTombstones.toList(),
      );
    } catch (_) {
      // ignore persistence errors; safeguard is best-effort
    }
  }

  Future<void> _recordManualTombstone(String cid) async {
    final trimmed = cid.trim();
    if (trimmed.isEmpty) return;
    await _ensureManualDeleteTombstonesLoaded();
    final added = _manualDeleteTombstones.add(trimmed);
    _unconfirmed.forgetCid(trimmed);
    await _removePersistedPendingCids(<String>[trimmed]);
    if (added) {
      await _persistManualDeleteTombstones();
      final userId = _activeWarmStartUserId();
      if (userId != null) {
        await _commitCalendarOverlayState(
          userId: userId,
          reason: 'delete_tombstone_added',
        );
      }
    }
  }

  Future<void> _clearManualTombstone(String cid) async {
    final trimmed = cid.trim();
    if (trimmed.isEmpty) return;
    await _ensureManualDeleteTombstonesLoaded();
    final removed = _manualDeleteTombstones.remove(trimmed);
    if (removed) {
      await _persistManualDeleteTombstones();
      final userId = _activeWarmStartUserId();
      if (userId != null) {
        await _commitCalendarOverlayState(
          userId: userId,
          reason: 'delete_tombstone_cleared',
          removeTombstoneIdentities: <String>{trimmed},
        );
      }
    }
  }

  bool _isTombstoned(String? cid) {
    final trimmed = cid?.trim();
    if (trimmed == null || trimmed.isEmpty) return false;
    return _manualDeleteTombstones.contains(trimmed);
  }

  Future<void> _persistOccurrenceExclusions() async {
    final values =
        _occurrenceExclusions
            .map((identity) => identity.canonicalKey)
            .toList(growable: false)
          ..sort();
    final prefs = await SharedPreferences.getInstance();
    await CalendarUserScopedPrefs.writeStringList(
      prefs: prefs,
      userId: _activeWarmStartUserId(),
      userKey: CalendarUserScopedPrefs.occurrenceExclusionsKey,
      legacyKey: CalendarUserScopedPrefs.legacyOccurrenceExclusionsKey,
      values: values,
    );
  }

  Future<void> _loadOccurrenceExclusions({bool refreshServer = false}) async {
    final userId = _activeWarmStartUserId();
    if (userId == null || userId.trim().isEmpty) return;
    final normalizedUserId = userId.trim();

    final activeLoad = _occurrenceExclusionsLoad;
    if (activeLoad != null) {
      await activeLoad;
      if (identical(_occurrenceExclusionsLoad, activeLoad)) {
        _occurrenceExclusionsLoad = null;
      }
      if (refreshServer) {
        await _loadOccurrenceExclusions(refreshServer: true);
      }
      return;
    }

    final serverCacheFresh =
        _occurrenceExclusionsLoadedForUserId == normalizedUserId &&
        _occurrenceExclusionsServerLoadedAt != null &&
        DateTime.now().difference(_occurrenceExclusionsServerLoadedAt!) <
            const Duration(seconds: 30);
    final needsLocalLoad =
        _occurrenceExclusionsLoadedForUserId != normalizedUserId;
    final needsServerLoad = refreshServer && !serverCacheFresh;
    if (!needsLocalLoad && !needsServerLoad) return;

    late final Future<void> load;
    load = () async {
      if (needsLocalLoad) {
        final prefs = await SharedPreferences.getInstance();
        final stored = await CalendarUserScopedPrefs.readStringList(
          prefs: prefs,
          userId: normalizedUserId,
          userKey: CalendarUserScopedPrefs.occurrenceExclusionsKey,
          legacyKey: CalendarUserScopedPrefs.legacyOccurrenceExclusionsKey,
        );
        if (_activeWarmStartUserId() != normalizedUserId) return;
        _occurrenceExclusions
          ..clear()
          ..addAll(
            stored
                .map(CalendarOccurrenceIdentity.tryParse)
                .whereType<CalendarOccurrenceIdentity>(),
          );
        _occurrenceExclusionsLoadedForUserId = normalizedUserId;
      }

      if (!needsServerLoad || _activeWarmStartUserId() != normalizedUserId) {
        return;
      }
      try {
        final locallyKnown = Set<CalendarOccurrenceIdentity>.from(
          _occurrenceExclusions,
        );
        final remote = await _occurrenceExclusionsRepo.listMine();
        if (_activeWarmStartUserId() != normalizedUserId) return;
        _occurrenceExclusions.addAll(remote);
        _occurrenceExclusionsServerLoadedAt = DateTime.now();
        await _persistOccurrenceExclusions();
        for (final identity in locallyKnown.difference(remote)) {
          unawaited(_syncOccurrenceExclusionToServer(identity));
        }
      } catch (error) {
        // A cached exclusion is safer than resurrecting a deleted occurrence.
        // Back off briefly so a network outage does not add one failed read to
        // every progressive hydration chunk.
        if (_activeWarmStartUserId() == normalizedUserId) {
          _occurrenceExclusionsServerLoadedAt = DateTime.now();
        }
        if (kDebugMode) {
          _calendarDebugPrint(
            '[occurrence-exclusions] refresh failed: ${error.runtimeType}',
          );
        }
      }
    }();
    _occurrenceExclusionsLoad = load;
    try {
      await load;
    } finally {
      if (identical(_occurrenceExclusionsLoad, load)) {
        _occurrenceExclusionsLoad = null;
      }
    }
  }

  Future<void> _recordOccurrenceExclusion(
    CalendarOccurrenceIdentity identity,
  ) async {
    await _loadOccurrenceExclusions();
    final added = _occurrenceExclusions.add(identity);
    if (added) await _persistOccurrenceExclusions();
  }

  Future<void> _syncOccurrenceExclusionToServer(
    CalendarOccurrenceIdentity identity,
  ) async {
    try {
      await _occurrenceExclusionsRepo.exclude(identity);
      _occurrenceExclusionsServerLoadedAt = DateTime.now();
    } catch (error) {
      // The local exclusion remains authoritative and will be retried by the
      // next server refresh. Rolling it back would resurrect the occurrence.
      if (kDebugMode) {
        _calendarDebugPrint(
          '[occurrence-exclusions] sync deferred: ${error.runtimeType}',
        );
      }
    }
  }

  bool _isOccurrenceExcluded(CalendarOccurrenceIdentity identity) =>
      _occurrenceExclusions.contains(identity);

  bool _isReminderOccurrenceClientIdExcluded(String? clientEventId) {
    final identity = CalendarOccurrenceIdentity.tryParse(clientEventId);
    return identity != null && _isOccurrenceExcluded(identity);
  }

  int _removeExcludedReminderOccurrences(Map<String, List<_Note>> notesByDay) {
    final before = notesByDay.values.fold<int>(
      0,
      (count, notes) => count + notes.length,
    );
    final visible = deriveVisibleCalendarBuckets<_Note>(
      source: notesByDay,
      suppressionRules: <CalendarItemSuppressionRule<_Note>>[
        _isExcludedReminderOccurrenceInBucket,
      ],
    );
    notesByDay.clear();
    for (final entry in visible.entries) {
      notesByDay[entry.key] = entry.value;
    }
    return before -
        visible.values.fold<int>(0, (count, notes) => count + notes.length);
  }

  bool _isRepeatingNoteFlow(_Flow? flow) {
    if (flow == null) return false;
    return flow.id > 0 &&
        !flow.isReminder &&
        (flow.isHidden || hasRepeatingNoteFlowMetadata(flow.notes));
  }

  _Flow? _repeatingNoteFlowForId(int? flowId) {
    if (flowId == null || flowId <= 0) return null;
    for (final flow in _flows) {
      if (flow.id == flowId && _isRepeatingNoteFlow(flow)) return flow;
    }
    return null;
  }

  Set<DateTime> _repeatingFlowRuleDates(_Flow flow) {
    final dates = <DateTime>{};
    for (final rule in flow.rules) {
      if (rule is _RuleDates) {
        dates.addAll(rule.dates.map(calendarRecurringDateOnly));
      }
    }
    return dates;
  }

  ({bool allDay, TimeOfDay? start, TimeOfDay? end}) _repeatingFlowTimeFields(
    _Flow flow,
  ) {
    for (final rule in flow.rules) {
      if (rule is _RuleDates) {
        return (allDay: rule.allDay, start: rule.start, end: rule.end);
      }
    }
    return (allDay: true, start: null, end: null);
  }

  DateTime _gregorianDateForKemeticDay(int ky, int km, int kd) {
    return calendarRecurringDateOnly(KemeticMath.toGregorian(ky, km, kd));
  }

  DateTime? _gregorianDateForNoteBucketKey(String key) {
    final parts = key.split('-');
    if (parts.length != 3) return null;
    final ky = int.tryParse(parts[0]);
    final km = int.tryParse(parts[1]);
    final kd = int.tryParse(parts[2]);
    if (ky == null || km == null || kd == null) return null;
    return _gregorianDateForKemeticDay(ky, km, kd);
  }

  DateTime _occurrenceStartLocal({
    required int ky,
    required int km,
    required int kd,
    required bool allDay,
    required TimeOfDay? start,
  }) {
    final day = KemeticMath.toGregorian(ky, km, kd);
    final hour = allDay || start == null ? 9 : start.hour;
    final minute = allDay || start == null ? 0 : start.minute;
    return DateTime(day.year, day.month, day.day, hour, minute);
  }

  int _removeLocalRepeatingNotesForDates({
    required int flowId,
    required Set<DateTime> dates,
  }) {
    if (flowId <= 0 || dates.isEmpty) return 0;
    final normalizedDates = dates.map(calendarRecurringDateOnly).toSet();
    final removed = _removeCalendarNotesWhere((key, note) {
      final bucketDate = _gregorianDateForNoteBucketKey(key);
      if (bucketDate == null || !normalizedDates.contains(bucketDate)) {
        return false;
      }
      return (note.flowId ?? -1) == flowId;
    });
    _unconfirmed.forgetCids(removed.clientEventIds);
    final removedCount = removed.notesByDay.values.fold<int>(
      0,
      (count, notes) => count + notes.length,
    );
    if (removedCount > 0) {
      setState(() {});
      _notifyDayViewDataChanged();
    }
    return removedCount;
  }

  Future<CalendarRecurringMutationScope?> _showRepeatingEventScopeSheet({
    required BuildContext context,
    required bool isDelete,
  }) {
    return showCupertinoModalPopup<CalendarRecurringMutationScope>(
      context: context,
      builder: (popupContext) => CupertinoActionSheet(
        actions: [
          for (final scope in CalendarRecurringMutationScope.values)
            CupertinoActionSheetAction(
              isDestructiveAction:
                  isDelete &&
                  scope == CalendarRecurringMutationScope.entireSeries,
              onPressed: () => Navigator.pop(popupContext, scope),
              child: Text(scope.label),
            ),
        ],
        cancelButton: CupertinoActionSheetAction(
          onPressed: () => Navigator.pop(popupContext),
          child: const Text('Cancel'),
        ),
      ),
    );
  }

  Future<_Flow?> _persistRepeatingNoteFlow({
    required _Flow flow,
    required Set<DateTime> dates,
    required String title,
    required String? detail,
    required String? location,
    required String? calendarId,
    required bool allDay,
    required TimeOfDay? startTime,
    required TimeOfDay? endTime,
    required Color color,
    required String? category,
    required int alertMinutesBefore,
    DateTime? rescheduleFromDate,
    String caller = 'repeat_scope_update',
  }) async {
    final normalizedDates = dates.map(calendarRecurringDateOnly).toSet();
    if (normalizedDates.isEmpty) {
      await _deleteRepeatingNoteFlowSeries(flow);
      return null;
    }

    final orderedDates = normalizedDates.toList()..sort();
    final nextRule = _RuleDates(
      dates: normalizedDates,
      allDay: allDay,
      start: allDay ? null : startTime,
      end: allDay ? null : endTime,
    );
    final nextFlow = _Flow(
      id: flow.id,
      calendarId: calendarId,
      name: title,
      color: color,
      active: true,
      isSaved: flow.isSaved,
      savedAt: flow.savedAt,
      rules: [nextRule],
      start: orderedDates.first,
      end: orderedDates.last,
      notes: _encodeRepeatingNoteMetadata(
        detail: detail,
        location: location,
        category: category,
        alertMinutes: alertMinutesBefore,
        keepMarker: true,
      ),
      shareId: flow.shareId,
      isHidden: true,
      isReminder: false,
      reminderUuid: flow.reminderUuid,
    );

    final repo = UserEventsRepo(Supabase.instance.client);
    await repo.upsertFlow(
      id: nextFlow.id,
      name: nextFlow.name,
      color: nextFlow.color.toARGB32(),
      active: nextFlow.active,
      calendarId: nextFlow.calendarId,
      startDate: nextFlow.start,
      endDate: nextFlow.end,
      notes: nextFlow.notes,
      rules: jsonEncode(nextFlow.rules.map(ruleToJson).toList()),
      isHidden: true,
      isSaved: nextFlow.isSaved,
      shareId: nextFlow.shareId,
      isReminder: false,
      reminderUuid: nextFlow.reminderUuid,
    );

    final idx = _flows.indexWhere((f) => f.id == flow.id);
    if (idx >= 0) {
      _flows[idx] = nextFlow;
    } else {
      _flows.add(nextFlow);
    }

    if (rescheduleFromDate != null) {
      await scheduleFlowNotes(
        flowId: nextFlow.id,
        rules: nextFlow.rules,
        flowNotes: nextFlow.notes,
        startDate: calendarRecurringDateOnly(rescheduleFromDate),
        endDate: nextFlow.end,
      );
    }

    if (kDebugMode) {
      _calendarDebugPrint(
        '[RepeatScope] $caller flowId=${nextFlow.id} dates=${normalizedDates.length}',
      );
    }
    return nextFlow;
  }

  Future<_Flow> _createRepeatingNoteFlowFromDates({
    required Set<DateTime> dates,
    required String title,
    required String? detail,
    required String? location,
    required String? calendarId,
    required bool allDay,
    required TimeOfDay? startTime,
    required TimeOfDay? endTime,
    required Color color,
    required String? category,
    required int alertMinutesBefore,
  }) async {
    final normalizedDates = dates.map(calendarRecurringDateOnly).toSet();
    final orderedDates = normalizedDates.toList()..sort();
    if (orderedDates.isEmpty) {
      throw ArgumentError('Repeating flow requires at least one date.');
    }

    final rule = _RuleDates(
      dates: normalizedDates,
      allDay: allDay,
      start: allDay ? null : startTime,
      end: allDay ? null : endTime,
    );
    final notes = _encodeRepeatingNoteMetadata(
      detail: detail,
      location: location,
      category: category,
      alertMinutes: alertMinutesBefore,
      keepMarker: true,
    );
    final repo = UserEventsRepo(Supabase.instance.client);
    final flowId = await repo.upsertFlow(
      id: null,
      name: title,
      color: color.toARGB32(),
      active: true,
      calendarId: calendarId,
      startDate: orderedDates.first,
      endDate: orderedDates.last,
      notes: notes,
      rules: jsonEncode([ruleToJson(rule)]),
      isHidden: true,
      isReminder: false,
    );

    final flow = _Flow(
      id: flowId,
      calendarId: calendarId,
      name: title,
      color: color,
      active: true,
      rules: [rule],
      start: orderedDates.first,
      end: orderedDates.last,
      notes: notes,
      isHidden: true,
    );
    _flows.add(flow);
    if (flowId >= _nextFlowId) _nextFlowId = flowId + 1;

    await scheduleFlowNotes(
      flowId: flow.id,
      rules: flow.rules,
      flowNotes: flow.notes,
      startDate: orderedDates.first,
      endDate: orderedDates.last,
    );
    return flow;
  }

  Future<void> _deleteRepeatingNoteFlowSeries(_Flow flow) async {
    final flowId = flow.id;
    if (flowId <= 0) return;
    _removeLocalNotesForFlowReplacement(flowId);
    _flows.removeWhere((f) => f.id == flowId);
    if (mounted) setState(() {});
    _notifyDayViewDataChanged();

    final repo = UserEventsRepo(Supabase.instance.client);
    await repo.deleteFlow(flowId);
  }

  Future<void> _deleteRepeatingOccurrenceRow({
    required _Note note,
    required String deleteScope,
  }) async {
    final repo = UserEventsRepo(Supabase.instance.client);
    final cid = note.clientEventId?.trim();
    if (cid != null && cid.isNotEmpty) {
      await repo.deleteByClientId(
        cid,
        semantic: 'repeat_scope_delete',
        sourceFeature: 'CalendarPage._deleteRepeatingOccurrenceRow',
        deleteScope: deleteScope,
      );
      await Notify.cancelNotificationForEvent(cid);
      return;
    }
    final id = note.id?.trim();
    if (id != null && id.isNotEmpty) {
      await repo.delete(id);
    }
  }

  Future<void> _notifySharedRepeatingScope({
    required String? calendarId,
    required String title,
    required CalendarRecurringMutationScope scope,
    required bool isDelete,
    String? clientEventId,
    String? eventId,
    int? flowId,
  }) {
    return _notifySharedCalendarMembers(
      calendarId: calendarId,
      title: _calendarDisplayName(calendarId),
      body: '${isDelete ? 'Deleted' : 'Updated'} event: $title',
      clientEventId: clientEventId,
      data: <String, dynamic>{
        'recurrence_scope': scope.name,
        if (eventId != null && eventId.trim().isNotEmpty) 'event_id': eventId,
        if (flowId != null && flowId > 0) 'flow_id': flowId,
      },
    );
  }

  Future<bool> _applyRepeatingNoteDeleteScope({
    required _Note note,
    required int kYear,
    required int kMonth,
    required int kDay,
    required CalendarRecurringMutationScope scope,
  }) async {
    final flow = _repeatingNoteFlowForId(note.flowId);
    if (flow == null) return false;

    final dates = _repeatingFlowRuleDates(flow);
    final selectedDate = _gregorianDateForKemeticDay(kYear, kMonth, kDay);
    final plan = planCalendarRecurringDateScope(
      originalDates: dates,
      selectedDate: selectedDate,
      scope: scope,
    );
    if (plan.affectedOriginalDates.isEmpty) return false;

    final meta = _decodeRepeatingNoteMetadata(flow.notes);
    final time = _repeatingFlowTimeFields(flow);
    final selectedStart = _occurrenceStartLocal(
      ky: kYear,
      km: kMonth,
      kd: kDay,
      allDay: note.allDay,
      start: note.start,
    );
    final repo = UserEventsRepo(Supabase.instance.client);

    switch (scope) {
      case CalendarRecurringMutationScope.thisEventOnly:
        await _persistRepeatingNoteFlow(
          flow: flow,
          dates: plan.keptOriginalDates,
          title: flow.name,
          detail: meta.detail,
          location: meta.location,
          calendarId: flow.calendarId,
          allDay: time.allDay,
          startTime: time.start,
          endTime: time.end,
          color: flow.color,
          category: meta.category,
          alertMinutesBefore: meta.alertMinutes ?? _alertNoneMinutes,
          caller: 'repeat_scope_delete_this',
        );
        _removeLocalRepeatingNotesForDates(
          flowId: flow.id,
          dates: plan.affectedOriginalDates,
        );
        await _deleteRepeatingOccurrenceRow(
          note: note,
          deleteScope: 'repeat_this_event',
        );
        break;

      case CalendarRecurringMutationScope.thisAndFuture:
        if (plan.keptOriginalDates.isEmpty) {
          await _deleteRepeatingNoteFlowSeries(flow);
        } else {
          await _persistRepeatingNoteFlow(
            flow: flow,
            dates: plan.keptOriginalDates,
            title: flow.name,
            detail: meta.detail,
            location: meta.location,
            calendarId: flow.calendarId,
            allDay: time.allDay,
            startTime: time.start,
            endTime: time.end,
            color: flow.color,
            category: meta.category,
            alertMinutesBefore: meta.alertMinutes ?? _alertNoneMinutes,
            caller: 'repeat_scope_delete_future_keep_past',
          );
          _removeLocalRepeatingNotesForDates(
            flowId: flow.id,
            dates: plan.affectedOriginalDates,
          );
          await repo.deleteByFlowId(
            flow.id,
            fromDate: selectedStart.toUtc(),
            semantic: 'repeat_scope_delete',
            sourceFeature: 'CalendarPage._applyRepeatingNoteDeleteScope',
            deleteScope: 'repeat_this_and_future',
          );
        }
        break;

      case CalendarRecurringMutationScope.entireSeries:
        await _deleteRepeatingNoteFlowSeries(flow);
        break;
    }

    await _notifySharedRepeatingScope(
      calendarId: note.calendarId ?? flow.calendarId,
      title: note.title,
      scope: scope,
      isDelete: true,
      clientEventId: note.clientEventId,
      eventId: note.id,
      flowId: flow.id,
    );
    await _requestHydration(
      _CalendarHydrationRequest.catalogReconcile(
        reason: 'repeat_scope_delete_${scope.name}',
      ),
    );
    return true;
  }

  Future<({String? clientEventId, String? eventId})>
  _applyRepeatingNoteEditScope({
    required _Note originalNote,
    required int sourceKYear,
    required int sourceKMonth,
    required int sourceKDay,
    required int selYear,
    required int selMonth,
    required int selDay,
    required String title,
    required String? detail,
    required String? location,
    required String? calendarId,
    required String? calendarName,
    required bool allDay,
    required TimeOfDay? startTime,
    required TimeOfDay? endTime,
    required Color color,
    required String? category,
    required int alertMinutesBefore,
    required CalendarRecurringMutationScope scope,
  }) async {
    final flow = _repeatingNoteFlowForId(originalNote.flowId);
    if (flow == null) return (clientEventId: null, eventId: null);

    final dates = _repeatingFlowRuleDates(flow);
    final selectedDate = _gregorianDateForKemeticDay(
      sourceKYear,
      sourceKMonth,
      sourceKDay,
    );
    final targetSelectedDate = _gregorianDateForKemeticDay(
      selYear,
      selMonth,
      selDay,
    );
    final plan = planCalendarRecurringDateScope(
      originalDates: dates,
      selectedDate: selectedDate,
      targetSelectedDate: targetSelectedDate,
      scope: scope,
    );
    if (plan.affectedOriginalDates.isEmpty) {
      return (clientEventId: null, eventId: null);
    }

    final selectedStart = _occurrenceStartLocal(
      ky: sourceKYear,
      km: sourceKMonth,
      kd: sourceKDay,
      allDay: originalNote.allDay,
      start: originalNote.start,
    );
    final repo = UserEventsRepo(Supabase.instance.client);
    String? resultClientEventId;
    String? resultEventId;

    switch (scope) {
      case CalendarRecurringMutationScope.thisEventOnly:
        await _persistRepeatingNoteFlow(
          flow: flow,
          dates: plan.keptOriginalDates,
          title: flow.name,
          detail: _decodeRepeatingNoteMetadata(flow.notes).detail,
          location: _decodeRepeatingNoteMetadata(flow.notes).location,
          calendarId: flow.calendarId,
          allDay: _repeatingFlowTimeFields(flow).allDay,
          startTime: _repeatingFlowTimeFields(flow).start,
          endTime: _repeatingFlowTimeFields(flow).end,
          color: flow.color,
          category: _decodeRepeatingNoteMetadata(flow.notes).category,
          alertMinutesBefore:
              _decodeRepeatingNoteMetadata(flow.notes).alertMinutes ??
              _alertNoneMinutes,
          caller: 'repeat_scope_edit_this_keep_series',
        );
        _removeLocalRepeatingNotesForDates(
          flowId: flow.id,
          dates: plan.affectedOriginalDates,
        );
        await _deleteRepeatingOccurrenceRow(
          note: originalNote,
          deleteScope: 'repeat_edit_this_original',
        );
        final saved = await _saveSingleNoteOnly(
          selYear: selYear,
          selMonth: selMonth,
          selDay: selDay,
          title: title,
          detail: detail,
          location: location,
          calendarId: calendarId,
          calendarName: calendarName,
          allDay: allDay,
          startTime: startTime,
          endTime: endTime,
          color: color,
          category: category,
          alertMinutesBefore: alertMinutesBefore,
          notifyShared: false,
        );
        resultClientEventId = saved.clientEventId;
        resultEventId = saved.eventId;
        break;

      case CalendarRecurringMutationScope.thisAndFuture:
        if (plan.keptOriginalDates.isEmpty) {
          await repo.deleteByFlowId(
            flow.id,
            fromDate: selectedStart.toUtc(),
            semantic: 'repeat_scope_edit',
            sourceFeature: 'CalendarPage._applyRepeatingNoteEditScope',
            deleteScope: 'repeat_this_and_future_replace',
          );
          final updatedFlow = await _persistRepeatingNoteFlow(
            flow: flow,
            dates: plan.shiftedAffectedDates,
            title: title,
            detail: detail,
            location: location,
            calendarId: calendarId,
            allDay: allDay,
            startTime: startTime,
            endTime: endTime,
            color: color,
            category: category,
            alertMinutesBefore: alertMinutesBefore,
            rescheduleFromDate: plan.shiftedAffectedDates.reduce(
              (a, b) => a.isBefore(b) ? a : b,
            ),
            caller: 'repeat_scope_edit_future_as_series',
          );
          if (updatedFlow != null) {
            resultClientEventId = _buildCid(
              ky: selYear,
              km: selMonth,
              kd: selDay,
              title: title,
              startHour: allDay || startTime == null ? null : startTime.hour,
              startMinute: allDay || startTime == null
                  ? null
                  : startTime.minute,
              allDay: allDay,
              flowId: updatedFlow.id,
            );
          }
        } else {
          final meta = _decodeRepeatingNoteMetadata(flow.notes);
          final time = _repeatingFlowTimeFields(flow);
          await _persistRepeatingNoteFlow(
            flow: flow,
            dates: plan.keptOriginalDates,
            title: flow.name,
            detail: meta.detail,
            location: meta.location,
            calendarId: flow.calendarId,
            allDay: time.allDay,
            startTime: time.start,
            endTime: time.end,
            color: flow.color,
            category: meta.category,
            alertMinutesBefore: meta.alertMinutes ?? _alertNoneMinutes,
            caller: 'repeat_scope_edit_future_keep_past',
          );
          _removeLocalRepeatingNotesForDates(
            flowId: flow.id,
            dates: plan.affectedOriginalDates,
          );
          await repo.deleteByFlowId(
            flow.id,
            fromDate: selectedStart.toUtc(),
            semantic: 'repeat_scope_edit',
            sourceFeature: 'CalendarPage._applyRepeatingNoteEditScope',
            deleteScope: 'repeat_this_and_future_original',
          );
          final newFlow = await _createRepeatingNoteFlowFromDates(
            dates: plan.shiftedAffectedDates,
            title: title,
            detail: detail,
            location: location,
            calendarId: calendarId,
            allDay: allDay,
            startTime: startTime,
            endTime: endTime,
            color: color,
            category: category,
            alertMinutesBefore: alertMinutesBefore,
          );
          resultClientEventId = _buildCid(
            ky: selYear,
            km: selMonth,
            kd: selDay,
            title: title,
            startHour: allDay || startTime == null ? null : startTime.hour,
            startMinute: allDay || startTime == null ? null : startTime.minute,
            allDay: allDay,
            flowId: newFlow.id,
          );
        }
        break;

      case CalendarRecurringMutationScope.entireSeries:
        await repo.deleteByFlowId(
          flow.id,
          semantic: 'repeat_scope_edit',
          sourceFeature: 'CalendarPage._applyRepeatingNoteEditScope',
          deleteScope: 'repeat_entire_series_replace',
        );
        final updatedFlow = await _persistRepeatingNoteFlow(
          flow: flow,
          dates: plan.shiftedAffectedDates,
          title: title,
          detail: detail,
          location: location,
          calendarId: calendarId,
          allDay: allDay,
          startTime: startTime,
          endTime: endTime,
          color: color,
          category: category,
          alertMinutesBefore: alertMinutesBefore,
          rescheduleFromDate: plan.shiftedAffectedDates.reduce(
            (a, b) => a.isBefore(b) ? a : b,
          ),
          caller: 'repeat_scope_edit_entire_series',
        );
        if (updatedFlow != null) {
          resultClientEventId = _buildCid(
            ky: selYear,
            km: selMonth,
            kd: selDay,
            title: title,
            startHour: allDay || startTime == null ? null : startTime.hour,
            startMinute: allDay || startTime == null ? null : startTime.minute,
            allDay: allDay,
            flowId: updatedFlow.id,
          );
        }
        break;
    }

    await _notifySharedRepeatingScope(
      calendarId: calendarId ?? originalNote.calendarId ?? flow.calendarId,
      title: title,
      scope: scope,
      isDelete: false,
      clientEventId: resultClientEventId ?? originalNote.clientEventId,
      eventId: resultEventId ?? originalNote.id,
      flowId: flow.id,
    );
    await _requestHydration(
      _CalendarHydrationRequest.catalogReconcile(
        reason: 'repeat_scope_edit_${scope.name}',
      ),
    );
    return (clientEventId: resultClientEventId, eventId: resultEventId);
  }

  CalendarMutationIdentity? _buildDeletionIdentity({
    String? id,
    String? clientEventId,
    int? kYear,
    int? kMonth,
    int? kDay,
    String? title,
    bool? allDay,
    TimeOfDay? start,
    TimeOfDay? end,
    int? flowId,
  }) {
    String? fallbackKey;
    if (kYear != null &&
        kMonth != null &&
        kDay != null &&
        title != null &&
        title.trim().isNotEmpty) {
      final normalizedTitle = title.trim().toLowerCase();
      final startMin = start == null ? -1 : (start.hour * 60 + start.minute);
      final endMin = end == null ? -1 : (end.hour * 60 + end.minute);
      final fid = flowId ?? -9999;
      final allDayFlag = allDay == true ? '1' : '0';
      fallbackKey =
          '$kYear-$kMonth-$kDay|$normalizedTitle|$allDayFlag|$startMin|$endMin|$fid';
    }
    final identity = CalendarMutationIdentity.userEvent(
      databaseId: id,
      clientEventId: clientEventId,
      fallbackKey: fallbackKey,
    );
    return identity.isEmpty ? null : identity;
  }

  bool _isPendingDelete({
    String? id,
    String? clientEventId,
    int? kYear,
    int? kMonth,
    int? kDay,
    String? title,
    bool? allDay,
    TimeOfDay? start,
    TimeOfDay? end,
    int? flowId,
    int? hydrationPassEpoch,
  }) {
    final identity = _buildDeletionIdentity(
      id: id,
      clientEventId: clientEventId,
      kYear: kYear,
      kMonth: kMonth,
      kDay: kDay,
      title: title,
      allDay: allDay,
      start: start,
      end: end,
      flowId: flowId,
    );
    final hit =
        identity != null &&
        _pendingDeletes.suppress(
          identity,
          observedInHydrationEpoch: hydrationPassEpoch,
        );
    if (hit && kDebugMode) {
      _calendarDebugPrint(
        '[hydrationEngine] skip pending delete aliases=${identity.aliases.length}',
      );
    }
    return hit;
  }

  void _schedulePendingDeleteReconciliation({
    required DateTime localDate,
    required bool deleteAccepted,
  }) {
    if (!mounted || Supabase.instance.client.auth.currentUser == null) return;
    unawaited(
      _requestHydration(
        _CalendarHydrationRequest.targeted(
          reason: deleteAccepted
              ? 'pending_delete_confirm'
              : 'pending_delete_rejected',
          intentKind: CalendarHydrationIntentKind.affectedDate,
          interval: CalendarHydrationInterval.fromInclusiveLocalDays(
            firstLocalDay: localDate,
            lastLocalDay: localDate,
          ),
        ),
      ),
    );
  }

  CalendarOccurrenceIdentity? _reminderOccurrenceIdentityForNote(
    _Note note,
    int kYear,
    int kMonth,
    int kDay,
  ) {
    return _reminderOccurrenceIdentityForLocalDate(
      note,
      KemeticMath.toGregorian(kYear, kMonth, kDay),
    );
  }

  CalendarOccurrenceIdentity? _reminderOccurrenceIdentityForLocalDate(
    _Note note,
    DateTime? localDate,
  ) {
    final parsed = CalendarOccurrenceIdentity.tryParse(note.clientEventId);
    if (parsed != null) return parsed;
    if (!note.isReminder || localDate == null) return null;
    final reminderId = note.reminderId?.trim();
    if (reminderId == null || reminderId.isEmpty) return null;
    return CalendarOccurrenceIdentity.reminder(
      reminderId: reminderId,
      localDate: localDate,
    );
  }

  Future<bool> _deleteReminderOccurrence({
    required _Note note,
    required CalendarOccurrenceIdentity identity,
  }) async {
    final identities = <CalendarOccurrenceIdentity>[
      for (final reminderId in _logicalReminderRuleIds(identity.sourceId))
        CalendarOccurrenceIdentity.reminder(
          reminderId: reminderId,
          localDate: identity.localDate,
        ),
    ];
    try {
      // The exclusion is the durable user command. The user_events delete
      // below is only cleanup of a replaceable materialized occurrence.
      for (final occurrenceIdentity in identities) {
        await _recordOccurrenceExclusion(occurrenceIdentity);
      }
    } catch (error) {
      if (kDebugMode) {
        _calendarDebugPrint(
          '[delete-reminder-occurrence] exclusion failed: '
          '${error.runtimeType}',
        );
      }
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not delete this reminder occurrence.'),
            backgroundColor: Colors.red,
          ),
        );
      }
      return false;
    }

    _replaceLiveNoteBuckets(_notes);
    if (mounted) {
      setState(() {});
      _notifyDayViewDataChanged();
    }

    final repo = UserEventsRepo(Supabase.instance.client);
    for (final occurrenceIdentity in identities) {
      await _syncOccurrenceExclusionToServer(occurrenceIdentity);
    }
    try {
      if (note.id?.trim().isNotEmpty == true) {
        await repo.delete(
          note.id!,
          clientEventId: note.clientEventId ?? identity.canonicalKey,
        );
      } else {
        await repo.deleteByClientId(identity.canonicalKey);
      }
      for (final occurrenceIdentity in identities) {
        if (occurrenceIdentity == identity) continue;
        await repo.deleteByClientId(occurrenceIdentity.canonicalKey);
      }
    } catch (error) {
      // The exclusion already owns absence. A later sync will prune the stale
      // materialized row, so cleanup failure must not resurrect the reminder.
      if (kDebugMode) {
        _calendarDebugPrint(
          '[delete-reminder-occurrence] cache cleanup deferred: '
          '${error.runtimeType}',
        );
      }
    }
    try {
      await Notify.cancelNotificationForEvent(identity.canonicalKey);
    } catch (_) {
      // Notification cleanup is retried by normal reminder reconciliation.
    }

    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('✓ Deleted: ${note.title}'),
          backgroundColor: Colors.green,
          duration: const Duration(seconds: 1),
        ),
      );
    }
    return true;
  }

  Future<bool> _deleteNote(int kYear, int kMonth, int kDay, int index) async {
    final k = _kKey(kYear, kMonth, kDay);
    final existing = _notes[k];
    if (existing == null || index < 0 || index >= existing.length) return false;

    // Capture note before removal so we know what to delete remotely.
    final note = existing[index];
    if (_isBirthdayOccurrence(
      category: note.category,
      clientEventId: note.clientEventId,
    )) {
      _showBirthdayReadOnlyMessage();
      return false;
    }
    if (isImportedDeviceCalendarEvent(
      clientEventId: note.clientEventId,
      category: note.category,
    )) {
      _showImportedCalendarReadOnlyMessage();
      return false;
    }
    final String deletedTitle = note.title;
    final manualCid = _manualCidForNote(note, kYear, kMonth, kDay);
    final int? flowIdForNote = note.flowId;

    final repeatingFlow = _repeatingNoteFlowForId(flowIdForNote);
    if (repeatingFlow != null) {
      final scope = await _showRepeatingEventScopeSheet(
        context: context,
        isDelete: true,
      );
      if (scope == null) return false;
      final deleted = await _applyRepeatingNoteDeleteScope(
        note: note,
        kYear: kYear,
        kMonth: kMonth,
        kDay: kDay,
        scope: scope,
      );
      if (deleted && mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('✓ Deleted: $deletedTitle'),
            backgroundColor: Colors.green,
            duration: const Duration(seconds: 1),
          ),
        );
      }
      return deleted;
    }
    final reminderOccurrenceIdentity = _reminderOccurrenceIdentityForNote(
      note,
      kYear,
      kMonth,
      kDay,
    );
    if (reminderOccurrenceIdentity != null) {
      return _deleteReminderOccurrence(
        note: note,
        identity: reminderOccurrenceIdentity,
      );
    }
    final pendingIdentity = _buildDeletionIdentity(
      id: note.id,
      clientEventId: note.clientEventId,
      kYear: kYear,
      kMonth: kMonth,
      kDay: kDay,
      title: note.title,
      allDay: note.allDay,
      start: note.start,
      end: note.end,
      flowId: note.flowId,
    );
    final deleteLocalDate = KemeticMath.toGregorian(kYear, kMonth, kDay);
    final pendingDeleteToken = pendingIdentity == null
        ? null
        : _pendingDeletes.register(
            identity: pendingIdentity,
            localDate: deleteLocalDate,
          );
    String? pendingCidForCleanup;
    if (pendingDeleteToken != null) {
      final cid = note.clientEventId?.trim();
      if (cid != null && cid.isNotEmpty) {
        _unconfirmed.forgetCid(cid);
        pendingCidForCleanup = cid;
      }
      if (kDebugMode) {
        _calendarDebugPrint(
          '[delete-note] pending delete aliases=${pendingIdentity!.aliases.length}',
        );
      }
    }

    // Remove locally for responsive UI.
    _removeCalendarNotesWhere(
      (dayKey, candidate) => dayKey == k && identical(candidate, note),
    );
    setState(() {});
    _notifyDayViewDataChanged();

    if (pendingCidForCleanup != null) {
      await _removePersistedPendingCids(<String>[pendingCidForCleanup]);
    }

    final repo = UserEventsRepo(Supabase.instance.client);
    final Set<int> candidateFlowIds = <int>{};
    bool removed = false;
    bool absentSuppressed = false;
    String? successfulCid;

    Future<void> cancelNotification(String cid) async {
      try {
        await Notify.cancelNotificationForEvent(cid);
      } catch (_) {
        // ignore cancellation errors
      }
    }

    try {
      // Priority 1: Use the note's own flowId.
      if (note.flowId != null) {
        candidateFlowIds.add(note.flowId!);
        if (kDebugMode) {
          _calendarDebugPrint(
            '[delete-note] Primary candidate: flowId=${note.flowId}',
          );
        }
      }

      // Priority 2: Standalone fallback (-1).
      candidateFlowIds.add(-1);

      // Attempt direct delete by persistent id or clientEventId first.
      try {
        if (note.id != null && note.id!.trim().isNotEmpty) {
          final deleteResult = await repo.delete(
            note.id!,
            clientEventId: note.clientEventId,
          );
          if (deleteResult.isSuccess && note.clientEventId != null) {
            await cancelNotification(note.clientEventId!);
          }
          removed = deleteResult.isSuccess;
          if (removed) successfulCid = note.clientEventId;
          if (kDebugMode) {
            _calendarDebugPrint(
              '[delete-note] ✅ SUCCESS: Deleted by id=${note.id} cid=${note.clientEventId}',
            );
          }
        } else if (note.clientEventId != null &&
            note.clientEventId!.trim().isNotEmpty) {
          final deleteResult = await repo.deleteByClientId(note.clientEventId!);
          removed = deleteResult.isSuccess;
          if (removed) {
            await cancelNotification(note.clientEventId!);
            successfulCid = note.clientEventId;
          }
          if (kDebugMode) {
            _calendarDebugPrint(
              '[delete-note] ✅ SUCCESS: Deleted by clientEventId=${note.clientEventId}',
            );
          }
        }
      } catch (e) {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[delete-note] ⚠️ delete by id/clientEventId failed: $e',
          );
        }
      }

      if (removed) {
        final tombstoneCid =
            manualCid ?? _inviteImportTombstoneCid(successfulCid);
        if (tombstoneCid != null) {
          await _recordManualTombstone(tombstoneCid);
          try {
            // Store the deletion marker outside client-readable event rows so
            // deleted notes cannot resurface as calendar ghosts.
            await repo.recordDeletionTombstone(
              clientEventId: tombstoneCid,
              calendarId: note.calendarId,
              reason: 'delete_note',
            );
          } catch (e) {
            if (kDebugMode) {
              _calendarDebugPrint('[delete-note] tombstone record failed: $e');
            }
          }
        }
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('✓ Deleted: $deletedTitle'),
              backgroundColor: Colors.green,
              duration: const Duration(seconds: 1),
            ),
          );
        }
        // Local row, pending-delete key, ledger forget, server delete, and
        // tombstone are already done above. Skipping full hydration here:
        // other-device changes surface on the next trigger (resume /
        // invalidation / startup). Standalone deletes do not need flow-count
        // or reminder maintenance after hydration.
        return true;
      }

      // Priority 3: Pre-fetch events from Supabase to gather other possible flowIds.
      try {
        // Limit to a reasonable number of events for performance.
        final events = await repo.getAllEvents(limit: 1000);
        for (final evt in events) {
          if (evt.title == deletedTitle) {
            // Extract flowId from unified CID if present.
            final cid = evt.clientEventId;
            if (cid != null && cid.isNotEmpty) {
              final parsed = _flowIdFromCid(cid);
              candidateFlowIds.add(parsed);
              if (kDebugMode) {
                _calendarDebugPrint(
                  '[delete-note] Candidate from CID: flowId=$parsed, CID=$cid',
                );
              }
            }
            // Also consider flowLocalId provided by the server.
            final fid = evt.flowLocalId;
            if (fid != null) {
              candidateFlowIds.add(fid);
              if (kDebugMode) {
                _calendarDebugPrint(
                  '[delete-note] Candidate from flowLocalId: $fid',
                );
              }
            }
          }
        }
      } catch (e) {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[delete-note] ⚠️ Could not pre-fetch events for deletion: $e',
          );
        }
      }

      // Convert to list for ordered iteration.
      final List<int> candidates = candidateFlowIds.toList();
      if (kDebugMode) {
        _calendarDebugPrint(
          '[delete-note] Will try ${candidates.length} candidate flowIds: $candidates',
        );
      }

      final List<String> attemptedCids = [];

      // Try each candidate flowId.
      for (final fid in candidates) {
        final String cid = _buildCid(
          ky: kYear,
          km: kMonth,
          kd: kDay,
          title: deletedTitle,
          startHour: note.start?.hour,
          startMinute: note.start?.minute,
          allDay: note.allDay,
          flowId: fid,
        );
        attemptedCids.add(cid);
        if (kDebugMode) {
          _calendarDebugPrint('[delete-note] Trying CID: $cid');
        }
        try {
          final deleteResult = await repo.deleteByClientId(cid);
          if (deleteResult.disposition ==
              UserEventDeleteDisposition.alreadyAbsentSuppressed) {
            absentSuppressed = true;
            successfulCid ??= cid;
            continue;
          }
          removed =
              deleteResult.disposition == UserEventDeleteDisposition.deleted;
          if (!removed) continue;
          await cancelNotification(cid);
          successfulCid = cid;
          if (kDebugMode) {
            _calendarDebugPrint(
              '[delete-note] ✅ SUCCESS: Deleted with CID: $cid',
            );
          }
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text('✓ Deleted: $deletedTitle'),
                backgroundColor: Colors.green,
                duration: const Duration(seconds: 1),
              ),
            );
          }
          break;
        } catch (e) {
          if (kDebugMode) {
            _calendarDebugPrint(
              '[delete-note] ⚠️ Failed to delete with flowId=$fid: $e',
            );
          }
          // Continue to next candidate.
        }
      }

      // 🚨 LAST RESORT: Direct deletion by matching title/date.
      if (!removed) {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[delete-note] All candidate CIDs failed. Trying direct title-based deletion...',
          );
        }
        try {
          final events = await repo.getAllEvents(limit: 1000);
          for (final evt in events) {
            final evtTime = evt.startsAtUtc.toLocal();
            final kEvt = KemeticMath.fromGregorian(evtTime);
            if (evt.title == deletedTitle &&
                kEvt.kYear == kYear &&
                kEvt.kMonth == kMonth &&
                kEvt.kDay == kDay) {
              final cid = evt.clientEventId;
              if (cid != null && cid.isNotEmpty) {
                final deleteResult = await repo.deleteByClientId(cid);
                removed = deleteResult.isSuccess;
                if (!removed) continue;
                await cancelNotification(cid);
                successfulCid = cid;
                if (kDebugMode) {
                  _calendarDebugPrint(
                    '[delete-note] ✅ SUCCESS (direct): Deleted using actual CID: $cid',
                  );
                }
                if (mounted) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text('✓ Deleted: $deletedTitle'),
                      backgroundColor: Colors.green,
                      duration: const Duration(seconds: 1),
                    ),
                  );
                }
                break;
              }
            }
          }
        } catch (e) {
          if (kDebugMode) {
            _calendarDebugPrint('[delete-note] ❌ Direct deletion failed: $e');
          }
        }
      }

      if (!removed && absentSuppressed) {
        removed = true;
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('✓ Deleted: $deletedTitle'),
              backgroundColor: Colors.green,
              duration: const Duration(seconds: 1),
            ),
          );
        }
      }

      // Final status: if still not removed, show error.
      if (!removed) {
        _calendarDebugPrint(
          '[delete-note] ❌❌❌ CRITICAL: Could not delete note!',
        );
        _calendarDebugPrint(
          '[delete-note] Note: "$deletedTitle", flowId=${note.flowId}',
        );
        _calendarDebugPrint(
          '[delete-note] Attempted ${attemptedCids.length} CIDs: ${attemptedCids.join(", ")}',
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                '⚠️ Could not delete "$deletedTitle". Please delete manually in Supabase.',
              ),
              backgroundColor: Colors.red,
              duration: const Duration(seconds: 5),
              action: SnackBarAction(
                label: 'OK',
                textColor: Colors.white,
                onPressed: () {},
              ),
            ),
          );
        }
      } else {
        if (manualCid != null) {
          await _recordManualTombstone(manualCid);
        }
        if (kDebugMode) {
          _calendarDebugPrint(
            '[delete-note] ✓ Deletion confirmed: $successfulCid',
          );
        }
      }
    } finally {
      if (pendingDeleteToken != null) {
        if (removed) {
          _pendingDeletes.acknowledge(
            pendingDeleteToken,
            currentHydrationEpoch: _hydrationPassEpoch,
            additionalIdentity: CalendarMutationIdentity.userEvent(
              databaseId: note.id,
              clientEventId: successfulCid ?? note.clientEventId,
            ),
          );
        } else {
          _pendingDeletes.reject(pendingDeleteToken);
        }
        _schedulePendingDeleteReconciliation(
          localDate: deleteLocalDate,
          deleteAccepted: removed,
        );
      }
    }

    return removed;
  }

  /// Returns the index of the note in _notes[dayKey] matching id or clientEventId, or -1.
  int _findNoteIndexByIdOrClientId(
    String dayKey, {
    String? eventId,
    String? clientEventId,
  }) {
    final list = _notes[dayKey];
    if (list == null || list.isEmpty) return -1;
    final trimmedEventId = eventId?.trim();
    final trimmedClientId = clientEventId?.trim();
    return list.indexWhere((n) {
      final noteId = n.id?.trim() ?? '';
      final noteCid = n.clientEventId?.trim() ?? '';
      if (trimmedEventId != null &&
          trimmedEventId.isNotEmpty &&
          noteId == trimmedEventId) {
        return true;
      }
      if (trimmedClientId != null &&
          trimmedClientId.isNotEmpty &&
          noteCid == trimmedClientId) {
        return true;
      }
      return false;
    });
  }

  _Note? _findLatestNoteByIdOrClientId({
    String? eventId,
    String? clientEventId,
  }) {
    final trimmedEventId = eventId?.trim();
    final trimmedClientId = clientEventId?.trim();
    if ((trimmedEventId == null || trimmedEventId.isEmpty) &&
        (trimmedClientId == null || trimmedClientId.isEmpty)) {
      return null;
    }

    _Note? bestClientIdMatch;

    for (final bucket in _notes.values) {
      for (final note in bucket) {
        final noteId = note.id?.trim() ?? '';
        final noteCid = note.clientEventId?.trim() ?? '';
        if (trimmedEventId != null &&
            trimmedEventId.isNotEmpty &&
            noteId == trimmedEventId) {
          return note;
        }
        if (trimmedClientId != null &&
            trimmedClientId.isNotEmpty &&
            noteCid == trimmedClientId) {
          if (bestClientIdMatch == null) {
            bestClientIdMatch = note;
            continue;
          }
          final bestHasId = bestClientIdMatch.id?.trim().isNotEmpty ?? false;
          final noteHasId = noteId.isNotEmpty;
          if (!bestHasId && noteHasId) {
            bestClientIdMatch = note;
          }
        }
      }
    }

    return bestClientIdMatch;
  }

  _Note? _findBestReminderNoteForInvite(EventItem evt) {
    final reminderId = evt.reminderId?.trim();
    if (!evt.isReminder || reminderId == null || reminderId.isEmpty) {
      return null;
    }

    final evtTitle = evt.title.trim().toLowerCase();
    final evtLocation = (evt.location ?? '').trim().toLowerCase();
    final evtDetail = (evt.detail ?? '').trim().toLowerCase();
    final evtStartHour = evt.startMin ~/ 60;
    final evtStartMinute = evt.startMin % 60;
    final evtEndHour = evt.endMin ~/ 60;
    final evtEndMinute = evt.endMin % 60;

    int score(_Note note) {
      var value = 0;
      if (note.id?.trim().isNotEmpty ?? false) value += 4;
      if (note.clientEventId?.trim().isNotEmpty ?? false) value += 2;
      if ((note.location ?? '').trim().toLowerCase() == evtLocation) value += 1;
      if ((note.detail ?? '').trim().toLowerCase() == evtDetail) value += 1;
      return value;
    }

    _Note? best;
    for (final bucket in _notes.values) {
      for (final note in bucket) {
        if (!note.isReminder) continue;
        if ((note.reminderId?.trim() ?? '') != reminderId) continue;
        if (note.title.trim().toLowerCase() != evtTitle) continue;
        if (note.allDay != evt.allDay) continue;
        if (!evt.allDay) {
          if (note.start == null ||
              note.start!.hour != evtStartHour ||
              note.start!.minute != evtStartMinute) {
            continue;
          }
          if (note.end != null &&
              (note.end!.hour != evtEndHour ||
                  note.end!.minute != evtEndMinute)) {
            continue;
          }
        }

        if (best == null || score(note) > score(best)) {
          best = note;
        }
      }
    }

    return best;
  }

  void _attachPersistedEventIdentity({
    required String eventId,
    required String clientEventId,
  }) {
    if (!mounted) return;

    final upserts = <CalendarPendingVisibleItem<_Note>>[];
    for (final entry in _notes.entries) {
      for (final note in entry.value) {
        if ((note.clientEventId?.trim() ?? '') != clientEventId) continue;
        if (note.id?.trim().isNotEmpty ?? false) continue;
        upserts.add(
          CalendarPendingVisibleItem<_Note>(
            dayKey: entry.key,
            item: note.copyWith(id: eventId, clientEventId: clientEventId),
          ),
        );
      }
    }

    if (upserts.isNotEmpty) {
      _publishCalendarNoteMutation(upserts: upserts);
      setState(() {});
      _notifyDayViewDataChanged();
    }
  }

  int? _findNoteIndexByEvent(int ky, int km, int kd, EventItem evt) {
    final key = _kKey(ky, km, kd);
    final list = _notes[key];
    if (list == null) return null;

    // Fast path: match by id or clientEventId if present.
    final idxByIds = _findNoteIndexByIdOrClientId(
      key,
      eventId: evt.id,
      clientEventId: evt.clientEventId,
    );
    if (idxByIds >= 0) return idxByIds;

    int startHour = evt.startMin ~/ 60;
    int startMinute = evt.startMin % 60;
    int endHour = evt.endMin ~/ 60;
    int endMinute = evt.endMin % 60;
    int? metadataOnlyMatch;

    for (int i = 0; i < list.length; i++) {
      final n = list[i];
      // For flow-driven events, require flowId match when provided.
      if (evt.flowId != null && (n.flowId ?? -1) != evt.flowId) continue;
      if (n.allDay != evt.allDay) continue;
      if (!evt.allDay) {
        if (n.start == null ||
            n.start!.hour != startHour ||
            n.start!.minute != startMinute) {
          continue;
        }
        if (n.end != null &&
            (n.end!.hour != endHour || n.end!.minute != endMinute)) {
          continue;
        }
      }
      final titlesMatch =
          n.title.trim().toLowerCase() == evt.title.trim().toLowerCase();
      final locMatch =
          (n.location ?? '').trim().toLowerCase() ==
          (evt.location ?? '').trim().toLowerCase();
      final detMatch =
          (n.detail ?? '').trim().toLowerCase() ==
          (evt.detail ?? '').trim().toLowerCase();
      if (titlesMatch && locMatch && detMatch) {
        if ((n.start == null && !evt.allDay) ||
            (n.end == null && !evt.allDay)) {
          if (metadataOnlyMatch != null) return null;
          metadataOnlyMatch = i;
          continue;
        }
        return i;
      }
    }

    for (int i = 0; i < list.length; i++) {
      final n = list[i];
      if (evt.flowId != null && (n.flowId ?? -1) != evt.flowId) continue;
      if (n.allDay != evt.allDay) continue;
      final titlesMatch =
          n.title.trim().toLowerCase() == evt.title.trim().toLowerCase();
      final locMatch =
          (n.location ?? '').trim().toLowerCase() ==
          (evt.location ?? '').trim().toLowerCase();
      final detMatch =
          (n.detail ?? '').trim().toLowerCase() ==
          (evt.detail ?? '').trim().toLowerCase();
      if (!titlesMatch || !locMatch || !detMatch) continue;
      if (metadataOnlyMatch != null) return null;
      metadataOnlyMatch = i;
    }

    return metadataOnlyMatch;
  }

  Future<void> _deleteNoteByEvent(int ky, int km, int kd, EventItem evt) async {
    if (_isBirthdayOccurrence(
      category: evt.category,
      clientEventId: evt.clientEventId,
    )) {
      _showBirthdayReadOnlyMessage();
      return;
    }
    if (isImportedDeviceCalendarEvent(
      clientEventId: evt.clientEventId,
      category: evt.category,
    )) {
      _showImportedCalendarReadOnlyMessage();
      return;
    }
    final idx = _findNoteIndexByEvent(ky, km, kd, evt);
    if (idx != null) {
      await _deleteNote(ky, km, kd, idx);
    }
  }

  Future<void> _editNoteByEvent(int ky, int km, int kd, EventItem evt) async {
    if (_isBirthdayOccurrence(
      category: evt.category,
      clientEventId: evt.clientEventId,
    )) {
      _showBirthdayReadOnlyMessage();
      return;
    }
    if (isImportedDeviceCalendarEvent(
      clientEventId: evt.clientEventId,
      category: evt.category,
    )) {
      _showImportedCalendarReadOnlyMessage();
      return;
    }
    final idx = _findNoteIndexByEvent(ky, km, kd, evt);
    if (idx == null) return;
    final key = _kKey(ky, km, kd);
    final note = _notes[key]![idx];

    await Future<void>.delayed(Duration.zero, () {
      _openDaySheet(
        ky,
        km,
        kd,
        allowDateChange: true,
        initialTitle: note.title,
        initialLocation: note.location,
        initialDetail: note.detail,
        initialAllDay: note.allDay,
        initialStartTime: note.start,
        initialEndTime: note.end,
        initialColor: note.manualColor,
        initialCategory: note.category,
        initialAlertMinutes: note.alertOffsetMinutes,
        editingIndex: idx,
      );
    });
  }

  bool _isBirthdayOccurrence({String? category, String? clientEventId}) {
    final normalizedCategory = category?.trim().toLowerCase();
    if (normalizedCategory == 'birthday') return true;
    final normalizedClientEventId = (clientEventId ?? '').trim().toLowerCase();
    return normalizedClientEventId.startsWith('birthday:') ||
        normalizedClientEventId.startsWith('$kBirthdaysSystemType:');
  }

  void _showBirthdayReadOnlyMessage() {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'Birthday editing is managed from the Birthdays calendar.',
        ),
      ),
    );
  }

  void _showImportedCalendarReadOnlyMessage() {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'This event mirrors your device calendar. Edit it in Apple or Google Calendar and HAw will update automatically.',
        ),
      ),
    );
  }

  Future<void> _openFlowShareSheetFromEvent({
    required int flowId,
    required String fallbackTitle,
  }) async {
    var flowTitle = fallbackTitle.trim();
    var flowExists = false;
    for (final flow in _flows) {
      if (flow.id != flowId) continue;
      flowExists = true;
      final candidate = flow.name.trim();
      if (candidate.isNotEmpty) {
        flowTitle = candidate;
      }
      break;
    }

    if (!flowExists) {
      try {
        final persistedFlow = await _flowsRepo.getFlowById(flowId);
        if (persistedFlow != null) {
          flowExists = true;
          final candidate = persistedFlow.name.trim();
          if (candidate.isNotEmpty) {
            flowTitle = candidate;
          }
        }
      } catch (_) {
        // Ignore lookup failures here and surface the generic share error below.
      }
    }

    if (!flowExists) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('This flow is no longer available to share.'),
          ),
        );
      }
      return;
    }

    if (flowTitle.isEmpty) {
      flowTitle = 'Flow';
    }

    if (!mounted) return;
    await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) => ShareFlowSheet(flowId: flowId, flowTitle: flowTitle),
    );
  }

  Future<void> _shareFlowFromEventItem(EventItem evt) async {
    final flowId = evt.flowId;
    if (flowId == null || evt.isReminder) return;
    await _openFlowShareSheetFromEvent(
      flowId: flowId,
      fallbackTitle: evt.title,
    );
  }

  Future<void> _shareNoteSimple(EventItem evt) async {
    _Note? latest =
        _findLatestNoteByIdOrClientId(
          eventId: evt.id,
          clientEventId: evt.clientEventId,
        ) ??
        _findBestReminderNoteForInvite(evt);

    var eventId = (latest?.id ?? evt.id)?.trim();
    var lookupClientId = (latest?.clientEventId ?? evt.clientEventId)?.trim();

    if ((eventId == null || eventId.isEmpty) &&
        (lookupClientId == null || lookupClientId.isEmpty) &&
        evt.isReminder) {
      await _requestHydration(
        _CalendarHydrationRequest.targeted(
          reason: 'reminder_event_identity_refresh',
          intentKind: CalendarHydrationIntentKind.affectedDate,
        ),
      );
      if (!mounted) return;

      latest =
          _findLatestNoteByIdOrClientId(
            eventId: evt.id,
            clientEventId: evt.clientEventId,
          ) ??
          _findBestReminderNoteForInvite(evt);
      eventId = (latest?.id ?? evt.id)?.trim();
      lookupClientId = (latest?.clientEventId ?? evt.clientEventId)?.trim();
    }

    if ((eventId == null || eventId.isEmpty) &&
        lookupClientId != null &&
        lookupClientId.isNotEmpty) {
      final persisted = await UserEventsRepo(
        Supabase.instance.client,
      ).getEventByClientEventId(lookupClientId);
      if (persisted != null) {
        eventId = persisted.id.trim();
        _attachPersistedEventIdentity(
          eventId: persisted.id,
          clientEventId: persisted.clientEventId ?? lookupClientId,
        );
      }
    }

    if (eventId == null || eventId.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Save this event first, then invite people.'),
        ),
      );
      return;
    }
    if (!mounted) return;
    await _openEventInviteSheet(
      eventId: eventId,
      title: latest?.title ?? evt.title,
    );
  }

  Future<void> _openEventInviteSheet({
    required String eventId,
    required String title,
  }) async {
    await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) =>
          ShareFlowSheet(flowId: null, flowTitle: title, eventId: eventId),
    );
  }

  EventItem _noteToEventItem(_Note note) {
    final startMin = note.allDay
        ? 9 * 60
        : (note.start?.hour ?? 9) * 60 + (note.start?.minute ?? 0);
    final endMin = note.allDay
        ? 17 * 60
        : (note.end?.hour ?? 17) * 60 + (note.end?.minute ?? 0);

    // Prefer manual color; otherwise use resolver (handles flow color).
    final resolvedColor = note.manualColor ?? _noteColor(note);

    return EventItem(
      id: note.id,
      clientEventId: note.clientEventId,
      calendarId: note.calendarId,
      calendarName: note.calendarName,
      title: note.title,
      detail: note.detail,
      location: note.location,
      startMin: startMin,
      endMin: endMin,
      flowId: note.flowId,
      color: resolvedColor,
      manualColor: note.manualColor,
      allDay: note.allDay,
      category: note.category,
      isReminder: note.isReminder,
      reminderId: note.reminderId,
      behaviorPayload: note.behaviorPayload,
    );
  }

  Future<void> _moveEventInDayView(
    int ky,
    int km,
    int kd,
    EventItem evt,
    int proposedStartMin,
  ) async {
    if (isImportedDeviceCalendarEvent(
      clientEventId: evt.clientEventId,
      category: evt.category,
    )) {
      _showImportedCalendarReadOnlyMessage();
      return;
    }
    final rawId = evt.id?.trim();
    final rawClientId = evt.clientEventId?.trim();
    final moveKeyForLog = (rawId != null && rawId.isNotEmpty)
        ? rawId
        : (rawClientId != null && rawClientId.isNotEmpty)
        ? rawClientId
        : '<none>';
    if (kDebugMode) {
      _calendarDebugPrint(
        '[DayView] move start id=${safeLogIdentifier(evt.id)} '
        'cid=${safeLogIdentifier(evt.clientEventId)} '
        'rawId=${safeLogIdentifier(rawId)} '
        'rawCid=${safeLogIdentifier(rawClientId)} '
        'moveKey=$moveKeyForLog '
        'title=<redacted chars=${evt.title.length}> '
        'flowId=${evt.flowId} startMin=${evt.startMin} '
        'endMin=${evt.endMin} proposedStart=$proposedStartMin',
      );
    }
    if (evt.allDay) {
      if (kDebugMode) {
        _calendarDebugPrint(
          '[DayView] move bail: all-day event "${evt.title}"',
        );
      }
      return;
    }
    if (evt.isReminder) {
      if (kDebugMode) {
        _calendarDebugPrint('[DayView] move bail: reminder "${evt.title}"');
      }
      return;
    }

    if ((rawId == null || rawId.isEmpty) &&
        (rawClientId == null || rawClientId.isEmpty)) {
      if (kDebugMode) {
        _calendarDebugPrint(
          '[DayView] move bail: no id/clientEventId for "${evt.title}"',
        );
      }
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Save event before moving.')),
        );
      }
      return;
    }

    final moveKey = (rawId != null && rawId.isNotEmpty) ? rawId : rawClientId!;
    if (_eventMoveInProgress.contains(moveKey)) {
      if (kDebugMode) {
        _calendarDebugPrint('[DayView] move already in progress for $moveKey');
      }
      return;
    }
    _eventMoveInProgress.add(moveKey);

    final key = _kKey(ky, km, kd);
    _Note? previousNote;
    _Note? publishedNote;
    final bool isReminderOccurrence =
        rawClientId != null && rawClientId.startsWith('reminder:');
    String? detailWithOverrideMarker;
    if (isReminderOccurrence) {
      final currentDetail = evt.detail ?? '';
      if (currentDetail.contains(_kReminderManualOverrideMarker)) {
        detailWithOverrideMarker = currentDetail;
      } else {
        final needsNewline =
            currentDetail.isNotEmpty && !currentDetail.endsWith('\n');
        detailWithOverrideMarker =
            '$currentDetail${needsNewline ? '\n' : ''}$_kReminderManualOverrideMarker';
      }
    }

    String fmtTod(TimeOfDay? tod) {
      if (tod == null) return 'all-day';
      final hh = tod.hour.toString().padLeft(2, '0');
      final mm = tod.minute.toString().padLeft(2, '0');
      return '$hh:$mm';
    }

    void logBucket(String label) {
      if (!kDebugMode) return;
      final bucket = _notes[key] ?? const [];
      final summary = bucket
          .map(
            (n) =>
                'id=${n.id ?? '-'} cid=${n.clientEventId ?? '-'} start=${fmtTod(n.start)}',
          )
          .join(' | ');
      _calendarDebugPrint(
        '[DayView] $label key=$key count=${bucket.length} notes=[$summary]',
      );
    }

    try {
      int durationMin = evt.endMin - evt.startMin;
      if (durationMin < 15) durationMin = 15;
      final int maxStart = (1440 - durationMin).clamp(0, 1440).toInt();
      int clampedStart = proposedStartMin.clamp(0, maxStart).toInt();
      int clampedEnd = clampedStart + durationMin;
      if (clampedEnd > 1439) {
        clampedEnd = 1439;
        clampedStart = (clampedEnd - durationMin).clamp(0, 1439).toInt();
      }

      if (clampedStart == evt.startMin && clampedEnd == evt.endMin) {
        if (kDebugMode) {
          _calendarDebugPrint('[DayView] move no-op for $moveKey');
        }
        return;
      }

      final gregorian = KemeticMath.toGregorian(ky, km, kd);
      final startLocal = DateTime(
        gregorian.year,
        gregorian.month,
        gregorian.day,
        clampedStart ~/ 60,
        clampedStart % 60,
      );
      final endLocal = DateTime(
        gregorian.year,
        gregorian.month,
        gregorian.day,
        clampedEnd ~/ 60,
        clampedEnd % 60,
      );

      final repeatingFlow = _repeatingNoteFlowForId(evt.flowId);
      if (repeatingFlow != null) {
        final scope = await _showRepeatingEventScopeSheet(
          context: context,
          isDelete: false,
        );
        if (scope == null) return;
        final idx = _findNoteIndexByEvent(ky, km, kd, evt);
        final originalNote = idx == null
            ? _Note(
                id: evt.id,
                clientEventId: evt.clientEventId,
                calendarId: evt.calendarId,
                calendarName: evt.calendarName,
                title: evt.title,
                detail: evt.detail,
                location: evt.location,
                allDay: evt.allDay,
                start: TimeOfDay(
                  hour: evt.startMin ~/ 60,
                  minute: evt.startMin % 60,
                ),
                end: TimeOfDay(hour: evt.endMin ~/ 60, minute: evt.endMin % 60),
                flowId: evt.flowId,
                manualColor: evt.manualColor,
                category: evt.category,
                alertOffsetMinutes: _decodeDetailMetadata(
                  evt.detail,
                ).alertMinutes,
              )
            : _notes[key]![idx];
        await _applyRepeatingNoteEditScope(
          originalNote: originalNote,
          sourceKYear: ky,
          sourceKMonth: km,
          sourceKDay: kd,
          selYear: ky,
          selMonth: km,
          selDay: kd,
          title: evt.title,
          detail: evt.detail,
          location: evt.location,
          calendarId: evt.calendarId ?? repeatingFlow.calendarId,
          calendarName: evt.calendarName,
          allDay: false,
          startTime: TimeOfDay(
            hour: clampedStart ~/ 60,
            minute: clampedStart % 60,
          ),
          endTime: TimeOfDay(hour: clampedEnd ~/ 60, minute: clampedEnd % 60),
          color: evt.manualColor ?? repeatingFlow.color,
          category: evt.category,
          alertMinutesBefore:
              originalNote.alertOffsetMinutes ?? _alertNoneMinutes,
          scope: scope,
        );
        return;
      }

      final repo = UserEventsRepo(Supabase.instance.client);
      final importedDeviceEvent = isImportedDeviceCalendarEvent(
        clientEventId: rawClientId,
        category: evt.category,
      );
      final effectiveCategory = _editableStandaloneCategory(
        detachImportedDeviceEvent: importedDeviceEvent,
        category: evt.category,
      );
      final detailToPersist = isReminderOccurrence
          ? detailWithOverrideMarker
          : evt.detail;
      UserEvent updated;
      if (importedDeviceEvent) {
        final detachedCid = _buildCid(
          ky: ky,
          km: km,
          kd: kd,
          title: evt.title,
          startHour: clampedStart ~/ 60,
          startMinute: clampedStart % 60,
          allDay: evt.allDay,
          flowId: -1,
        );
        if (kDebugMode) {
          _calendarDebugPrint(
            '[DayView] move persist: detaching imported device event oldCid=$rawClientId newCid=$detachedCid start=${startLocal.toUtc()} end=${endLocal.toUtc()}',
          );
        }
        if (rawId != null && rawId.isNotEmpty) {
          updated = await repo.replace(
            id: rawId,
            clientEventId: detachedCid,
            title: evt.title,
            detail: detailToPersist,
            location: evt.location,
            allDay: evt.allDay,
            startsAt: startLocal,
            endsAt: endLocal,
            category: effectiveCategory,
          );
        } else {
          final persisted = rawClientId == null
              ? null
              : await repo.getEventByClientEventId(rawClientId);
          if (persisted != null) {
            updated = await repo.replace(
              id: persisted.id,
              clientEventId: detachedCid,
              title: evt.title,
              detail: detailToPersist,
              location: evt.location,
              allDay: evt.allDay,
              startsAt: startLocal,
              endsAt: endLocal,
              category: effectiveCategory,
            );
          } else {
            updated = await repo.upsertByClientId(
              clientEventId: detachedCid,
              title: evt.title,
              startsAtUtc: startLocal.toUtc(),
              detail: detailToPersist,
              location: evt.location,
              allDay: evt.allDay,
              endsAtUtc: endLocal.toUtc(),
              flowLocalId: null,
              category: effectiveCategory,
              caller: 'move_event_detach',
            );
          }
          if (rawClientId != null && rawClientId != detachedCid) {
            try {
              await repo.deleteByClientId(rawClientId);
            } catch (_) {
              // Best-effort cleanup for a stale imported row.
            }
          }
        }
      } else if (rawId != null && rawId.isNotEmpty) {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[DayView] move persist: update by id=$rawId start=${startLocal.toUtc()} end=${endLocal.toUtc()}',
          );
        }
        updated = await repo.update(
          id: rawId,
          startsAt: startLocal.toUtc(),
          endsAt: endLocal.toUtc(),
          detail: isReminderOccurrence ? detailWithOverrideMarker : null,
        );
      } else {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[DayView] move persist: upsert by cid=$rawClientId start=${startLocal.toUtc()} end=${endLocal.toUtc()}',
          );
        }
        updated = await repo.upsertByClientId(
          clientEventId: rawClientId!,
          title: evt.title,
          startsAtUtc: startLocal.toUtc(),
          detail: detailToPersist,
          location: evt.location,
          allDay: evt.allDay,
          endsAtUtc: endLocal.toUtc(),
          flowLocalId: evt.flowId,
          category: effectiveCategory,
          caller: 'move_event',
        );
      }
      if (kDebugMode) {
        _calendarDebugPrint(
          '[DayView] move persist: result id=${updated.id} cid=${updated.clientEventId} start=${updated.startsAt} end=${updated.endsAt}',
        );
      }

      final TimeOfDay updatedStart = TimeOfDay(
        hour: clampedStart ~/ 60,
        minute: clampedStart % 60,
      );
      final TimeOfDay updatedEnd = TimeOfDay(
        hour: clampedEnd ~/ 60,
        minute: clampedEnd % 60,
      );

      final updatedMeta = _decodeDetailMetadata(updated.detail);
      final cleanedDetail = _cleanDetail(updatedMeta.detail);

      _Note reminderNote;
      final localIdx = _findNoteIndexByIdOrClientId(
        key,
        eventId: updated.id,
        clientEventId: updated.clientEventId,
      );
      if (localIdx != -1) {
        final existing = _notes[key]![localIdx];
        previousNote = existing;
        if (kDebugMode) {
          _calendarDebugPrint(
            '[DayView] move: local note found at index $localIdx id=${existing.id} cid=${existing.clientEventId}',
          );
        }
        final replacement = existing.copyWith(
          id: updated.id,
          clientEventId: updated.clientEventId,
          detail: cleanedDetail,
          start: updatedStart,
          end: updatedEnd,
          category: updated.category,
          alertOffsetMinutes:
              existing.alertOffsetMinutes ??
              updatedMeta.alertMinutes ??
              _alertNoneMinutes,
        );
        reminderNote = replacement;
      } else {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[DayView] move: note not found locally for id=${updated.id} cid=${updated.clientEventId}; reconciling fallback into _notes',
          );
        }
        reminderNote = _Note(
          id: updated.id.trim(),
          clientEventId: updated.clientEventId?.trim(),
          calendarId: updated.calendarId?.trim(),
          calendarName: updated.calendarName?.trim(),
          title: updated.title.trim().isNotEmpty ? updated.title : evt.title,
          detail: cleanedDetail,
          location: updated.location,
          allDay: updated.allDay,
          start: updatedStart,
          end: updatedEnd,
          flowId: updated.flowLocalId,
          manualColor:
              evt.manualColor ??
              (updated.calendarIsPersonal
                  ? null
                  : (updated.calendarColor != null
                        ? Color(updated.calendarColor!)
                        : null)),
          category: updated.category,
          isReminder: evt.isReminder,
          reminderId: evt.reminderId,
          alertOffsetMinutes: updatedMeta.alertMinutes ?? _alertNoneMinutes,
        );
        _unconfirmed.forgetCids(<String>{
          if ((reminderNote.clientEventId ?? '').trim().isNotEmpty)
            reminderNote.clientEventId!.trim(),
          if ((rawClientId ?? '').trim().isNotEmpty) rawClientId!.trim(),
        });
      }

      _publishCalendarNoteMutation(
        upserts: <CalendarPendingVisibleItem<_Note>>[
          CalendarPendingVisibleItem<_Note>(dayKey: key, item: reminderNote),
        ],
        sourceConflictRule: (sourceDayKey, source, pendingDayKey, pending) {
          if (sourceDayKey != pendingDayKey) return false;
          if (_calendarNoteMatchesIdentityAliases(
            source,
            eventIds: <String?>[pending.id, rawId],
            clientEventIds: <String?>[pending.clientEventId, rawClientId],
          )) {
            return true;
          }
          if (previousNote != null) return identical(source, previousNote);
          return source.title.trim().toLowerCase() ==
                  pending.title.trim().toLowerCase() &&
              source.start != null &&
              pending.start != null &&
              source.start!.hour == pending.start!.hour &&
              source.start!.minute == pending.start!.minute;
        },
      );
      publishedNote = reminderNote;
      logBucket(
        previousNote == null
            ? 'move: reconciled note publication (fallback)'
            : 'move: replaced note publication',
      );

      final alertMinutes = _effectiveAlertMinutes(
        reminderNote.alertOffsetMinutes,
      );
      DateTime? alertLocal;
      if (alertMinutes != null) {
        alertLocal = startLocal.subtract(Duration(minutes: alertMinutes));
        final reminderId = _reminderIdForNote(reminderNote, alertLocal.toUtc());
        await _reminderService.addOrUpdate(
          Reminder(
            id: reminderId,
            eventId: reminderNote.id?.toString(),
            title: reminderNote.title,
            detail: reminderNote.detail,
            alertAtUtc: alertLocal.toUtc(),
            flowId: reminderNote.flowId?.toString(),
            createdAt: DateTime.now().toUtc(),
            updatedAt: DateTime.now().toUtc(),
          ),
        );
      }

      if (updated.clientEventId != null && updated.clientEventId!.isNotEmpty) {
        await Notify.cancelNotificationForEvent(updated.clientEventId!);
        if (alertLocal != null) {
          final bodyLines = <String>[
            if ((updated.location ?? '').trim().isNotEmpty)
              updated.location!.trim(),
            if (cleanedDetail.isNotEmpty) cleanedDetail,
          ];
          final scheduleResult =
              await Notify.scheduleAlertWithPersistenceResult(
                clientEventId: updated.clientEventId!,
                scheduledAt: alertLocal,
                title: reminderNote.title,
                body: bodyLines.isEmpty ? null : bodyLines.join('\n'),
                payload: CalendarPage._calendarNotificationPayloadJson(
                  itemType:
                      reminderNote.flowId != null && reminderNote.flowId! > 0
                      ? calendarPushItemTypeFlowEvent
                      : calendarPushItemTypeNote,
                  kYear: ky,
                  kMonth: km,
                  kDay: kd,
                  eventId: updated.id,
                  clientEventId: updated.clientEventId,
                  reminderId: reminderNote.reminderId,
                  flowId: reminderNote.flowId,
                ),
              );
          if (scheduleResult.needsUserVisibleWarning) {
            _showNotificationScheduleWarning(scheduleResult.message);
          }
        }
      }

      _notifyDayViewDataChanged();
    } catch (e, st) {
      final rollbackNote = previousNote;
      final failedNote = publishedNote;
      if (rollbackNote != null && failedNote != null) {
        _publishCalendarNoteMutation(
          upserts: <CalendarPendingVisibleItem<_Note>>[
            CalendarPendingVisibleItem<_Note>(dayKey: key, item: rollbackNote),
          ],
          sourceConflictRule: (sourceDayKey, source, pendingDayKey, _) =>
              sourceDayKey == pendingDayKey &&
              _calendarNoteMatchesIdentityAliases(
                source,
                eventIds: <String?>[failedNote.id],
                clientEventIds: <String?>[failedNote.clientEventId],
              ),
        );
      }
      if (kDebugMode) {
        _calendarDebugPrint('[DayView] move failed for $moveKey: $e');
        _calendarDebugPrint('$st');
      }
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text("Couldn't move event.")));
      }
    } finally {
      _eventMoveInProgress.remove(moveKey);
    }
  }

  // Flows — add/remove/toggle
  // >>> FIND-ME: PATCH-2 _saveNewFlow AFTER
  Future<int?> _saveNewFlow(_Flow flow) async {
    try {
      final repo = UserEventsRepo(Supabase.instance.client);
      final rulesJson = jsonEncode(flow.rules.map(ruleToJson).toList());

      final savedId = await repo.upsertFlow(
        id: null, // let server assign id
        name: flow.name,
        color: flow.color.toARGB32(),
        active: flow.active,
        calendarId: flow.calendarId,
        startDate: flow.start,
        endDate: flow.end,
        notes: flow.notes,
        rules: rulesJson,
        isHidden: flow.isHidden,
        isSaved: flow.isSaved,
        shareId: flow.shareId,
        isReminder: flow.isReminder,
        reminderUuid: flow.reminderUuid,
      );

      // Keep nextFlowId monotonic with server ids
      if (savedId >= _nextFlowId) _nextFlowId = savedId + 1;

      final persisted = _Flow(
        id: savedId,
        calendarId: flow.calendarId,
        name: flow.name,
        color: flow.color,
        active: flow.active,
        isSaved: flow.isSaved,
        savedAt: flow.savedAt,
        rules: flow.rules,
        start: flow.start,
        end: flow.end,
        notes: flow.notes,
        shareId: flow.shareId,
        isHidden: flow.isHidden,
        isReminder: flow.isReminder,
        reminderUuid: flow.reminderUuid,
      );

      _flows.add(persisted);
      await _ensureSharedExperienceForFlow(
        flowId: savedId,
        calendarId: flow.calendarId,
        source: 'CalendarPage._saveNewFlow',
      );
      if (mounted) setState(() {});
      _notifyDayViewDataChanged();

      return savedId;
    } on PostgrestException catch (e, st) {
      _calendarDebugPrint('[saveNewFlow] ✗ ${e.code} ${e.message}');
      final details = e.details?.toString() ?? '';
      if (details.isNotEmpty) {
        _calendarDebugPrint('[saveNewFlow] details: $details');
      }
      final hint = e.hint?.toString() ?? '';
      if (hint.isNotEmpty) _calendarDebugPrint('[saveNewFlow] hint: $hint');
      _calendarDebugPrint(
        '[saveNewFlow] nulls start:${flow.start == null} end:${flow.end == null} notes:${flow.notes == null} shareId:${flow.shareId == null} isReminder:${flow.isReminder} isSaved:${flow.isSaved}',
      );
      _calendarDebugPrint('$st');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Unable to save flow to cloud. Please retry.'),
            duration: Duration(seconds: 2),
          ),
        );
      }
      return null;
    } catch (e, st) {
      _calendarDebugPrint('[saveNewFlow] ✗ $e');
      _calendarDebugPrint('$st');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Unable to save flow to cloud. Please retry.'),
            duration: Duration(seconds: 2),
          ),
        );
      }
      return null;
    }
  }

  void _deleteFlow(int flowId) {
    final flow = _flows.firstWhere(
      (f) => f.id == flowId,
      orElse: () => _Flow(
        id: flowId,
        name: '',
        color: Colors.white,
        active: false,
        rules: const [],
      ),
    );
    final isSaved = flow.isSaved;

    CalendarPage._forgetRememberedJoinedMaatFlow(flowId);
    _myFlowsFilingSnapshotCache = null;
    unawaited(_flowsRepo.clearMyFiledFlowsCache());

    final removed = _removeCalendarNotesWhere(
      (_, note) => note.flowId == flowId,
    );
    _unconfirmed.forgetCids(removed.clientEventIds);

    if (isSaved) {
      // For saved flows, keep the flow row and events as a template,
      // just mark it inactive so it disappears from the calendar.
      final idx = _flows.indexWhere((f) => f.id == flowId);
      if (idx >= 0) {
        final f = _flows[idx];
        _flows[idx] = _Flow(
          id: f.id,
          calendarId: f.calendarId,
          name: f.name,
          color: f.color,
          active: false,
          rules: f.rules,
          start: f.start,
          end: f.end,
          notes: f.notes,
          shareId: f.shareId,
          isHidden: f.isHidden,
          isSaved: f.isSaved,
          savedAt: f.savedAt,
          isReminder: f.isReminder,
          reminderUuid: f.reminderUuid,
        );
      }
      setState(() {});
    } else {
      _flows.removeWhere((f) => f.id == flowId);
      setState(() {});
    }

    Future.microtask(() async {
      try {
        final repo = UserEventsRepo(Supabase.instance.client);
        if (isSaved) {
          // Keep events and flow row; just persist inactive state.
          await repo.upsertFlow(
            id: flow.id,
            name: flow.name,
            color: flow.color.toARGB32(),
            active: false,
            calendarId: flow.calendarId,
            startDate: flow.start,
            endDate: flow.end,
            notes: flow.notes,
            rules: jsonEncode(flow.rules.map(ruleToJson).toList()),
            isHidden: flow.isHidden,
            isSaved: flow.isSaved,
            shareId: flow.shareId,
            isReminder: flow.isReminder,
            reminderUuid: flow.reminderUuid,
          );
          if (kDebugMode) {
            _calendarDebugPrint(
              '[deleteFlow] Saved flow $flowId marked inactive, events retained',
            );
          }
        } else {
          await repo.deleteByFlowId(flowId);
          await repo.deleteFlow(flowId);
          await _requestHydration(
            _CalendarHydrationRequest.catalogReconcile(
              reason: 'flow_delete_succeeded',
            ),
          );
        }
      } catch (e, stackTrace) {
        if (kDebugMode) {
          _calendarDebugPrint(
            '[deleteFlow] ✗ Failed to delete flow $flowId: $e',
          );
          _calendarDebugPrint('[deleteFlow] Stack trace: $stackTrace');
        }
        // Resync local state to match server (restores flow if delete failed)
        await _requestHydration(
          _CalendarHydrationRequest.catalogReconcile(
            reason: 'flow_delete_failed_reconcile',
          ),
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Failed to delete flow. Please try again.'),
              action: SnackBarAction(
                label: 'Retry',
                onPressed: () => _deleteFlow(flowId),
              ),
              duration: const Duration(seconds: 4),
            ),
          );
        }
      }
    });
  }

  String _formatTimeOfDay(TimeOfDay t) {
    final h = t.hourOfPeriod == 0 ? 12 : t.hourOfPeriod;
    final m = t.minute.toString().padLeft(2, '0');
    final ap = t.period == DayPeriod.am ? 'AM' : 'PM';
    return '$h:$m $ap';
  }

  int _toMinutes(TimeOfDay t) => t.hour * 60 + t.minute;

  TimeOfDay _addMinutes(TimeOfDay t, int delta) {
    final m = (_toMinutes(t) + delta) % (24 * 60);
    return TimeOfDay(hour: (m ~/ 60), minute: m % 60);
  }

  String _timeRangeLabel({
    required bool allDay,
    TimeOfDay? start,
    TimeOfDay? end,
  }) {
    if (allDay) return 'All-day';
    String s(TimeOfDay t) => _formatTimeOfDay(t);
    if (start != null && end != null) return '${s(start)} – ${s(end)}';
    if (start != null) return s(start);
    if (end != null) return '… – ${s(end)}';
    return '';
  }

  String _calendarSheetEventTimeRangeLabel(EventItem event) {
    TimeOfDay? timeFromMinutes(int minutes) {
      if (minutes < 0) return null;
      return TimeOfDay(hour: minutes ~/ 60, minute: minutes % 60);
    }

    return _timeRangeLabel(
      allDay: event.allDay,
      start: event.allDay ? null : timeFromMinutes(event.startMin),
      end: event.allDay ? null : timeFromMinutes(event.endMin),
    );
  }

  /// Gregorian label for a Kemetic month/year (handles epagomenal spanning years).
  String _gregYearLabelFor(int kYear, int kMonth) {
    final lastDay = (kMonth == 13)
        ? (KemeticMath.isLeapKemeticYear(kYear) ? 6 : 5)
        : 30;
    final yStart = KemeticMath.toGregorian(kYear, kMonth, 1).year;
    final yEnd = KemeticMath.toGregorian(kYear, kMonth, lastDay).year;
    return (yStart == yEnd) ? '$yStart' : '$yStart/$yEnd';
  }

  String _monthLabel(int kMonth) => getMonthById(kMonth).displayFull;

  /* ───── TODAY snap/center ───── */

  void _scrollToToday({bool animate = true}) {
    unawaited(_scrollToTodayWithResolvedTarget(animate: animate));
  }

  Future<void> _scrollToTodayWithResolvedTarget({required bool animate}) async {
    if (_todayNavigationInFlight) return;
    _todayNavigationInFlight = true;
    final presentationTransaction =
        _beginCalendarTodayPresentationTransaction();
    try {
      final today = _today;
      final targetInterval = CalendarHydrationInterval.fromInclusiveLocalDays(
        firstLocalDay: KemeticMath.toGregorian(today.kYear, today.kMonth, 1),
        lastLocalDay: KemeticMath.toGregorian(
          today.kYear,
          today.kMonth,
          _maxDayForMonth(today.kYear, today.kMonth),
        ),
      );
      if (animate &&
          !_hydrationController.state.coverage.covers(targetInterval) &&
          Supabase.instance.client.auth.currentUser != null) {
        // Today is a local semantic navigation command. Target hydration may
        // improve the projection, but network availability must never gate or
        // absorb the tap. Any extent-changing result is staged by the active
        // presentation transaction and published at settle.
        unawaited(
          _requestHydration(
            _CalendarHydrationRequest.targeted(
              reason: 'today_target_spec',
              intentKind: CalendarHydrationIntentKind.affectedDate,
              interval: targetInterval,
            ),
          ),
        );
      }
      if (!mounted) return;
      await _travelToTodayInActiveEpoch(animate: animate);
    } finally {
      _settleCalendarTodayPresentationTransaction(presentationTransaction);
      _todayNavigationInFlight = false;
    }
  }

  void _centerMonth(int ky, int km) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;

      final targetCtx = keyForMonth(ky, km).currentContext;
      final targetPixels = _centeredScrollOffsetForContext(targetCtx);
      if (targetPixels == null || !_scrollCtrl.hasClients) return;
      _scrollCtrl.jumpTo(targetPixels);
    });
  }

  /* ───── AppBar actions (scroll + journal) ───── */

  MonthExpansionLevel _parseExpansion(String? raw) {
    switch (raw) {
      case 'stacked':
        return MonthExpansionLevel.stacked;
      case 'labeled':
        return MonthExpansionLevel.labeled;
      case 'details':
        return MonthExpansionLevel.details;
      case 'compact':
      default:
        return MonthExpansionLevel.compact;
    }
  }

  String _expansionToString(MonthExpansionLevel level) {
    switch (level) {
      case MonthExpansionLevel.compact:
        return 'compact';
      case MonthExpansionLevel.stacked:
        return 'stacked';
      case MonthExpansionLevel.labeled:
        return 'labeled';
      case MonthExpansionLevel.details:
        return 'details';
    }
  }

  Future<void> _persistExpansionLevel(MonthExpansionLevel level) async {
    if (!_rememberLastView) return;
    final state = _buildCalendarRestorationState().copyWith(
      expansion: _expansionToString(level),
    );
    await _persistCalendarRestorationState(state, reason: 'expansion_changed');
  }

  void _setExpansionLevelSmooth(
    MonthExpansionLevel level, {
    String entryPoint = 'pinch',
  }) {
    if (_monthExpansion == level && !_isPinching) return;
    _monthExpansionRestorationTarget = level;
    if (_isPinching && _pinchAnchorMonth != null && _pinchAnchorPoint != null) {
      setState(() => _monthExpansion = level);
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _maintainAnchorPoint();
        _monthExpansionRestorationTarget = null;
      });
    } else {
      final double? offset = _scrollCtrl.hasClients
          ? _scrollCtrl.position.pixels
          : null;

      setState(() => _monthExpansion = level);
      _monthExpansionRestorationTarget = null;

      if (!_isPinching) {
        _persistExpansionLevel(level);
        Events.trackIfAuthed('calendar_expansion_changed', {
          'level': _expansionToString(level),
          'entry_point': entryPoint,
        });
      }

      if (offset != null && _scrollCtrl.hasClients) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!_scrollCtrl.hasClients) return;
          final pos = _scrollCtrl.position;
          final target = offset.clamp(pos.minScrollExtent, pos.maxScrollExtent);
          pos.animateTo(
            target,
            duration: const Duration(milliseconds: 200),
            curve: Curves.easeOutCubic,
          );
        });
      }
    }
  }

  void _maintainAnchorPoint() {
    if (_pinchAnchorMonth == null || _pinchAnchorPoint == null) return;
    if (!_scrollCtrl.hasClients) return;

    final (anchorKy, anchorKm) = _pinchAnchorMonth!;
    final anchorScreenY = _pinchAnchorPoint!.dy;

    final box = context.findRenderObject() as RenderBox?;
    if (box == null) return;

    final monthCtx = keyForMonth(anchorKy, anchorKm).currentContext;
    if (monthCtx == null) return;

    final monthBox = monthCtx.findRenderObject();
    if (monthBox == null || monthBox is! RenderBox) return;

    final monthGlobalTop = monthBox.localToGlobal(Offset.zero);
    final boxGlobalTop = box.localToGlobal(Offset.zero);
    final currentScroll = _scrollCtrl.position.pixels;

    final monthTopInContent =
        monthGlobalTop.dy - boxGlobalTop.dy + currentScroll;

    final targetScroll = monthTopInContent + boxGlobalTop.dy - anchorScreenY;

    final pos = _scrollCtrl.position;
    final clamped = targetScroll.clamp(
      pos.minScrollExtent,
      pos.maxScrollExtent,
    );
    pos.jumpTo(clamped);
  }

  (int, int)? _findMonthAtPoint(Offset globalPoint) {
    if (!_scrollCtrl.hasClients) return null;

    final box = context.findRenderObject() as RenderBox?;
    if (box == null) return null;

    final localPoint = box.globalToLocal(globalPoint);

    final baseKy = _lastViewKy ?? _today.kYear;
    final baseKm = _lastViewKm ?? _today.kMonth;

    for (int dy = -2; dy <= 2; dy++) {
      final ky = baseKy + dy;
      for (int km = 1; km <= 13; km++) {
        final ctx = keyForMonth(ky, km).currentContext;
        if (ctx == null) continue;

        final ro = ctx.findRenderObject();
        if (ro == null || ro is! RenderBox) continue;

        final monthBox = ro;
        final monthTop = monthBox.localToGlobal(Offset.zero).dy;
        final monthBottom = monthTop + monthBox.size.height;
        final screenY = box.localToGlobal(localPoint).dy;

        if (screenY >= monthTop && screenY <= monthBottom) {
          return (ky, km);
        }
      }
    }

    return (baseKy, baseKm);
  }

  void _onScaleStart(ScaleStartDetails details) {
    if (details.pointerCount < 2) return;
    _monthExpansionRestorationTarget = null;
    _scaleGestureAnchor = 1.0;
    _isPinching = true;
    _lastPinchUpdate = null;
    _pinchStartLevel = _monthExpansion;
    _pinchExpansionValue = _monthExpansion.index.toDouble();
    _pinchAnchorPoint = details.focalPoint;
    _pinchAnchorMonth = _findMonthAtPoint(details.focalPoint);
  }

  void _onScaleUpdate(ScaleUpdateDetails details) {
    if (_scaleGestureAnchor == null || details.pointerCount < 2) return;

    final now = DateTime.now();
    if (_lastPinchUpdate != null &&
        now.difference(_lastPinchUpdate!) < _pinchUpdateThrottle) {
      return;
    }
    _lastPinchUpdate = now;

    final scaleDelta = details.scale - _scaleGestureAnchor!;
    const scaleSensitivity = 0.15;
    final expansionDelta = scaleDelta / scaleSensitivity;
    final maxExpansionIndex = MonthExpansionLevel.values.length - 1;
    final newValue = (_pinchExpansionValue + expansionDelta).clamp(
      0.0,
      maxExpansionIndex.toDouble(),
    );

    if ((newValue - _pinchExpansionValue).abs() > 0.05) {
      _pinchExpansionValue = newValue;
      _scaleGestureAnchor = details.scale;

      final nearestLevel = _pinchExpansionValue.round().clamp(
        0,
        maxExpansionIndex,
      );
      final targetLevel = MonthExpansionLevel.values[nearestLevel];
      if (targetLevel != _monthExpansion) {
        _setExpansionLevelSmooth(targetLevel, entryPoint: 'pinch');
      }
    }
  }

  void _onScaleEnd(ScaleEndDetails details) {
    if (_scaleGestureAnchor == null && !_isPinching) return;

    final startLevel = _pinchStartLevel ?? _monthExpansion;
    final maxExpansionIndex = MonthExpansionLevel.values.length - 1;
    final nearestLevel = _pinchExpansionValue.round().clamp(
      0,
      maxExpansionIndex,
    );
    final targetLevel = MonthExpansionLevel.values[nearestLevel];
    _setExpansionLevelSmooth(targetLevel, entryPoint: 'pinch');
    _pinchExpansionValue = targetLevel.index.toDouble();
    _lastPinchUpdate = null;
    _isPinching = false;
    _scaleGestureAnchor = null;

    if (_pinchAnchorMonth != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _maintainAnchorPoint();
        _pinchAnchorPoint = null;
        _pinchAnchorMonth = null;
      });
    }

    if (targetLevel != startLevel) {
      _persistExpansionLevel(targetLevel);
      Events.trackIfAuthed('calendar_expansion_changed', {
        'level': _expansionToString(targetLevel),
        'entry_point': 'pinch',
      });
    }

    _pinchStartLevel = null;
  }

  Color _noteColor(_Note note) {
    if (note.manualColor != null) return note.manualColor!;
    if (note.flowId != null && note.flowId != -1) {
      try {
        final flow = _flows.firstWhere((f) => f.id == note.flowId);
        return _displayFlowColor(flow.name, flow.color);
      } catch (_) {}
    }
    if (note.isReminder) return _blue;
    return _silver;
  }

  String? _flowName(_Note note) {
    if (note.flowId != null && note.flowId != -1) {
      try {
        final flow = _flows.firstWhere((f) => f.id == note.flowId);
        return flow.name;
      } catch (_) {}
    }
    return null;
  }

