  Widget _buildFlowStudioHubPageCore(
    BuildContext innerCtx, {
    VoidCallback? onClose,
    bool persistOverlay = true,
    bool embeddedInDaySheet = false,
  }) {
    return _FlowHubPage(
      onClose: onClose,
      embeddedInDaySheet: embeddedInDaySheet,
      filingSnapshotProvider: _cachedMyFlowsFilingSnapshot,
      loadFilingSnapshot: _loadMyFlowsFilingSnapshot,
      openMyFlows: () {
        unawaited(
          _pushFlowStudioRoute<void>(
            Navigator.of(innerCtx),
            MaterialPageRoute<void>(
              builder: (ctx2) => _FlowsViewerPage(
                loadFilingSnapshot: _loadMyFlowsFilingSnapshot,
                initialFilingSnapshot: _cachedMyFlowsFilingSnapshot(),
                fmtGregorian: (d) => d == null
                    ? '--'
                    : '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}',
                onCreateNew: () async {
                  final edited = await _pushFlowStudioEditor(
                    Navigator.of(innerCtx),
                    returnState: const <String, dynamic>{
                      'mode': _kFlowStudioModeMyFlows,
                    },
                    persistOverlay: persistOverlay,
                  );
                  await _persistReturnedFlowStudioResult(edited);
                },
                onEditFlow: (id) async {
                  final edited = await _pushFlowStudioEditor(
                    Navigator.of(innerCtx),
                    editFlowId: id,
                    returnState: const <String, dynamic>{
                      'mode': _kFlowStudioModeMyFlows,
                    },
                    persistOverlay: persistOverlay,
                  );
                  await _persistReturnedFlowStudioResult(edited);
                },
                onEndFlow: (id) => _endFlow(id),
                completeAdd: _completeMountedStagedFlowAddWithDayView,
                onImportFlow: (importedFlowId) async {
                  if (importedFlowId != null) {
                    await _requestHydration(
                      _CalendarHydrationRequest.catalogReconcile(
                        reason: 'my_flows_imported',
                      ),
                    );
                  }
                },
                onAppendToJournal: _appendToJournalAndRefresh,
              ),
            ),
            visibleState: const <String, dynamic>{
              'mode': _kFlowStudioModeMyFlows,
            },
            returnState: const <String, dynamic>{'mode': _kFlowStudioModeHub},
            persistOverlay: persistOverlay,
          ),
        );
      },
      openMaatFlows: () {
        unawaited(() async {
          await _requestHydration(
            _CalendarHydrationRequest.catalogReconcile(
              reason: 'open_maat_flows',
            ),
          );
          if (!innerCtx.mounted) return;
          final importedFlowId = await _pushFlowStudioRoute<int?>(
            Navigator.of(innerCtx),
            MaterialPageRoute<int?>(
              builder: (ctx3) =>
                  _buildMaatFlowsListPage(ctx3, persistOverlay: persistOverlay),
            ),
            visibleState: const <String, dynamic>{
              'mode': _kFlowStudioModeMaatFlows,
            },
            returnState: const <String, dynamic>{'mode': _kFlowStudioModeHub},
            persistOverlay: persistOverlay,
          );
          if (importedFlowId == null || importedFlowId <= 0) return;
          // List already snackbars when chronological first note is missing.
          if (_firstChronologicalNoteForFlow(importedFlowId) == null) return;
          // Close hub + Flow Studio sheet, then open Day View on first day.
          if (innerCtx.mounted) {
            final rootNavigator = Navigator.of(innerCtx, rootNavigator: true);
            if (rootNavigator.canPop()) {
              rootNavigator.pop();
            }
          }
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (!mounted) return;
            _openDayViewForStagedFlow(importedFlowId);
          });
        }());
      },
      onCreateNew: () async {
        final edited = await _pushFlowStudioEditor(
          Navigator.of(innerCtx),
          returnState: const <String, dynamic>{'mode': _kFlowStudioModeHub},
          persistOverlay: persistOverlay,
        );
        if (edited != null) await _persistFlowStudioResult(edited);
      },
    );
  }

  // Manage Flows callback: jump straight to My Flows (or specific flow editor if id provided).
  void Function(int? flowId) _getMyFlowsCallback() {
    return (int? flowId) {
      if (flowId != null) {
        if (kIsWeb) {
          unawaited(
            CalendarPage.openFlowEditorFromAnyContext(
              context,
              flowId: flowId,
              fallbackLocation: '/',
              source: 'calendar_detail',
            ),
          );
          return;
        }
        // Open the existing Flow editor directly when a flowId is provided.
        _openFlowEditorDirectly(flowId);
        return;
      }
      _openMyFlowsList();
    };
  }

  // Flow Studio callback that opens the Flow Hub (same as main calendar)
  void Function(int? flowId) _getFlowStudioCallback() {
    return (int? flowId) {
      // If flowId provided, go directly to that flow
      if (flowId != null) {
        if (kIsWeb) {
          unawaited(
            CalendarPage.openFlowEditorFromAnyContext(
              context,
              flowId: flowId,
              fallbackLocation: '/',
              source: 'flow_studio_callback',
            ),
          );
          return;
        }
        _openFlowEditorDirectly(flowId);
        return;
      }

      // The hub now lives in the unified Notes / Reminders / Flows sheet.
      _openDaySheet(
        _today.kYear,
        _today.kMonth,
        _today.kDay,
        allowDateChange: true,
        initialTab: DaySheetTab.flows,
      );
    };
  }

