  void _openDaySheetFlowDetail(int flowId) {
    _openFlowStudioSheet(
      continuityState: <String, dynamic>{
        'mode': _kFlowStudioModeMyFlows,
        'initialFlowId': flowId,
        'source': 'day_sheet_flow_detail',
      },
      showCloseButton: true,
      rootBuilder: (innerCtx) {
        final sourceSnapshot = _cachedMyFlowsFilingSnapshot();
        final snapshot = sourceSnapshot == null
            ? null
            : CalendarPage._applyEndFlowVisibilityOverlay(sourceSnapshot);
        final snapshotFlows = snapshot?.flows ?? const <_Flow>[];
        final sourceFlows = snapshotFlows.isNotEmpty ? snapshotFlows : _flows;
        final activeIds =
            snapshot?.activeFlowIds ??
            <int>{
              for (final flow in _flows)
                if (!CalendarPage._isFlowEndSuppressed(flow.id) &&
                    flow.active &&
                    !flow.isHidden &&
                    !flow.isReminder)
                  flow.id,
            };
        final activeItems =
            sourceFlows.where((flow) => activeIds.contains(flow.id)).toList()
              ..sort(
                (a, b) => a.name.toLowerCase().compareTo(b.name.toLowerCase()),
              );
        final fallbackIndex = sourceFlows.indexWhere(
          (flow) => flow.id == flowId,
        );
        final activeIndex = activeItems.indexWhere((flow) => flow.id == flowId);
        final flow = activeIndex >= 0
            ? activeItems[activeIndex]
            : (fallbackIndex >= 0 ? sourceFlows[fallbackIndex] : null);

        if (flow == null) {
          return const Scaffold(
            backgroundColor: MaatFlowListTokens.pageBg,
            body: Center(
              child: Text(
                'Flow unavailable',
                style: TextStyle(color: DaySheetTokens.silverHi),
              ),
            ),
          );
        }

        final sequence = activeItems.any((item) => item.id == flowId)
            ? activeItems
            : <_Flow>[flow];
        final initialIndex = sequence.indexWhere((item) => item.id == flowId);
        final metricsByFlow = snapshot == null
            ? const <int, _FlowPreviewMetrics>{}
            : <int, _FlowPreviewMetrics>{
                for (final item in sequence)
                  item.id: _FlowPreviewMetrics.fromSnapshot(
                    flow: item,
                    snapshot: snapshot,
                  ),
              };
        final initialEventsByFlow = _debugDaySheetSmokeEnabled
            ? _daySheetFlowDetailEventsByFlow(sequence)
            : null;

        return _FlowPreviewPage(
          flow: flow,
          flowSequence: sequence,
          initialIndex: initialIndex < 0 ? 0 : initialIndex,
          mode: _FlowPreviewMode.active,
          metricsByFlow: metricsByFlow,
          initialEventsByFlow: initialEventsByFlow?.isEmpty == true
              ? null
              : initialEventsByFlow,
          getDecanLabel: (km, di) =>
              (DecanMetadata.decanNames[km] ?? const ['I', 'II', 'III'])[di],
          fmt: (d) => d == null
              ? '--'
              : '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}',
          onEdit: (flow) {
            unawaited(() async {
              final edited = await _pushFlowStudioEditor(
                Navigator.of(innerCtx),
                editFlowId: flow.id,
                returnState: const <String, dynamic>{
                  'mode': _kFlowStudioModeMyFlows,
                },
              );
              await _saveCalendarOverlayState(
                _kCalendarOverlayKindFlowStudio,
                const <String, dynamic>{'mode': _kFlowStudioModeMyFlows},
              );
              if (edited != null) await _persistFlowStudioResult(edited);
              await _requestHydration(
                _CalendarHydrationRequest.catalogReconcile(
                  reason: 'flow_editor_returned',
                ),
              );
            }());
          },
          completeAdd: _completeMountedStagedFlowAddWithDayView,
          onAppendToJournal: _appendToJournalAndRefresh,
          onEndMaatFlow: (flow) async {
            final result = await _endFlow(flow.id);
            if (result.result != EndFlowActionResult.success &&
                innerCtx.mounted) {
              ScaffoldMessenger.of(innerCtx).showSnackBar(
                SnackBar(
                  content: Text(endFlowFailureDisplayMessage(result)),
                  action: SnackBarAction(
                    label: 'Copy diagnostics',
                    onPressed: () => unawaited(
                      EndFlowDiagnostics.instance.copyTerminalDiagnostics(
                        result.operationId,
                      ),
                    ),
                  ),
                ),
              );
            }
            return result;
          },
        );
      },
    );
  }

  Map<int, List<FlowEventRow>> _daySheetFlowDetailEventsByFlow(
    Iterable<_Flow> flows,
  ) {
    final targetIds = <int>{
      for (final flow in flows)
        if (flow.id > 0) flow.id,
    };
    if (targetIds.isEmpty) return const <int, List<FlowEventRow>>{};

    final eventsByFlow = <int, List<FlowEventRow>>{};
    for (final entry in _notes.entries) {
      final dayStart = _gregorianDayStartFromKey(entry.key);
      if (dayStart == null) continue;
      for (final note in entry.value) {
        final flowId = note.flowId;
        if (flowId == null || !targetIds.contains(flowId)) continue;
        eventsByFlow
            .putIfAbsent(flowId, () => <FlowEventRow>[])
            .add(_flowEventRowFromDaySheetNote(note, dayStart));
      }
    }

    for (final entry in eventsByFlow.entries) {
      entry.value.sort((a, b) => a.startsAtUtc.compareTo(b.startsAtUtc));
    }
    return eventsByFlow;
  }

  DateTime? _gregorianDayStartFromKey(String key) {
    final parts = key.split('-');
    if (parts.length != 3) return null;
    final kYear = int.tryParse(parts[0]);
    final kMonth = int.tryParse(parts[1]);
    final kDay = int.tryParse(parts[2]);
    if (kYear == null || kMonth == null || kDay == null) return null;
    try {
      return DateUtils.dateOnly(KemeticMath.toGregorian(kYear, kMonth, kDay));
    } catch (_) {
      return null;
    }
  }

  FlowEventRow _flowEventRowFromDaySheetNote(_Note note, DateTime dayStart) {
    final start = note.allDay
        ? dayStart
        : DateTime(
            dayStart.year,
            dayStart.month,
            dayStart.day,
            note.start?.hour ?? 9,
            note.start?.minute ?? 0,
          );
    DateTime? end;
    if (!note.allDay) {
      final rawEnd = note.end == null
          ? start.add(const Duration(minutes: 30))
          : DateTime(
              dayStart.year,
              dayStart.month,
              dayStart.day,
              note.end!.hour,
              note.end!.minute,
            );
      end = rawEnd.isAfter(start)
          ? rawEnd
          : rawEnd.add(const Duration(days: 1));
    }
    final calendar = _calendarSummary(note.calendarId);

    return (
      id: note.id,
      clientEventId: note.clientEventId,
      calendarId: note.calendarId,
      calendarName: note.calendarName ?? calendar?.name,
      calendarColor: (note.manualColor ?? calendar?.color)?.toARGB32(),
      calendarIsPersonal: calendar?.isPersonal ?? true,
      title: note.title,
      detail: note.detail,
      location: note.location,
      allDay: note.allDay,
      startsAtUtc: start.toUtc(),
      endsAtUtc: end?.toUtc(),
      flowLocalId: note.flowId,
      category: note.category,
      actionId: note.actionId,
      behaviorPayload: note.behaviorPayload,
    );
  }

  /* ─────────── Ma’at Flows helpers ─────────── */

  /// True if there is at least one *active* instance of template [tplKey]
  /// with any remaining day today or in the future.
  bool _hasActiveMaatInstanceFor(String tplKey) {
    if (CalendarPage._hasRememberedJoinedMaatTemplate(tplKey)) return true;
    final snapshot = _cachedMyFlowsFilingSnapshot();
    if (snapshot != null) {
      return CalendarPage._snapshotHasActiveMaatInstanceFor(snapshot, tplKey);
    }
    return _flows.any((f) {
      return !CalendarPage._isFlowEndSuppressed(f.id) &&
          CalendarPage._flowMatchesActiveMaatTemplate(f, tplKey);
    });
  }

  _MaatFlowCompletionStatus? _maatCompletionStatusForActiveInstance(
    String tplKey,
  ) {
    for (final flow in _flows) {
      if (CalendarPage._isFlowEndSuppressed(flow.id)) continue;
      if (!CalendarPage._flowMatchesActiveMaatTemplate(flow, tplKey)) {
        continue;
      }
      return CalendarPage._maatCompletionStatusFromCounts(
        totalEventCount: _flowTotalEventCounts[flow.id] ?? 0,
        remainingEventCount: _flowRemainingEventCounts[flow.id] ?? 0,
      );
    }
    return null;
  }

  /// Create a user-owned *instance* from a Ma'at template starting on [startDate].
  /// - Sequence templates use [startDate] and optionally [useKemetic].
  /// - Ongoing templates can use their own join settings, such as timezone.
  /// - Returns the created flow's id.
  Future<int> _addMaatFlowInstance({
    required _MaatFlowTemplate template,
    bool completionRequired = true,
    DateTime? startDate,
    bool useKemetic = false,
    TrackSkyTimeZone? trackSkyTimeZone,
    int alertMinutesBefore = _alertNoneMinutes,
    bool dawnDiscreetMode = false,
    DawnHouseRiteLens dawnLens = DawnHouseRiteLens.neutral,
    bool eveningDiscreetMode = false,
    EveningThresholdRiteLens eveningLens = EveningThresholdRiteLens.neutral,
    int eveningFallbackMinutesAfterMidnight =
        kEveningThresholdDefaultFallbackMinutes,
    TheWeighingLens theWeighingLens = TheWeighingLens.neutral,
    OfferingTableLens offeringTableLens = OfferingTableLens.neutral,
    bool offeringNoCupMode = false,
    TheTendingLens theTendingLens = TheTendingLens.neutral,
    KeptWordLens keptWordLens = KeptWordLens.neutral,
    CourseLens courseLens = CourseLens.neutral,
    MoonReturnLens moonReturnLens = MoonReturnLens.neutral,
    WagLens wagLens = WagLens.neutral,
    DecanWatchLens decanWatchLens = DecanWatchLens.neutral,
    OpenHandLens openHandLens = OpenHandLens.neutral,
    DjedLens djedLens = DjedLens.neutral,
    List<ReadingHouseSitting>? readingHouseSittings,
    String? eveningThresholdInitialCarry,
  }) async {
    final flowId = await CalendarPage._addMaatFlowInstanceHeadless(
      template: template,
      completionRequired: completionRequired,
      personalCalendarIdOverride: _personalCalendarId,
      startDate: startDate,
      useKemetic: useKemetic,
      trackSkyTimeZone: trackSkyTimeZone,
      alertMinutesBefore: alertMinutesBefore,
      dawnDiscreetMode: dawnDiscreetMode,
      dawnLens: dawnLens,
      eveningDiscreetMode: eveningDiscreetMode,
      eveningLens: eveningLens,
      eveningFallbackMinutesAfterMidnight: eveningFallbackMinutesAfterMidnight,
      theWeighingLens: theWeighingLens,
      offeringTableLens: offeringTableLens,
      offeringNoCupMode: offeringNoCupMode,
      theTendingLens: theTendingLens,
      keptWordLens: keptWordLens,
      courseLens: courseLens,
      moonReturnLens: moonReturnLens,
      wagLens: wagLens,
      decanWatchLens: decanWatchLens,
      openHandLens: openHandLens,
      djedLens: djedLens,
      readingHouseSittings: readingHouseSittings,
      eveningThresholdInitialCarry: eveningThresholdInitialCarry,
    );
    if (flowId <= 0) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not create ${template.title}.')),
        );
      }
      return -1;
    }
    _applyPendingStagedFlow(flowId);
    return flowId;
  }

  /// End Flow removes the current user's local calendar copy of the flow by
  /// deleting every matched materialized row from that calendar in the
  /// canonical RPC. Previously shared, posted, or saved copies live in their
  /// own records and are not removed by this action.
  //// === FLOW LIFECYCLE: END FLOW ===
  _MountedFlowEndPatch _optimisticallyPatchEndedFlow(int flowId) {
    final flowIndex = _flows.indexWhere((flow) => flow.id == flowId);
    final existingFlow = flowIndex < 0 ? null : _flows[flowIndex];
    final flowSnapshot = existingFlow == null
        ? null
        : _Flow(
            id: existingFlow.id,
            calendarId: existingFlow.calendarId,
            name: existingFlow.name,
            color: existingFlow.color,
            active: existingFlow.active,
            isSaved: existingFlow.isSaved,
            savedAt: existingFlow.savedAt,
            rules: List<FlowRule>.from(existingFlow.rules),
            start: existingFlow.start,
            end: existingFlow.end,
            notes: existingFlow.notes,
            shareId: existingFlow.shareId,
            isHidden: existingFlow.isHidden,
            isReminder: existingFlow.isReminder,
            reminderUuid: existingFlow.reminderUuid,
          );
    final removed = _removeCalendarNotesWhere(
      (_, note) => note.flowId == flowId,
    );
    final unconfirmedNotes = _unconfirmed.takeCids(removed.clientEventIds);

    if (existingFlow != null) {
      if (existingFlow.isSaved) {
        existingFlow.active = false;
      } else {
        _flows.removeAt(flowIndex);
      }
    }

    final patch = _MountedFlowEndPatch(
      flow: flowSnapshot,
      flowIndex: flowIndex,
      notesByDay: removed.notesByDay,
      hadTotalCount: _flowTotalEventCounts.containsKey(flowId),
      totalCount: _flowTotalEventCounts[flowId],
      hadRemainingCount: _flowRemainingEventCounts.containsKey(flowId),
      remainingCount: _flowRemainingEventCounts[flowId],
      unconfirmedNotes: unconfirmedNotes,
    );
    _flowTotalEventCounts[flowId] = 0;
    _flowRemainingEventCounts[flowId] = 0;
    if (mounted) {
      setState(() {});
      _notifyDayViewDataChanged();
    }
    return patch;
  }

  void _rollbackOptimisticEndedFlow(int flowId, _MountedFlowEndPatch patch) {
    final flow = patch.flow;
    if (flow != null) {
      final currentIndex = _flows.indexWhere((item) => item.id == flowId);
      if (currentIndex >= 0) {
        _flows[currentIndex] = flow;
      } else {
        final insertAt = patch.flowIndex.clamp(0, _flows.length).toInt();
        _flows.insert(insertAt, flow);
      }
    }

    _publishCalendarNoteMutation(
      upserts: <CalendarPendingVisibleItem<_Note>>[
        for (final entry in patch.notesByDay.entries)
          for (final note in entry.value)
            CalendarPendingVisibleItem<_Note>(dayKey: entry.key, item: note),
      ],
    );
    _unconfirmed.restore(patch.unconfirmedNotes);

    if (patch.hadTotalCount) {
      _flowTotalEventCounts[flowId] = patch.totalCount ?? 0;
    } else {
      _flowTotalEventCounts.remove(flowId);
    }
    if (patch.hadRemainingCount) {
      _flowRemainingEventCounts[flowId] = patch.remainingCount ?? 0;
    } else {
      _flowRemainingEventCounts.remove(flowId);
    }
    _myFlowsFilingSnapshotCache = null;
    if (mounted) {
      setState(() {});
      _notifyDayViewDataChanged();
    }
  }

  Future<bool> _makeTodoFromEventTarget(DayViewSheetEventTarget target) async {
    final event = target.event;
    final flow = _calendarChromeFlowDataForId(event.flowId);
    final eventDate = KemeticMath.toGregorian(target.ky, target.km, target.kd);
    final dueDate = DateTime(eventDate.year, eventDate.month, eventDate.day);
    final dueTime = event.allDay ? null : _timeOfDayFromMinute(event.startMin);
    final source = EventTodoSource(
      title: event.title,
      detail: event.detail,
      location: event.location,
      flowName: flow?.name,
      isFlow: event.flowId != null && !event.isReminder,
      isReminder: event.isReminder,
    );
    final sourceMetadata = <String, dynamic>{
      'source': 'calendar_event_make_todo',
      'source_title': event.title,
      'source_kemetic_date': '${target.ky}-${target.km}-${target.kd}',
      if (event.id?.trim().isNotEmpty == true) 'event_id': event.id!.trim(),
      if (event.clientEventId?.trim().isNotEmpty == true)
        'client_event_id': event.clientEventId!.trim(),
      if (event.flowId != null) 'flow_id': event.flowId,
      if (flow?.name.trim().isNotEmpty == true) 'flow_name': flow!.name.trim(),
      if (event.reminderId?.trim().isNotEmpty == true)
        'reminder_id': event.reminderId!.trim(),
      if (event.isReminder) 'is_reminder': true,
    };
    final result = await makeEventTodos(
      source: source,
      dueDate: dueDate,
      dueTime: dueTime,
      metadata: sourceMetadata,
      insertTodos: _rhythmRepo.insertTodos,
    );
    if (!mounted) return false;
    if (!result.success || result.plannerLocation == null) {
      _showMakeTodoError(result.errorMessage ?? 'Could not add to-do.');
      return false;
    }
    await _openPlannerTodoList(result.plannerLocation!);
    return true;
  }

  TimeOfDay _timeOfDayFromMinute(int minuteOfDay) {
    final clamped = minuteOfDay.clamp(0, 23 * 60 + 59).toInt();
    return TimeOfDay(hour: clamped ~/ 60, minute: clamped % 60);
  }

  void _showMakeTodoError(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(SnackBar(content: Text(message)));
  }

  Future<void> _openPlannerTodoList(String location) async {
    if (!mounted) return;
    await openUtilityRoute<void>(context, location);
  }

  Future<EndFlowOutcome> _endFlow(int flowId, {DateTime? endedAtLocal}) {
    final existing = _mountedEndFlowOperations[flowId];
    if (existing != null) return existing;

    late final Future<EndFlowOutcome> operation;
    operation = _performEndFlow(flowId, endedAtLocal: endedAtLocal)
        .whenComplete(() {
          if (identical(_mountedEndFlowOperations[flowId], operation)) {
            _mountedEndFlowOperations.remove(flowId);
          }
        });
    _mountedEndFlowOperations[flowId] = operation;
    return operation;
  }

  Future<EndFlowOutcome> _performEndFlow(
    int flowId, {
    DateTime? endedAtLocal,
  }) async {
    final effectiveEndedAtLocal = endedAtLocal ?? DateTime.now();
    if (kDebugMode) {
      _calendarDebugPrint(
        '[endFlow] flowId=$flowId endedAtLocal='
        '${effectiveEndedAtLocal.toIso8601String()}',
      );
    }

    final remoteOperation = CalendarPage._runEndFlowRemote(
      flowId,
      endedAtLocal: effectiveEndedAtLocal,
      initiatorOwner: EndFlowOperationOwner.calendar,
    );
    final optimisticPatch = _optimisticallyPatchEndedFlow(flowId);
    final result = await remoteOperation;
    if (result.result != EndFlowActionResult.success) {
      _rollbackOptimisticEndedFlow(flowId, optimisticPatch);
      return result;
    }
    return result;
  }
