                        const SizedBox(height: 12),

                        DaySheetSpectrumColorPicker(
                          selectedColor: selectedColor,
                          onChanged: (color) {
                            setSheetState(() {
                              selectedColor = color;
                            });
                            persistDaySheetSession();
                          },
                        ),

                        const SizedBox(height: 12),
                        Align(
                          alignment: Alignment.centerRight,
                          child: DaySheetSaveButton(
                            label: 'Save',
                            accent: selectedColor,
                            onPressed: () async {
                              final t = controllerTitle.text.trim();
                              final loc = controllerLocation.text.trim();
                              final d = controllerDetail.text.trim();
                              String detailForSave = d;
                              if (initialCidMetadata.isNotEmpty) {
                                if (editingIndex != null &&
                                    d == strippedInitialDetail) {
                                  // Preserve original metadata if the user didn't change the text.
                                  detailForSave = rawInitialDetail;
                                } else {
                                  detailForSave = _appendCidMetadata(
                                    d,
                                    initialCidMetadata,
                                  );
                                }
                              }

                              if (t.isEmpty) return;

                              // Validate end time is after start time
                              if (!allDay &&
                                  startTime != null &&
                                  endTime != null) {
                                if (_toMinutes(endTime!) <=
                                    _toMinutes(startTime!)) {
                                  endTime = _addMinutes(startTime!, 60);
                                }
                              }

                              final bool isRepeating =
                                  repeatOption != NoteRepeatOption.never;

                              final bucketKey = _kKey(
                                sourceEditingKYear,
                                sourceEditingKMonth,
                                sourceEditingKDay,
                              );
                              final editIndex = editingIndex;
                              final existingNote = editIndex != null
                                  ? (_notes[bucketKey] != null &&
                                            editIndex <
                                                _notes[bucketKey]!.length
                                        ? _notes[bucketKey]![editIndex]
                                        : null)
                                  : null;
                              final existingClientEventId =
                                  existingNote?.clientEventId ??
                                  (existingNote != null &&
                                          (existingNote.flowId == null ||
                                              existingNote.flowId == -1)
                                      ? _buildCid(
                                          ky: sourceEditingKYear,
                                          km: sourceEditingKMonth,
                                          kd: sourceEditingKDay,
                                          title: existingNote.title,
                                          startHour: existingNote.start?.hour,
                                          startMinute:
                                              existingNote.start?.minute,
                                          allDay: existingNote.allDay,
                                          flowId: -1,
                                          calendarScopeToken:
                                              _calendarScopeToken(
                                                existingNote.calendarId,
                                              ),
                                        )
                                      : null);

                              try {
                                ({String clientEventId, String eventId})?
                                saveResult;
                                var updatedExistingStandalone = false;
                                var handledRepeatingEdit = false;

                                if (selectedCalendar != null &&
                                    !selectedCalendar.canEdit) {
                                  ScaffoldMessenger.of(context).showSnackBar(
                                    const SnackBar(
                                      content: Text(
                                        'You can view this calendar, but you cannot edit it.',
                                      ),
                                    ),
                                  );
                                  return;
                                }

                                final editingRepeatingFlow =
                                    _repeatingNoteFlowForId(
                                      existingNote?.flowId,
                                    );
                                if (editingRepeatingFlow != null &&
                                    existingNote != null) {
                                  final scope =
                                      await _showRepeatingEventScopeSheet(
                                        context: sheetCtx,
                                        isDelete: false,
                                      );
                                  if (scope == null) return;
                                  await _applyRepeatingNoteEditScope(
                                    originalNote: existingNote,
                                    sourceKYear: sourceEditingKYear,
                                    sourceKMonth: sourceEditingKMonth,
                                    sourceKDay: sourceEditingKDay,
                                    selYear: selYear,
                                    selMonth: selMonth,
                                    selDay: selDay,
                                    title: t,
                                    detail: detailForSave.isEmpty
                                        ? null
                                        : detailForSave,
                                    location: loc.isEmpty ? null : loc,
                                    calendarId: selectedCalendarId,
                                    calendarName: selectedCalendarLabel,
                                    allDay: allDay,
                                    startTime: startTime,
                                    endTime: endTime,
                                    color: selectedColor,
                                    category: selectedCategory,
                                    alertMinutesBefore: alertMinutesBefore,
                                    scope: scope,
                                  );
                                  handledRepeatingEdit = true;
                                } else if (!isRepeating) {
                                  final canUpdateExisting =
                                      existingNote?.id != null &&
                                      ((existingNote?.flowId == null) ||
                                          existingNote?.flowId == -1);
                                  if (canUpdateExisting) {
                                    updatedExistingStandalone = true;
                                    saveResult = await _updateSingleNoteOnly(
                                      existingEventId: existingNote!.id!,
                                      previousClientEventId:
                                          existingClientEventId,
                                      selYear: selYear,
                                      selMonth: selMonth,
                                      selDay: selDay,
                                      title: t,
                                      detail: detailForSave.isEmpty
                                          ? null
                                          : detailForSave,
                                      location: loc.isEmpty ? null : loc,
                                      calendarId: selectedCalendarId,
                                      calendarName: selectedCalendarLabel,
                                      allDay: allDay,
                                      startTime: startTime,
                                      endTime: endTime,
                                      color: selectedColor,
                                      category: selectedCategory,
                                      alertMinutesBefore: alertMinutesBefore,
                                    );
                                  } else {
                                    final save = beginOptimisticNoteEditorSave(
                                      startSave: () => _saveSingleNoteOnly(
                                        selYear: selYear,
                                        selMonth: selMonth,
                                        selDay: selDay,
                                        title: t,
                                        detail: detailForSave.isEmpty
                                            ? null
                                            : detailForSave,
                                        location: loc.isEmpty ? null : loc,
                                        calendarId: selectedCalendarId,
                                        calendarName: selectedCalendarLabel,
                                        allDay: allDay,
                                        startTime: startTime,
                                        endTime: endTime,
                                        color: selectedColor,
                                        category: selectedCategory,
                                        alertMinutesBefore: alertMinutesBefore,
                                      ),
                                      closeEditor: () {
                                        if (sheetCtx.mounted) {
                                          Navigator.pop(sheetCtx);
                                        }
                                      },
                                    );
                                    _observeOptimisticNoteSave(save);
                                    return;
                                  }
                                } else {
                                  // Repeating note - create hidden flow
                                  await _saveRepeatingNoteAsHiddenFlow(
                                    selYear: selYear,
                                    selMonth: selMonth,
                                    selDay: selDay,
                                    title: t,
                                    detail: detailForSave.isEmpty
                                        ? null
                                        : detailForSave,
                                    location: loc.isEmpty ? null : loc,
                                    calendarId: selectedCalendarId,
                                    calendarName: selectedCalendarLabel,
                                    allDay: allDay,
                                    startTime: startTime,
                                    endTime: endTime,
                                    repeatOption: repeatOption,
                                    customFrequency: customFrequency,
                                    customInterval: customInterval,
                                    endType: endType,
                                    endDate: endDate,
                                    endCount: endCount,
                                    color: selectedColor,
                                    category: selectedCategory,
                                    alertMinutesBefore: alertMinutesBefore,
                                  );
                                }

                                if (!handledRepeatingEdit &&
                                    editIndex != null &&
                                    existingNote != null) {
                                  if (updatedExistingStandalone) {
                                    _removeLocalNoteOnly(
                                      sourceEditingKYear,
                                      sourceEditingKMonth,
                                      sourceEditingKDay,
                                      editIndex,
                                    );
                                  } else {
                                    final cidMatches =
                                        !isRepeating &&
                                        existingClientEventId != null &&
                                        saveResult != null &&
                                        existingClientEventId ==
                                            saveResult.clientEventId;
                                    if (cidMatches) {
                                      _removeLocalNoteOnly(
                                        sourceEditingKYear,
                                        sourceEditingKMonth,
                                        sourceEditingKDay,
                                        editIndex,
                                      );
                                    } else {
                                      await _deleteNote(
                                        sourceEditingKYear,
                                        sourceEditingKMonth,
                                        sourceEditingKDay,
                                        editIndex,
                                      );
                                    }
                                  }
                                }
                              } catch (e, stackTrace) {
                                if (kDebugMode) {
                                  _calendarDebugPrint(
                                    '[SaveNote] Error saving note: $e',
                                  );
                                  _calendarDebugPrint(
                                    '[SaveNote] Stack trace: $stackTrace',
                                  );
                                }
                                if (mounted) {
                                  ScaffoldMessenger.of(context).showSnackBar(
                                    SnackBar(
                                      content: Text('Failed to save note: $e'),
                                      backgroundColor: Colors.red,
                                      duration: const Duration(seconds: 3),
                                    ),
                                  );
                                }
                                return; // Don't close sheet on error
                              }

                              if (!sheetCtx.mounted) return;
                              Navigator.pop(sheetCtx);
                            },
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              );
            },
          );
          return _DaySheetControllerDisposalScope(
            onDispose: disposeDaySheetControllers,
            child: daySheetContent,
          );
        },
      ).then((_) {
        _daySheetOpenOrOpening = false;
        sheetClosing = true;
        if (persistAsRestoration) {
          unawaited(AppRestorationService.instance.saveDaySheetState(null));
        }
        unawaited(
          SessionResumeService.clearResumeEntry(
            kind: _kSessionResumeKindDaySheet,
          ),
        );
        if (flowStudioTabVisited) {
          unawaited(CalendarPage._clearFlowStudioTransientState());
        }
      });

      _calendarDebugPrint('✅ Modal bottom sheet opened successfully');
    } catch (e, stackTrace) {
      _calendarDebugPrint('');
      _calendarDebugPrint('❌ ERROR OPENING DAY SHEET');
      _calendarDebugPrint('Error: $e');
      _calendarDebugPrint('Stack trace: $stackTrace');
      _calendarDebugPrint('');
      _daySheetOpenOrOpening = false;
      sheetClosing = true;
      disposeDaySheetControllers();
      if (persistAsRestoration) {
        unawaited(AppRestorationService.instance.saveDaySheetState(null));
      }
      unawaited(
        SessionResumeService.clearResumeEntry(
          kind: _kSessionResumeKindDaySheet,
        ),
      );
      if (flowStudioTabVisited) {
        unawaited(CalendarPage._clearFlowStudioTransientState());
      }
    }
  }

  /* ───── Natural language quick add ───── */

  void _observeOptimisticNoteSave<T>(Future<T> save) {
    unawaited(() async {
      try {
        await save;
      } catch (e, stackTrace) {
        if (kDebugMode) {
          _calendarDebugPrint('[SaveNote] optimistic save failed: $e');
          _calendarDebugPrint('$stackTrace');
        }
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Failed to save note: $e'),
            backgroundColor: Colors.red,
            duration: const Duration(seconds: 3),
          ),
        );
      }
    }());
  }

  Future<void> _openQuickAddSheet() async {
    if (_quickAddSheetOpenOrOpening) return;
    _quickAddSheetOpenOrOpening = true;
    try {
      await showModalBottomSheet(
        context: context,
        isScrollControlled: true,
        backgroundColor: Colors.transparent,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
        ),
        builder: (_) => _QuickAddSheet(
          parse: CalendarPage.parseQuickAddText,
          scaffoldMessengerContext: context,
          onSave: (parsed, color) async {
            final k = KemeticMath.fromGregorian(parsed.date);
            await _saveSingleNoteOnly(
              selYear: k.kYear,
              selMonth: k.kMonth,
              selDay: k.kDay,
              title: parsed.title,
              detail: null,
              location: parsed.location,
              allDay: parsed.allDay,
              startTime: parsed.allDay ? null : parsed.start,
              endTime: parsed.allDay ? null : parsed.end,
              color: color,
              alertMinutesBefore: _alertNoneMinutes,
            );
          },
          onOpenJournal: _openJournalFromAppBar,
          onOpenPlanner: _openPlannerPage,
          onOpenFullEditor: () {
            if (!mounted) return;
            _openDaySheet(
              _today.kYear,
              _today.kMonth,
              _today.kDay,
              allowDateChange: true,
            );
          },
        ),
      );
    } finally {
      _quickAddSheetOpenOrOpening = false;
    }
  }

  /* ───── UI ───── */
  bool _initOnce = false;

  Future<void> _requestStartupRun({String reason = 'queued'}) async {
    final user = Supabase.instance.client.auth.currentUser;
    if (user == null) {
      _pendingInitialHydration = true;
      return;
    }
    _pendingInitialHydration = false;
    if (!mounted) return;
    _startOrCoalesceStartup(reason);
    if (_startupFlight != null && !(_startupFlight!.isCompleted)) {
      await _startupFlight!.future;
    }
  }

  static const List<Duration> _startupRecoveryBackoff = <Duration>[
    Duration(seconds: 1),
    Duration(seconds: 2),
    Duration(seconds: 4),
    Duration(seconds: 8),
    Duration(seconds: 15),
  ];

  void _cancelStartupRecovery({bool resetAttempt = true}) {
    _startupRecoveryTimer?.cancel();
    _startupRecoveryTimer = null;
    if (resetAttempt) _startupRecoveryAttempt = 0;
  }

  void _scheduleStartupRecovery({
    required String userId,
    required String reason,
  }) {
    if (!mounted || _activeWarmStartUserId() != userId) return;
    if (_startupRecoveryTimer?.isActive ?? false) return;
    final delay =
        _startupRecoveryBackoff[math.min(
          _startupRecoveryAttempt,
          _startupRecoveryBackoff.length - 1,
        )];
    _startupRecoveryAttempt++;
    _startupRecoveryTimer = Timer(delay, () {
      _startupRecoveryTimer = null;
      if (!mounted || _activeWarmStartUserId() != userId) return;
      unawaited(
        _requestStartupRun(
          reason: 'recovery_${_startupRecoveryAttempt}_$reason',
        ),
      );
    });
  }

  void _retryStartupNow({required String reason}) {
    _cancelStartupRecovery(resetAttempt: false);
    unawaited(_requestStartupRun(reason: reason));
  }

  void _startOrCoalesceStartup(String reason) {
    CalendarHydrationDiagnostics.instance.recordPostProcessing(
      null,
      'startup_pipeline_requested',
      fields: <String, Object?>{'reason': reason},
    );
    // Coalesce concurrent auth-driven runs; allow one rerun after the current flight.
    if (_startupFlight != null && !(_startupFlight!.isCompleted)) {
      CalendarHydrationDiagnostics.instance.recordPostProcessing(
        null,
        'startup_pipeline_coalesced',
        fields: <String, Object?>{'reason': reason},
      );
      _startupRerunRequested = true;
      _startupLastReason = reason;
      if (kDebugMode) {
        _calendarDebugPrint('[startup] coalesce request reason=$reason');
      }
      return;
    }

    final flight = Completer<void>();
    _startupFlight = flight;
    _startupLastReason = reason;
    _startupRerunRequested = false;
    if (kDebugMode) {
      _calendarDebugPrint('[startup] start reason=$reason');
    }
    () async {
      try {
        await _startHydrationEngine(reason);
      } catch (e, st) {
        _calendarDebugPrint('[startup] failed: $e');
        final userId = _activeWarmStartUserId();
        if (userId != null) {
          _scheduleStartupRecovery(
            userId: userId,
            reason: 'pipeline_exception',
          );
        }
        if (kDebugMode) {
          _calendarDebugPrint('$st');
        }
      } finally {
        flight.complete();
        _startupFlight = null;
        final authority = _hydrationController.state.authority;
        final visibleAuthorityEstablished =
            authority == CalendarViewportAuthority.serverCurrent ||
            authority == CalendarViewportAuthority.fullHorizon;
        if (_startupRerunRequested && !visibleAuthorityEstablished) {
          final nextReason = 'rerun_after_${_startupLastReason ?? reason}';
          _startupRerunRequested = false;
          _startOrCoalesceStartup(nextReason);
        } else {
          _startupRerunRequested = false;
          if (kDebugMode) {
            _calendarDebugPrint('[startup] end reason=$reason');
          }
        }
      }
    }();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();

    // ✅ Subscribe to RouteObserver FIRST (before _initOnce check)
    final route = ModalRoute.of(context);
    if (route is PageRoute && !_isSubscribed) {
      routeObserver.subscribe(this, route);
      _isSubscribed = true;
    }

    if (_debugDaySheetSmokeEnabled) {
      _scheduleDebugDaySheetSmoke();
      return;
    }

    // ✅ PRESERVE existing _initOnce logic
    if (!_initOnce) {
      _initOnce = true;

      // 1) Load reminder rules + schedule their instances, then load flows/events
      final user = Supabase.instance.client.auth.currentUser;
      if (user != null) {
        if (widget.initialFlowIdToEdit == null &&
            !widget.openMyFlowsOnLaunch &&
            !_sharedCalendarRealDayViewOpening &&
            CalendarPage._pendingDetachedLaunchAction == null &&
            CalendarPage._pendingDetachedSearchResult == null &&
            CalendarPage._pendingDetachedSearchDay == null) {
          _schedulePersistentOverlayRestore(reason: 'init-early');
        }
        if (_sharedCalendarRealDayViewOpening) {
          return;
        }
        _requestInitialStartupRun(reason: 'init').then((_) {
          final targetFlowId = widget.initialFlowIdToEdit;
          if (!mounted) return;
          if (targetFlowId != null) {
            _openFlowEditorDirectly(targetFlowId);
          } else if (widget.openMyFlowsOnLaunch) {
            _openMyFlowsList();
          } else if (_schedulePendingStagedFlowDayViewIfAny()) {
            return;
          } else if (!_schedulePendingDetachedLaunchActionIfAny()) {
            _schedulePersistentOverlayRestore(reason: 'init');
          }
        });
      } else {
        _pendingInitialHydration = true;
        if (kDebugMode) {
          _calendarDebugPrint(
            '[Calendar] Deferring initial hydrate until auth session is available',
          );
        }
      }
    } else if (widget.initialFlowIdToEdit != null) {
      // Already initialized (flows loaded), but widget has an initial flow id
      // e.g., if CalendarPage got rebuilt with a different target flow
      final targetFlowId = widget.initialFlowIdToEdit;
      if (targetFlowId != null) {
        _openFlowEditorDirectly(targetFlowId);
      }
    } else if (widget.openMyFlowsOnLaunch) {
      // If already initialized and caller requested My Flows, honor it.
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _openMyFlowsList();
      });
    } else {
      if (!_schedulePendingStagedFlowDayViewIfAny()) {
        _schedulePendingDetachedLaunchActionIfAny();
      }
    }

    if (!_sharedCalendarRealDayViewOpening &&
        _pendingInitialHydration &&
        Supabase.instance.client.auth.currentUser != null) {
      _requestInitialStartupRun(reason: 'init-pending').then((_) {
        if (!mounted ||
            widget.initialFlowIdToEdit != null ||
            widget.openMyFlowsOnLaunch) {
          return;
        }
        if (_schedulePendingStagedFlowDayViewIfAny()) {
          return;
        }
        if (!_schedulePendingDetachedLaunchActionIfAny()) {
          _schedulePersistentOverlayRestore(reason: 'init-pending');
        }
      });
    }

    // The detached `/flows` route can close before a Calendar host exists.
    // Stage the join immediately, then consume again after startup as a safety
    // net so a cold host cannot drop the Day View intent.
    _schedulePendingStagedFlowDayViewIfAny();
  }

  Future<void> _startHydrationEngine(String reason) async {
    final user = Supabase.instance.client.auth.currentUser;
    if (user == null) {
      if (kDebugMode) {
        _calendarDebugPrint(
          '[startup] abort: no authenticated user reason=$reason',
        );
      }
      return;
    }
    await _restoreWarmStartCacheIfAvailable(reason: 'startup_gate:$reason');
    await _restoreDurablePendingNotesForUser(user.id);
    await _restoreMyFlowsFilingSnapshotCache(reason: 'startup:$reason');
    if (!mounted) return;
    final viewport = _computeStartupVisibleHydrationInterval();
    _hydrationController.reportViewport(viewport);

    // A warm catalog can refresh the exact viewport immediately. This result
    // is deliberately provisional until a fresh catalog fingerprint agrees.
    if (_flows.isNotEmpty || _warmStartSnapshotVisible) {
      await _requestHydration(
        _CalendarHydrationRequest.provisionalViewport(
          reason: 'startup_$reason',
          interval: viewport,
        ),
      );
    }
    if (!mounted || _activeWarmStartUserId() != user.id) return;

    // Fresh catalog reconciliation is the authority boundary. If the catalog
    // changed, this same job refetches both viewport lanes with the new IDs and
    // commits catalog + lanes atomically.
    final reconcile = await _requestHydration(
      _CalendarHydrationRequest.catalogReconcile(
        reason: 'startup_$reason',
        interval: viewport,
      ),
    );
    if (reconcile != CalendarHydrationJobDisposition.completed ||
        !mounted ||
        _activeWarmStartUserId() != user.id ||
        (_hydrationController.state.authority !=
                CalendarViewportAuthority.serverCurrent &&
            _hydrationController.state.authority !=
                CalendarViewportAuthority.fullHorizon)) {
      if (mounted && _activeWarmStartUserId() == user.id) {
        _scheduleStartupRecovery(
          userId: user.id,
          reason: 'visible_authority_not_established',
        );
      }
      return;
    }

    _cancelStartupRecovery();

    // Foreground work ends at fresh visible authority. Horizon and maintenance
    // jobs continue on the serialized scheduler without delaying the UI.
    unawaited(
      _runBackgroundHydration(
        userId: user.id,
        reason: reason,
        focusWindow: (startUtc: viewport.startUtc, endUtc: viewport.endUtc),
      ),
    );
  }

  String _horizonDiagnosticSource({
    required String reason,
    required int chunkIndex,
  }) => 'horizon_chunk:$reason:$chunkIndex';

  Future<void> _runBackgroundHydration({
    required String userId,
    required String reason,
    required CalendarHydrationWindow focusWindow,
  }) async {
    await _scheduleCalendarStateRefresh(
      reason: 'post_viewport_calendar_state:$reason',
    );
    if (!mounted || _activeWarmStartUserId() != userId) return;
    await _scheduleMaintenanceJob(
      kind: CalendarHydrationIntentKind.onboardingMaintenance,
      reason: 'post_viewport_onboarding:$reason',
      dedupeKey: 'onboarding_presentation',
      priority: 25,
      run: () async {
        if (_onboardingPresentationScheduled) return;
        _onboardingPresentationScheduled = true;
        try {
          await _maybePresentOnboarding();
        } catch (_) {
          _onboardingPresentationScheduled = false;
          rethrow;
        }
      },
    );
    if (!mounted || _activeWarmStartUserId() != userId) return;
    await _scheduleMaintenanceJob(
      kind: CalendarHydrationIntentKind.journalMaintenance,
      reason: 'post_viewport_journal:$reason',
      dedupeKey: 'journal_initialization',
      priority: 25,
      run: () async {
        final ready = await _ensureJournalControllerReady();
        if (!ready) {
          throw StateError('journal initialization failed');
        }
      },
    );
    if (!mounted || _activeWarmStartUserId() != userId) return;
    final backfillComplete = await _hydrateFullHorizon(
      userId: userId,
      reason: reason,
      focusWindow: focusWindow,
    );
    if (!backfillComplete || !mounted || _activeWarmStartUserId() != userId) {
      return;
    }

    await _scheduleMaintenanceJob(
      kind: CalendarHydrationIntentKind.accounting,
      reason: 'post_horizon_accounting:$reason',
      dedupeKey: 'flow_accounting',
      run: _refreshHydrationAccounting,
    );
    await _scheduleMaintenanceJob(
      kind: CalendarHydrationIntentKind.reminderMaintenance,
      reason: 'post_horizon_reminders:$reason',
      dedupeKey: 'reminder_sync',
      run: () => _syncReminderEvents(refreshUi: false, updateLocalCache: false),
    );
    if (mounted &&
        _activeWarmStartUserId() == userId &&
        !_pendingInviteOverlayReady) {
      setState(() => _pendingInviteOverlayReady = true);
    }
    await _scheduleMaintenanceJob(
      kind: CalendarHydrationIntentKind.filing,
      reason: 'post_horizon_filing:$reason',
      dedupeKey: 'filing_snapshot',
      run: () async {
        await _loadMyFlowsFilingSnapshot();
      },
    );
    await _scheduleMaintenanceJob(
      kind: CalendarHydrationIntentKind.journalMaintenance,
      reason: 'post_horizon_reflection:$reason',
      dedupeKey: 'decan_reflection',
      run: _maybeLoadDecanReflectionPrompt,
    );
    _scheduleExpiredPendingCidVerification();
    await _scheduleMaintenanceJob(
      kind: CalendarHydrationIntentKind.invitationImport,
      reason: 'post_horizon_invites:$reason',
      dedupeKey: 'accepted_invite_imports',
      run: () => _syncAcceptedInviteCalendarImports(reason),
    );
  }

  Future<void> _refreshHydrationAccounting() async {
    final stopwatch = Stopwatch()..start();
    final result = await _flowsRepo.loadMyFlowEventCounts(
      flowIds: _flows.map((flow) => flow.id),
    );
    if (!mounted) return;
    final counts = result.value;
    final hasCachedCounts =
        counts.total.isNotEmpty || counts.remaining.isNotEmpty;
    final applyCounts = shouldApplyHydrationAccountingResult(
      status: result.status,
      hasCachedCounts: hasCachedCounts,
    );
    setState(() {
      if (applyCounts) {
        _flowTotalEventCounts
          ..clear()
          ..addAll(counts.total);
        _flowRemainingEventCounts
          ..clear()
          ..addAll(counts.remaining);
      }
      if (result.succeeded) {
        _lastAccountingAuthorityAt = DateTime.now();
        _accountingStale = false;
      } else {
        _accountingStale = true;
      }
    });
    _publishCalendarRefreshState();
    CalendarHydrationDiagnostics.instance.recordPostProcessing(
      null,
      'flow_counts_applied',
      durationMs: stopwatch.elapsedMilliseconds,
      countsApplied: applyCounts,
      fields: <String, Object?>{
        'status': result.status.diagnosticName,
        'counts_applied': applyCounts,
        'total_count_entries': counts.total.length,
        'remaining_count_entries': counts.remaining.length,
      },
    );
  }

  Future<CalendarHydrationJobDisposition> _scheduleMaintenanceJob({
    required CalendarHydrationIntentKind kind,
    required String reason,
    required Future<void> Function() run,
    String? dedupeKey,
    int priority = 20,
  }) {
    return _hydrationScheduler.schedule(
      CalendarHydrationJob(
        key: CalendarHydrationJobKey(kind: kind, reason: dedupeKey ?? reason),
        priority: priority,
        retryPolicy: const CalendarHydrationRetryPolicy(maxAttempts: 2),
        run: (context) async {
          context.throwIfCancelled('before_maintenance');
          await run();
          context.throwIfCancelled('after_maintenance');
        },
      ),
    );
  }

  Future<bool> _hydrateFullHorizon({
    required String userId,
    required String reason,
    required CalendarHydrationWindow focusWindow,
  }) async {
    final flowIndex = <int, _Flow>{for (final flow in _flows) flow.id: flow};
    final flowOwnersById = <int, FlowRecordSnapshot>{
      for (final flow in _flows)
        flow.id: FlowRecordSnapshot(
          id: flow.id,
          active: flow.active,
          isHidden: flow.isHidden,
          isReminder: flow.isReminder,
          isSaved: flow.isSaved,
          notes: flow.notes,
        ),
    };
    final hydrationFlowIds = _flows
        .where(
          (flow) =>
              !CalendarPage._isFlowEndSuppressed(flow.id) &&
              shouldHydrateMaterializedUserEvents(flowOwnersById[flow.id]!),
        )
        .map((flow) => flow.id)
        .toSet();
    final flowWindow = hydrationFlowIds.isEmpty
        ? focusWindow
        : _computeFlowHydrationWindow(hydrationFlowIds, flowIndex);
    final standaloneWindow = _computeStandaloneHydrationWindow(_flows);
    final unionStart = <DateTime>[
      flowWindow.startUtc,
      standaloneWindow.startUtc,
      focusWindow.startUtc,
    ].reduce((a, b) => a.isBefore(b) ? a : b);
    final unionEnd = <DateTime>[
      flowWindow.endUtc,
      standaloneWindow.endUtc,
      focusWindow.endUtc,
    ].reduce((a, b) => a.isAfter(b) ? a : b);
    final union = (startUtc: unionStart, endUtc: unionEnd);
    _hydrationController.setFullHorizon(
      CalendarHydrationInterval(startUtc: unionStart, endUtc: unionEnd),
    );
    final horizonFingerprint =
        _hydrationController.state.freshCatalogFingerprint ??
        _catalogFingerprintForCurrentFlows();
    final chunks = buildBackfillChunks(
      unionStart: unionStart,
      unionEnd: unionEnd,
      excludeWindow: focusWindow,
      chunkDays: 75,
    );
    final diagnostics = CalendarHydrationDiagnostics.instance;
    _lastWarmStartCacheSaveOutcome = null;
    await diagnostics.startBackfillSummary(
      userId: userId,
      focusStartUtc: focusWindow.startUtc,
      focusEndUtc: focusWindow.endUtc,
      unionStartUtc: unionStart,
      unionEndUtc: unionEnd,
      chunks: chunks,
    );
    if (chunks.isEmpty) {
      await _persistWarmStartCacheNow(
        userId: userId,
        debugReason: 'hydration_horizon_already_complete',
      );
      await diagnostics.finishBackfillSummary(
        userId: userId,
        fullHorizonComplete:
            _hydrationController.state.authority ==
            CalendarViewportAuthority.fullHorizon,
        cacheSaveEnded: _lastWarmStartCacheSaveOutcome != null,
        cacheSaveOutcome: _lastWarmStartCacheSaveOutcome,
      );
      return _hydrationController.state.authority ==
          CalendarViewportAuthority.fullHorizon;
    }

    for (var index = 0; index < chunks.length; index++) {
      if (!mounted || _activeWarmStartUserId() != userId) {
        await diagnostics.finishBackfillSummary(
          userId: userId,
          fullHorizonComplete: false,
          cacheSaveEnded: false,
          cancellationReason: 'user_changed',
        );
        return false;
      }
      if (_hydrationController.state.freshCatalogFingerprint !=
          horizonFingerprint) {
        return _hydrateFullHorizon(
          userId: userId,
          reason: '${reason}_catalog_rebased',
          focusWindow: focusWindow,
        );
      }
      final source = _horizonDiagnosticSource(
        reason: reason,
        chunkIndex: index,
      );
      final disposition = await _requestHydration(
        _CalendarHydrationRequest.background(
          reason: source,
          intentKind: CalendarHydrationIntentKind.horizonChunk,
          interval: CalendarHydrationInterval(
            startUtc: chunks[index].startUtc,
            endUtc: chunks[index].endUtc,
          ),
          catalogFingerprint: horizonFingerprint,
          union: CalendarHydrationInterval(
            startUtc: union.startUtc,
            endUtc: union.endUtc,
          ),
          chunkIndex: index,
          chunkCount: chunks.length,
          isFinalChunk: index == chunks.length - 1,
        ),
      );
      if (disposition == CalendarHydrationJobDisposition.cancelled) {
        // Foreground viewport work preempts between calls. Resume this exact
        // chunk afterward; interval-scoped commits make the retry idempotent.
        index--;
        continue;
      }
      if (disposition != CalendarHydrationJobDisposition.completed) {
        return false;
      }
    }

    final cacheOutcome = _lastWarmStartCacheSaveOutcome;
    return _hydrationAuthorityScope ==
            CalendarHydrationAuthorityScope.fullHorizon &&
        (cacheOutcome == 'saved' || cacheOutcome == 'compacted_and_saved');
  }

  Future<void> _syncAcceptedInviteCalendarImports(String reason) async {
    final diagnostics = CalendarHydrationDiagnostics.instance;
    final diagnosticWork = diagnostics.markAsyncWorkStarted(
      null,
      'invite_import_sync',
    );
    await (() async {
      final stopwatch = Stopwatch()..start();
      try {
        final changed = await ShareRepo(
          Supabase.instance.client,
        ).syncAcceptedInviteCalendarImports();
        if (!changed) {
          diagnostics.recordPostProcessing(
            null,
            'invite_import_sync_ended',
            durationMs: stopwatch.elapsedMilliseconds,
            token: diagnosticWork,
            fields: const <String, Object?>{'status': 'success_unchanged'},
          );
        }
        if (!changed) return;
        if (!mounted) {
          diagnostics.recordPostProcessing(
            null,
            'invite_import_sync_ended',
            durationMs: stopwatch.elapsedMilliseconds,
            token: diagnosticWork,
            fields: const <String, Object?>{
              'status': 'success_changed_unmounted',
            },
          );
          return;
        }
        await _refreshCalendarStateFromServer();
        if (!mounted) {
          diagnostics.recordPostProcessing(
            null,
            'invite_import_sync_ended',
            durationMs: stopwatch.elapsedMilliseconds,
            token: diagnosticWork,
            fields: const <String, Object?>{
              'status': 'success_changed_unmounted_after_apply',
            },
          );
          return;
        }
        CalendarInvalidationBus.instance.publish(
          const CalendarInvalidated(
            reason: CalendarInvalidationReason.calendarImportSynced,
          ),
        );
        diagnostics.recordPostProcessing(
          null,
          'invite_import_sync_ended',
          durationMs: stopwatch.elapsedMilliseconds,
          token: diagnosticWork,
          fields: const <String, Object?>{'status': 'success_changed'},
        );
      } catch (e, st) {
        diagnostics.recordPostProcessing(
          null,
          'invite_import_sync_ended',
          durationMs: stopwatch.elapsedMilliseconds,
          token: diagnosticWork,
          fields: <String, Object?>{
            'status': 'failed',
            'safe_error_class': e.runtimeType.toString(),
          },
        );
        if (kDebugMode) {
          _calendarDebugPrint('[startup] invite import sync failed: $e');
          _calendarDebugPrint('$st');
        }
      } finally {
        diagnostics.markAsyncWorkEnded(
          null,
          'invite_import_sync',
          token: diagnosticWork,
        );
      }
    }());
  }

  String? _canonicalDawnHouseRiteDetailForLoadedEvent({
    required _Flow? flow,
    required FlowEventRow event,
  }) {
    return canonicalDawnHouseRiteDetailTextForEvent(
      flowName: flow?.name,
      flowNotes: flow?.notes,
      title: event.title,
      actionId: event.actionId,
      behaviorPayload: event.behaviorPayload,
    );
  }

  String? _canonicalTheWeighingDetailForLoadedEvent({
    required _Flow? flow,
    required FlowEventRow event,
