  @visibleForTesting
  void debugSeedReminderRulesForTesting(
    List<ReminderRule> rules, {
    required DateTime windowEnd,
  }) {
    _reminderRules
      ..clear()
      ..addAll(rules);
    _flows.removeWhere((flow) => flow.isReminder);
    _reminderRulesLoaded = true;
    for (var index = 0; index < rules.length; index++) {
      final rule = rules[index];
      _flows.add(
        _Flow(
          id: 8100 + index,
          calendarId: rule.calendarId,
          name: rule.title,
          color: rule.color,
          active: rule.active,
          rules: const <FlowRule>[],
          start: rule.startLocal,
          end: rule.endLocal,
          notes: jsonEncode(rule.toJson()),
          isReminder: true,
          reminderUuid: rule.id,
        ),
      );
      _materializeReminderLocally(
        rule: rule,
        occurrences: _generateReminderOccurrences(
          rule,
          DateUtils.dateOnly(rule.startLocal),
          DateUtils.dateOnly(windowEnd),
        ),
        notify: false,
      );
    }
  }

